texts.002ab28d060f5faf38f24b2aa446ef07a3475f2b:
"""Pre-flight short-answer format reminder.

When the user's request explicitly requires a bare short answer, this hook adds
a one-time reminder immediately before the first LLM call. It is deliberately
tiny and bounded: it only fires once per task (turn 1) and only when the exact
benchmark instruction is present, so it adds a small, fixed prompt cost and
never loops or re-rolls.

The reminder repeats the user's output contract plus the canonical-surface-form
rule. For a small set of high-risk question shapes (definition/category,
"this type of X", "one of these/those", "these/those" category, and declarative
person-with-quoted-title clues), it appends one short question-shape directive.
The primary model remains the sole author of the final answer; this hook only
makes the output contract and question-shape guidance the most recent
instruction before the model's first attempt.
"""

from __future__ import annotations

import re
from typing import Any

_DEFINITION_START_RE = re.compile(r"^(?:[Aa]|[Aa]n|[Tt]he)\s+[a-z]")
_DEFINITION_MARKER_RE = re.compile(
    r"\b(?:the term for|this type of|type of|the crime for which|it's the)\b",
    re.IGNORECASE,
)
_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_THESE_THOSE_RE = re.compile(r"\b(?:these|those)\s+[A-Za-z]", re.IGNORECASE)
_PRONOUN_RE = re.compile(r"\b(?:he|she|his|her|him)\b", re.IGNORECASE)
_QUOTED_RE = re.compile(r'"[^"]+"')
_PERSON_ACTION_RE = re.compile(
    r"\b(?:he|she)\s+(?:wrote|published|created|made|invented|composed|sang|recorded|founded)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _shape_note(q: str) -> str | None:
    """Return a one-line question-shape directive for a high-risk clue type."""
    if not q:
        return None
    if _DEFINITION_MARKER_RE.search(q) or _DEFINITION_START_RE.match(q):
        return (
            "Question shape: definition/category clue. Return the general "
            "category term whose function the supplied context states, not a "
            "specific example sharing only one property. If the question asks "
            "for 'this type of X', return the specific named type the context "
            "states, not the general X."
        )
    if _ONE_OF_THESE_RE.search(q):
        return (
            "Question shape: 'one of these/those' clue. Return the category or "
            "entity that the quoted phrase describes; do not echo the quoted "
            "phrase."
        )
    if _PRONOUN_RE.search(q) and _QUOTED_RE.search(q):
        return (
            "Question shape: declarative person clue with a quoted title. "
            "Resolve 'he/his/her' to the person who performed the action and "
            "return that person's name exactly as the supplied context "
            "introduces it; do not return the quoted title or work."
        )
    if _PERSON_ACTION_RE.search(q):
        return (
            "Question shape: declarative sentence about a person. Return the "
            "person who performed the action, not the document, title, or "
            "object they produced; use the person's full name exactly as the "
            "context introduces it."
        )
    if _THESE_THOSE_RE.search(q):
        return (
            "Question shape: 'these/those' category clue. Return the shortest "
            "exact context noun for the group; do not repeat a qualifier that "
            "is already present in the question."
        )
    return None


async def before_llm(messages: list[dict], ctx: Any) -> list[dict]:
    """Append a one-turn format reminder when the task demands a bare answer."""
    if ctx.turn != 1:
        return messages
    if not _short_answer_requested(ctx.question):
        return messages

    note = _shape_note(_question_line(ctx.question))
    content = (
        "Format reminder: the user's request says \"Return only the short "
        "answer.\" Your final message must be exactly the requested answer "
        "phrase and nothing else. Copy the exact wording from the supplied "
        "context (spelling, capitalization, hyphens, and name extent). Do not "
        "add extra name components, titles, or qualifiers that the question "
        "does not ask for, and do not over-shorten a correct full name or drop "
        "an honorific. No sentence, lead-in, explanation, parenthetical, "
        "citation, markdown, quote, or trailing punctuation."
    )
    if note:
        content += " " + note

    reminder = {"role": "user", "content": content}
    return messages + [reminder]

texts.08f923ea7063190205007217c6844cf165a56114:
"""Deterministic short-answer surface cleaner.

This hook runs only for tasks whose instruction says to return only the short
answer. It removes generic surface wrappers that break exact-match scoring:
discourse lead-ins, parenthetical/bracket glosses, dash glosses, trailing
sentence punctuation, and wrapper articles. It then prefers the exact surface
form used by the supplied context, restores plural produce nouns, and extracts
the minimal head for bare role/title and pair/list clues.

It never calls a model and never changes the selected entity or term. All
edits are lexical and reversible by construction.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER = re.compile(r"^\[[^\]]*\]$")
_PAREN_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]*[\)\]]")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAILING_PUNCT_RE = re.compile(r"[.!?]+$")
_REPEATED_TRAILING_MARK_RE = re.compile(r"[!?]{2,}$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.[A-Za-z]\.?$")
_ARTICLE_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)
_OF_FROM_RE = re.compile(r"\b(of|from)\s+(.+)$", re.IGNORECASE)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|"
    r"berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|"
    r"why|how|his|her|he|she|him)\b",
    re.IGNORECASE,
)

_SHORT_FORM_MARKERS = (
    "term for",
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "mayor",
    "governor",
    "politician",
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-\.]*$")
_CATEGORY_SUFFIXES = (
    "party",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)
_TERM_OF_RE = re.compile(r"^(?P<head>[A-Za-z][A-Za-z'\-]*)\s+of\s+(?P<tail>.+)$")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _strip_bracket_wrappers(text: str) -> str:
    """Remove one matched pair of surrounding brackets/parentheses only when it
    wraps the whole phrase."""
    for open_ch, close_ch in (("(", ")"), ("[", "]")):
        if text.startswith(open_ch) and text.endswith(close_ch):
            inner = text[1:-1].strip()
            if inner and _norm_text(inner) == _norm_text(text):
                return inner
    return text


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized n-grams back to the surface phrases that produced them."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _phrase_quality(phrase: str) -> tuple:
    stripped = _strip_surrounding(phrase)
    bracket_penalty = sum(1 for ch in phrase if ch in "()[]")
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        stripped.count(" "),
        -stripped.count("-"),
        -bracket_penalty,
        len(stripped),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _echo_context_form(text: str, question: str) -> str:
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    key = _norm_text(text)
    if not key or key not in phrases:
        return text
    ctx = _context_text(question)
    best = _strip_surrounding(_best_phrase(phrases[key], ctx))
    return _strip_bracket_wrappers(best)


def _supported(phrase: str, question: str) -> bool:
    key = _norm_text(phrase)
    if not key:
        return False
    phrases, _ = _context_phrases(question)
    if key in phrases:
        return True
    return phrase.casefold() in question.casefold()


def _strip_parentheticals(text: str) -> str:
    cur = text
    for _ in range(8):
        nxt = _PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            cur = nxt
            continue
        break
    return cur


def _strip_dash_gloss(text: str, question: str) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _supported(before, question):
        return before
    return text


def _strip_lead(text: str) -> str:
    text = _LEAD_IN_RE.sub("", text).strip()
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail and len(tail.split()) >= 3:
            return tail
    return text


def _strip_trailing_punct(text: str) -> str:
    while True:
        match = _TRAILING_PUNCT_RE.search(text)
        if not match:
            return text
        if _ABBREV_RE.search(text):
            return text
        nxt = text[: match.start()].rstrip()
        if not nxt:
            return text
        text = nxt


def _strip_repeated_trailing_marks(text: str) -> str:
    """Drop doubled/repeated trailing ``!``/``?`` marks.

    The cleaner strips all trailing punctuation before re-echoing the context
    form. Some context titles carry doubled marks (``What's Happening!!``) and
    the most-frequent echo can re-add them. Removing only the *repeated* run
    preserves legitimate single-title marks while avoiding a re-added ``!!``
    that breaks exact match.
    """
    nxt = _REPEATED_TRAILING_MARK_RE.sub("", text).strip()
    return nxt or text


def _strip_leading_article(text: str, question: str) -> str:
    """Drop a wrapper article only when the article-less form is itself
    supported by the task text. Preserves canonical phrases that genuinely
    begin with an article (titles, brand names, works of art)."""
    match = _ARTICLE_RE.match(text)
    if not match:
        return text
    rest = match.group("rest").strip()
    if not rest:
        return text
    if _supported(rest, question) and not _supported(text, question):
        return rest
    return text


def _plural_candidates(word: str) -> list[str]:
    if not word or word.endswith("s"):
        return []
    candidates = []
    if re.search(r"[^aeiou]y$", word, re.IGNORECASE):
        candidates.append(word[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", word, re.IGNORECASE):
        candidates.append(word + "es")
    candidates.append(word + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question: str) -> str:
    if len(text.split()) != 1:
        return text
    q = _question_line(question)
    if not _PRODUCE_RE.search(q):
        return text
    word = _strip_surrounding(text)
    if not word or word.endswith("s"):
        return text
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    for candidate in _plural_candidates(word):
        key = _norm_text(candidate)
        if key and key in phrases:
            ctx = _context_text(question)
            return _strip_surrounding(_best_phrase(phrases[key], ctx))
    return text


def _capitalized_words(text: str) -> list[str]:
    return [t for t in re.findall(r"[A-Za-z][A-Za-z'\-]*", text)]


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _extract_minimal_head(text: str, question: str) -> str:
    match = _OF_FROM_RE.search(text)
    if not match:
        return text
    tail = match.group(2).strip().strip(" .,;:!?\"'`")
    tail = re.sub(r"^(?:the|a|an)\s+", "", tail, flags=re.IGNORECASE)
    run: list[str] = []
    for tok in tail.split():
        if tok and tok[0].isupper() and not tok[0].isdigit():
            run.append(tok)
        else:
            break
    if len(run) != 1:
        return text
    candidate = run[0]
    return _echo_context_form(candidate, question) or candidate



def _looks_person_short_form(q: str) -> bool:
    ql = q.lower()
    return bool(_PERSON_DEMO_RE.search(q)) and any(
        role in ql for role in _PERSON_ROLE_WORDS
    )


def _looks_factual_person_statement(q: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(q)) and not bool(_PERSON_DEMO_RE.search(q))


def _name_tokens(text: str) -> list[str]:
    run: list[str] = []
    for tok in text.split():
        bare = _strip_surrounding(tok)
        if _NAME_TOKEN_RE.match(bare):
            run.append(bare)
        else:
            break
    return run


def _extract_person_subject(text: str, question: str) -> str:
    q = _question_line(question)
    if not _looks_factual_person_statement(q):
        return text
    words = text.split()
    if len(words) <= 4:
        return text
    run = _name_tokens(text)
    if not run:
        return text
    # Do not truncate a compact name that already occupies the whole text.
    if len(run) == len(words):
        return text
    return " ".join(run)


def _extract_surname(text: str, question: str) -> str:
    q = _question_line(question)
    if not _looks_person_short_form(q):
        return text
    toks = text.split()
    if not (2 <= len(toks) <= 3):
        return text
    if not all(_NAME_TOKEN_RE.match(_strip_surrounding(tok)) for tok in toks):
        return text
    surname = _strip_surrounding(toks[-1])
    phrases, _ = _context_phrases(question)
    if _norm_text(surname) not in phrases:
        return text
    return _echo_context_form(surname, question) or surname


def _extract_term_head(text: str, question: str) -> str:
    q = _question_line(question)
    if "term for" not in q.lower():
        return text
    match = _TERM_OF_RE.match(text)
    if not match:
        return text
    head = match.group("head").strip()
    if not (head and _supported(head, question)):
        return text
    # For definition/term clues the context often carries the article as part
    # of the answer phrase ("a transit"). Prefer that exact phrase when present.
    phrases, _ = _context_phrases(question)
    for article in ("a", "an", "the"):
        key = _norm_text(f"{article} {head}")
        if key in phrases:
            ctx = _context_text(question)
            return _strip_surrounding(_best_phrase(phrases[key], ctx)) or head
    return _echo_context_form(head, question) or head


def _strip_trailing_category(text: str, question: str) -> str:
    q = _question_line(question).lower()
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return text
    toks = text.split()
    if len(toks) < 2:
        return text
    last = _strip_surrounding(toks[-1]).lower()
    if last not in _CATEGORY_SUFFIXES:
        return text
    prefix = " ".join(toks[:-1])
    # Only strip a category suffix when the remaining form is still a
    # multi-token phrase. A single-token remainder is often a distractor or
    # needs the side verifier to check it against the question constraints.
    if len(prefix.split()) < 2:
        return text
    if _supported(prefix, question):
        return _echo_context_form(prefix, question) or prefix
    return text

def _clean(text: str, question: str) -> str:
    t = _strip_lead(text)
    t = _strip_parentheticals(t)
    t = _strip_dash_gloss(t, question)
    t = _strip_leading_article(t, question)
    t = _strip_trailing_punct(t)
    t = " ".join(t.split())
    t = _echo_context_form(t, question)

    if _short_answer_requested(question):
        q = _question_line(question)
        t = _extract_person_subject(t, question)
        t = _extract_surname(t, question)
        t = _extract_term_head(t, question)
        t = _strip_trailing_category(t, question)
        t = _prefer_plural_produce_form(t, question)
        if _is_role_title_clue(q) or _is_pair_list_clue(q):
            t = _extract_minimal_head(t, question)
        t = _echo_context_form(t, question)
        t = _strip_repeated_trailing_marks(t)
    return t


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.164fcc0bc8262891d72e8046fb144fc4cefbf3bb:
"""Conservative deterministic short-answer surface cleaner.

Runs only when the task explicitly says to return only the short answer.
It performs lexical-only, context-gated normalization:

  * strip code fences and one matched pair of surrounding quotes
  * strip "answer is / answer:" lead-ins
  * strip True/False/Yes/No discourse lead-ins ("True — ...")
  * strip a trailing sentence period or repeated !/? only when the remaining
    phrase is supported verbatim by the supplied context
  * strip trailing parenthetical/bracket glosses only when the remaining
    phrase is a verbatim context phrase
  * strip trailing em/en-dash glosses only when the remaining phrase is a
    verbatim context phrase

For three recurring generic clue shapes it also reduces a verbose draft to
the requested head phrase, but only when the extracted phrase is itself a
verbatim context phrase:

  * factual-person statements ("he/his/her ...") -> leading name run
  * bare role/title clues ("President X", "Sultan Y") -> associated place
  * bare pair/list clues ("A,B") -> shared label after of/from/in

It never calls a model, never changes the selected entity, and deliberately
does NOT strip leading articles, shorten an organization/term to its first
word, or rewrite surface punctuation (case/hyphenation). Those decisions are
left to the bounded primary-model retry hook.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_ANSWER_LEAD_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s+(?P<gloss>.+)$", re.DOTALL)
_TRAILING_GLOSS_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]{0,120}[\)\]]\s*[.!?]*$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.([A-Za-z]\.)?$")
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

_DEF_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how)\b",
    re.IGNORECASE,
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|his|him|she|her|hers)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|whose)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


