                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
