"""Bounded primary-model self-correction for short-answer format failures.

After the deterministic cleaner runs, this hook asks the primary model for up
to two bounded attempts when the candidate still looks like prose, is a longer
context phrase whose shorter prefix is the requested form, is a full person name
for a Jeopardy-style person clue, or is a multi-word non-context draft. It is
deliberately conservative:

  * only tasks with an explicit "return only the short answer" instruction;
  * at most two continuations per task (the runtime's turn budget is checked);
  * clean compact context phrases are never re-rolled.

For over-expanded context phrases, the feedback now names the shorter context
phrase(s) so the primary model does not have to rediscover them.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "referred to as",
    "called it",
    "term for",
    "surname",
    "acronym",
    "pre-",
    "company",
    "network",
    "association",
    "organization",
    "organisation",
    "mint",
    "radio",
)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_PROSE_WORDS_RE = re.compile(
    r"\b(the|a|an|from|of|and|in|for|with|to|as|by|is|was|were|are)\b",
    re.IGNORECASE,
)
_LEAD_IN_RE = re.compile(
    r"^(true|false|yes|no|correct|right|answer|note|indeed)\b", re.IGNORECASE
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in (text or "").split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for seg in _MARKER_RE.split(ctx):
        toks = []
        for raw in seg.split():
            norm = _norm_token(raw)
            if norm:
                toks.append(norm)
        max_n = min(5, len(toks))
        for n in range(1, max_n + 1):
            for i in range(len(toks) - n + 1):
                keys.add("".join(toks[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, list[str]]:
    """Map normalized word n-grams back to their original context phrases."""
    ctx = _context_text(question)
    surfaces: dict[str, list[str]] = {}
    if not ctx:
        return surfaces
    for seg in _MARKER_RE.split(ctx):
        toks = [( _norm_token(raw), raw) for raw in seg.split() if _norm_token(raw)]
        max_n = min(5, len(toks))
        for n in range(1, max_n + 1):
            for i in range(len(toks) - n + 1):
                key = "".join(t[0] for t in toks[i : i + n])
                phrase = " ".join(t[1] for t in toks[i : i + n])
                bucket = surfaces.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return surfaces


def _prefer_surface(bucket: list[str]) -> str:
    """Prefer a title-case, punctuation-free surface form for feedback text."""
    if not bucket:
        return ""

    def quality(p: str) -> tuple:
        s = p.strip()
        trailing = len(s) - len(s.rstrip(" .,;:!?"))
        return (
            1 if not s.isupper() else 0,
            1 if s[:1].isupper() else 0,
            -trailing,
            len(s),
        )

    return max(bucket, key=quality).strip(" .,;:!?")


def _prefix_alternatives(
    text: str, ctx_keys: set[str], surfaces: dict[str, list[str]]
) -> list[str]:
    """Return shorter context phrases that are strict token prefixes of ``text``."""
    words = text.split()
    if len(words) < 2:
        return []
    alternatives: list[str] = []
    seen: set[str] = set()
    for n in range(len(words) - 1, 0, -1):
        key = _norm_text(" ".join(words[:n]))
        if key in ctx_keys:
            phrase = _prefer_surface(surfaces.get(key, []))
            if phrase and _norm_text(phrase) not in seen:
                alternatives.append(phrase)
                seen.add(_norm_text(phrase))
        if len(alternatives) >= 3:
            break
    return alternatives


def _looks_like_prose(text: str, ctx_keys: set[str] | None = None) -> bool:
    words = text.split()
    if len(words) >= 6:
        return True
    if _LEAD_IN_RE.match(text):
        return True
    if len(words) >= 3:
        is_ctx = bool(ctx_keys) and _norm_text(text) in ctx_keys
        if is_ctx and not _SENTENCE_END_RE.search(text):
            return False
        if _SENTENCE_END_RE.search(text) or _PROSE_WORDS_RE.search(text):
            return True
    return False


def _looks_overexpanded(text: str, question: str, ctx_keys: set[str]) -> bool:
    """Compact context phrase that is longer than the requested short form."""
    q = _question_line(question).lower()
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False
    words = text.split()
    if len(words) < 3:
        return False
    full_key = _norm_text(text)
    if full_key not in ctx_keys:
        return False
    for n in range(len(words) - 1, 0, -1):
        prefix_key = _norm_text(" ".join(words[:n]))
        if prefix_key in ctx_keys:
            return True
    return False


def _looks_full_name_draft(text: str, question: str, ctx_keys: set[str]) -> bool:
    """Full first+last name for a Jeopardy-style 'this ...'/'whose ...' clue."""
    q = _question_line(question).lower()
    if _PERSON_PRONOUN_RE.search(q):
        return False
    if not _PERSON_DEMO_RE.search(q):
        return False
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return False

    words = text.split()
    if len(words) not in (2, 3):
        return False
    if not all(_NAME_TOKEN_RE.match(w) for w in words):
        return False
    surname_key = _norm_text(words[-1])
    return bool(surname_key and surname_key in ctx_keys)


def _looks_non_context(text: str, ctx_keys: set[str]) -> bool:
    words = text.split()
    if len(words) < 3:
        return False
    return _norm_text(text) not in ctx_keys


def _feedback(draft: str, alternatives: list[str] | None = None) -> str:
    message = (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare requested item.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item, then reply with only that item. Use the exact wording "
        "from the supplied context and the shortest form that still satisfies "
        "every clue (nickname, surname, term, acronym, or short label rather "
        "than a full name, title, date, or organization expansion). Do not "
        "include any explanation, lead-in, parenthetical, or punctuation that "
        "is not part of the requested item."
    )
    if alternatives:
        quoted = ", ".join(f"'{alt}'" for alt in alternatives)
        message += (
            "\n\nThe supplied context also contains the shorter phrase(s): "
            + quoted
            + ". Choose the shortest one that still satisfies every clue, and "
            "return only that phrase."
        )
    return message


def _person_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "This is a Jeopardy-style person clue, so the requested answer is the "
        "person's surname/target name only, not a full first+last name.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Return only the surname/target name exactly as the supplied context "
        "gives it, with no first name, dates, or extra words."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_retry"]
    fired = state.get("fired", 0)
    if fired >= 2:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    ctx_keys = _context_phrase_keys(ctx.question)

    if _looks_like_prose(original, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _feedback(original)}

    if _looks_full_name_draft(original, ctx.question, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _person_feedback(original)}

    if _looks_overexpanded(original, ctx.question, ctx_keys):
        alternatives = _prefix_alternatives(
            original, ctx_keys, _context_surfaces(ctx.question)
        )
        state["fired"] = fired + 1
        return {
            "action": "continue",
            "feedback": _feedback(original, alternatives),
        }

    if _looks_non_context(original, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _feedback(original)}

    return None

texts.45e3a113fc9dd1b395eee8305c5d1d003a824c6a:
"""Deterministic short-answer surface cleaner.

This hook runs only when the user explicitly requested a bare short answer
(``return only the short answer``). It removes generic surface wrappers that
break exact-match scoring and, for a few clue shapes, extracts the requested
minimal form. It never calls a model and never changes the chosen entity.

Covered operations (all reversible, lexical only):
  * code fences and matched surrounding quotes
  * "answer is / answer:" lead-ins
  * trailing sentence periods (initialisms are preserved)
  * trailing parenthetical/bracket glosses and short dash glosses
  * leading articles when the article-less form is a supplied context phrase
  * bare role/title and pair/list head extraction ("... of/from X")
  * produce/plant plural restoration ("Strawberry" -> "strawberries")
  * hyphenated acronym expansion ("Picture-in-picture" -> "Picture in Picture")
  * repeated title punctuation on pair/list clues ("What's Happening!!")
  * Jeopardy-style person-name shortening ("Jean Genet" -> "Genet")
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_TRAILING_PAREN_RE = re.compile(r"\s*\([^()]*\)\s*$")
_TRAILING_BRACKET_RE = re.compile(r"\s*\[[^\[\]]*\]\s*$")
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–-]\s+(?P<gloss>.+)$", re.DOTALL)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"his|her|he|she|him|whose)\b",
    re.IGNORECASE,
)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_ARTICLE_LEAD_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)

_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(
    r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE
)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in (text or "").split() if _norm_token(t))


def _segments(ctx: str) -> list[str]:
    return [p.strip() for p in _MARKER_RE.split(ctx) if p.strip()]


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to original context surface forms."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    for seg in _segments(ctx):
        toks: list[tuple[str, str]] = []
        for raw in seg.split():
            norm = _norm_token(raw)
            if norm:
                toks.append((norm, raw))
        max_n = min(5, len(toks))
        for n in range(1, max_n + 1):
            for i in range(len(toks) - n + 1):
                key = "".join(t[0] for t in toks[i : i + n])
                phrase = " ".join(t[1] for t in toks[i : i + n])
                counts[phrase] = counts.get(phrase, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _best_phrase(bucket: list[str], counts: dict[str, int]) -> str:
    """Pick the dominant context surface form for a normalized key.

    Trailing sentence punctuation is penalized so ``Sirius Satellite Radio,``
    is not chosen over the cleaner ``Sirius Satellite Radio`` form.
    """
    if not bucket:
        return ""

    def quality(p: str) -> tuple:
        stripped = p.strip()
        trailing = len(stripped) - len(stripped.rstrip(" .,;:!?"))
        return (
            counts.get(p, 0),
            1 if stripped.count(" ") > 0 else 0,
            -p.count("-"),
            -trailing,
            len(stripped),
        )

    return max(bucket, key=quality)


def _strip_code_fences(text: str) -> str:
    text = (text or "").strip()
    if text.startswith("```") and text.endswith("```") and len(text) > 6:
        inner = text[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            text = inner
    return text.strip()


def _strip_outer_quotes(text: str) -> str:
    text = (text or "").strip()
    for quote in ('"', "'", "`"):
        if (
            len(text) >= 2
            and text.startswith(quote)
            and text.endswith(quote)
        ):
            inner = text[1:-1].strip()
            if inner:
                text = inner
                break
    return text.strip()


def _strip_lead_in(text: str) -> str:
    return _LEAD_IN_RE.sub("", (text or "").strip()).strip()


def _strip_leading_article(text: str) -> str:
    """Return the article-less form without changing any other token."""
    match = _ARTICLE_LEAD_RE.match((text or "").strip())
    return match.group("rest").strip() if match else (text or "").strip()


def _resolved_context_form(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str | None:
    """Return the context's surface form for ``text`` if one exists.

    Also accepts the article-less form of ``text``, so a draft like ``A well``
    can resolve to the context's ``well`` when ``A well`` is not itself a
    supplied phrase. Surrounding punctuation is removed from the returned
    context phrase so wrappers such as ``(SiriusXM)`` never leave a comma
    behind.
    """
    key = _norm_text(text)
    if key and key in phrases:
        bucket = phrases[key]
        stripped = (text or "").strip().strip(" .,;:!?\"'`")
        for phrase in bucket:
            if phrase.strip(" .,;:!?\"'`") == stripped:
                return stripped
        return _best_phrase(bucket, counts).strip(" .,;:!?\"'`")
    bare = _strip_leading_article(text)
    if bare and bare != text:
        key = _norm_text(bare)
        if key and key in phrases:
            return _best_phrase(phrases[key], counts).strip(" .,;:!?\"'`")
    return None


def _strip_trailing_period(text: str, phrases: dict[str, list[str]]) -> str:
    """Drop one sentence-final period, preserving abbreviations/initialisms."""
    cur = (text or "").strip()
    if not (cur.endswith(".") and not cur.endswith("..") and len(cur) > 1):
        return cur

    # Initialisms and common abbreviations keep their final period.
    if re.search(r"\b[A-Za-z](\.[A-Za-z])+\.?$", cur):
        return cur
    if re.match(r"^[A-Za-z]\.$", cur):
        return cur
    if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", cur, re.IGNORECASE):
        return cur

    nxt = cur[:-1].rstrip()
    if not nxt:
        return cur

    # Strip when the character before the period is lowercase, a closing
    # bracket/paren/quote, or when the period-less text is a context phrase.
    # This catches both "Massachusetts." and "A well (a water well).".
    if (
        cur[-2].islower()
        or cur[-2] in ")]}\"'`"
        or _norm_text(nxt) in phrases
    ):
        return nxt
    return cur


def _strip_trailing_glosses(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str:
    cur = (text or "").strip()
    for _ in range(5):
        prev = cur

        nxt = _TRAILING_PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            resolved = _resolved_context_form(nxt, phrases, counts)
            if resolved:
                cur = resolved
                continue

        nxt = _TRAILING_BRACKET_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            resolved = _resolved_context_form(nxt, phrases, counts)
            if resolved:
                cur = resolved
                continue

        match = _DASH_GLOSS_RE.search(cur)
        if match:
            before = cur[: match.start()].strip()
            gloss = match.group("gloss").strip()
            resolved = _resolved_context_form(before, phrases, counts)
            if (
                before
                and gloss
                and len(gloss.split()) <= 8
                and resolved
            ):
                cur = resolved
                continue
        break
    return cur


def _capitalized_words(text: str) -> list[str]:
    return re.findall(r"[A-Za-z][A-Za-z'\-]*", text or "")


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _echo_context_form(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str:
    key = _norm_text(text)
    if key and key in phrases:
        return _best_phrase(phrases[key], counts)
    return text


def _extract_head(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    """Extract a single proper-noun head after ``of``/``from`` for bare
    role/title and pair/list clues. Longer proper-name runs are left intact."""
    q = _question_line(question)
    if not (_is_role_title_clue(q) or _is_pair_list_clue(q)):
        return text
    match = re.search(
        r"\b(?:of|from)\s+(?:(?:the|a|an)\s+)?([A-Z][A-Za-z'.\-]*)", text
    )
    if not match:
        return text
    head = match.group(1)
    rest = text[match.end() :].strip()
    next_token = rest.split()[0] if rest else ""
    if next_token and next_token[0].isupper():
        return text
    return _echo_context_form(head, phrases, counts)


def _plural_forms(word: str) -> list[str]:
    if not word:
        return []
    forms: list[str] = []
    if (
        len(word) > 1
        and word[-1].lower() == "y"
        and word[-2].lower() not in "aeiou"
    ):
        forms.append(word[:-1] + "ies")
    forms.append(word + "s")
    return forms


def _prefer_produce_plural(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if len(text.split()) != 1:
        return text
    if not _PRODUCE_RE.search(_question_line(question)):
        return text
    word = text.strip().strip(" .,;:!?\"'`")
    if not word or not word[:1].isupper():
        return text
    for form in _plural_forms(word):
        key = _norm_text(form)
        if key and key in phrases:
            return _best_phrase(phrases[key], counts)
    return text


def _fix_hyphenated_acronym(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if "-" not in text:
        return text
    acronyms = re.findall(r"\b[A-Z]{2,6}\b", _question_line(question))
    if not acronyms:
        return text
    key = _norm_text(text)
    if key not in phrases:
        return text
    words = text.replace("-", " ").split()
    if len(words) < 2:
        return text
    initials = "".join(w[0] for w in words).lower()
    for acr in acronyms:
        if acr.lower() != initials:
            continue
        candidates = [
            p
            for p in phrases[key]
            if "-" not in p and len(p.split()) == len(words)
        ]
        if not candidates:
            continue
        best = _best_phrase(candidates, counts)
        if best and best != text:
            return best
    return text


def _strip_title_bangs(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if not _is_pair_list_clue(_question_line(question)):
        return text
    if not re.search(r"[!?]{2,}$", (text or "").strip()):
        return text
    key = _norm_text(text)
    if key not in phrases:
        return text
    candidates = [p for p in phrases[key] if not re.search(r"[!?]{1,}$", p.strip())]
    if not candidates:
        return text
    return _best_phrase(candidates, counts)


def _shorten_person_name(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    """Shorten a full name to the surname/target for a Jeopardy-style person
    clue when the surname appears alone in the supplied context.

    Factual statements (``he/his/her ...``) are excluded because they usually
    want the full name exactly as the context introduces it.
    """
    q = _question_line(question).lower()
    if _PERSON_PRONOUN_RE.search(q):
        return text
    if not _PERSON_DEMO_RE.search(q):
        return text
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return text

    words = text.split()
    if len(words) not in (2, 3):
        return text
    if not all(_NAME_TOKEN_RE.match(w) for w in words):
        return text

    surname = words[-1]
    key = _norm_text(surname)
    if key and key in phrases:
        return _best_phrase(phrases[key], counts)
    return text


def _clean(text: str, question: str) -> str:
    phrases, counts = _context_phrases(question)

    t = _strip_code_fences(text)
    t = _strip_outer_quotes(t)
    t = _strip_lead_in(t)

    # Strip a sentence-final period before gloss removal so patterns such as
    # "A well (a water well)." can be unwrapped one layer at a time.
    t = _strip_trailing_period(t, phrases)
    t = _strip_trailing_glosses(t, phrases, counts)

    q = _question_line(question)
    if _is_role_title_clue(q) or _is_pair_list_clue(q):
        t = _extract_head(t, question, phrases, counts)

    t = _prefer_produce_plural(t, question, phrases, counts)
    t = _fix_hyphenated_acronym(t, question, phrases, counts)
    t = _strip_title_bangs(t, question, phrases, counts)
    t = _shorten_person_name(t, question, phrases, counts)

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        return {"action": "replace", "answer": cleaned}
    return None

texts.4615c4a1a33238d6cfcb11d142a883a3dc7b1e4a:
"""Bounded side-LLM verifier for short-answer QA.

Runs after the deterministic cleaner. For suspicious multi-token drafts it asks
a side model to re-derive the exact context phrase that satisfies every clue.
It only replaces the draft when the side output is a verbatim phrase from the
supplied context and is not longer than the draft. At most one side call is made
per task, with an explicit exit condition.

When the side model cannot produce a context-backed correction, the hook leaves
a typed `unresolved` status in shared middleware state so the later bounded
primary retry can escalate with constraint-focused feedback. This keeps the
side check cheap while giving wrong-entity and disambiguation failures one more
bounded chance through the primary model.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER = re.compile(r"^\[[^\]]*\]$")
_SHORT_FORM_MARKERS = (
    "term for",
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "pre-",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "mayor",
    "governor",
    "politician",
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_DEFINITION_RE = re.compile(
    r"^(?:an?|the)\s+[a-z]",
    re.IGNORECASE,
)
_DEFINITION_VERB_RE = re.compile(
    r"\b(applied|used|known|called|termed|named|designed|worn)\b",
    re.IGNORECASE,
)
_DIGIT_RE = re.compile(r"\d")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _phrase_quality(phrase: str) -> tuple:
    stripped = _strip_surrounding(phrase)
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        stripped.count(" "),
        -stripped.count("-"),
        len(stripped),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _looks_person_short_form(q: str) -> bool:
    ql = q.lower()
    if not _PERSON_DEMO_RE.search(q):
        return False
    return any(role in ql for role in _PERSON_ROLE_WORDS)


def _looks_definition_clue(q: str) -> bool:
    return bool(_DEFINITION_RE.match(q)) and bool(_DEFINITION_VERB_RE.search(q))


def _looks_numeric_person(q: str) -> bool:
    ql = q.lower()
    if not _DIGIT_RE.search(q):
        return False
    return any(role in ql for role in _PERSON_ROLE_WORDS)


def _should_verify(q: str, in_context: bool) -> bool:
    if not in_context:
        return True
    ql = q.lower()
    if any(marker in ql for marker in _SHORT_FORM_MARKERS):
        return True
    if _looks_person_short_form(q):
        return True
    if _looks_numeric_person(q):
        return True
    if _looks_definition_clue(q):
        return True
    return False


def _is_keep_response(text: str) -> bool:
    t = (text or "").strip().strip("\"'`").lower()
    return t in {"keep", "keep."} or t.startswith("keep ")


def _clean_side_output(text: str, phrases: dict[str, list[str]]) -> str | None:
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines:
        return None
    cleaned_lines: list[str] = []
    for raw in lines:
        out = raw.strip().strip("\"'`").strip()
        out = re.sub(
            r"^(?:answer\s*(?:is|:)?\s*)", "", out, flags=re.IGNORECASE
        ).strip()
        if not out:
            continue
        if out.lower().strip(" .") == "keep" or out.lower().startswith("keep"):
            return None
        cleaned_lines.append(out)
        if _norm_text(out) in phrases:
            return out
    if not cleaned_lines:
        return None
    last = cleaned_lines[-1]
    return last if _norm_text(last) in phrases else None


def _prompt(question: str, draft: str) -> str:
    return (
        "You are checking a short-answer QA draft. Use ONLY the supplied context below.\n\n"
        + question
        + "\n\nDraft answer:\n"
        + draft
        + "\n\n"
        "Check the draft against every clue in the question.\n"
        "If the draft already satisfies every clue, return exactly KEEP.\n"
        "Otherwise, find the exact phrase in the supplied context that satisfies "
        "every clue and return that phrase.\n\n"
        "Rules:\n"
        "- Prefer the passage that states every number, date, denomination, "
        "function, or relationship in the question.\n"
        "- For a definition clue (for example 'An X that does Y'), return the "
        "general category/term whose function is stated, not a salient example.\n"
        "- For a Jeopardy-style 'this ...' or 'whose ...' clue, return the "
        "shortest blank-filling phrase from the context (nickname, term, surname, "
        "acronym, or short company/network/mint/association name), not a full "
        "name or title expansion.\n"
        "- For a factual statement about a person ('he/his/her ...'), return the "
        "person's full name exactly as the context introduces it.\n"
        "- Preserve the exact spelling, capitalization, hyphenation, number, and "
        "articles of the context phrase.\n"
        "- Return only KEEP or the corrected answer string. No explanation, "
        "quotes, or formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Replace a suspicious multi-token draft only with a context-backed answer."""
    if not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_verify"]
    if state.get("fired", 0) >= 1:
        return None

    original = (candidate or "").strip()
    if len(original.split()) < 2:
        return None

    phrases, _ = _context_phrases(ctx.question)
    if not phrases:
        return None

    q = _question_line(ctx.question)
    original_key = _norm_text(original)
    in_context = original_key in phrases
    if not _should_verify(q, in_context):
        return None

    state["fired"] = 1
    try:
        side = await ctx.side_text(
            _prompt(ctx.question, original),
            purpose="short_answer_verify",
            max_tokens=80,
        )
    except Exception as e:
        ctx.trace.event("short_answer_verify_error", error=str(e))
        state["unresolved"] = "side_unavailable"
        return None
    if not side:
        state["unresolved"] = "side_unavailable"
        return None

    if _is_keep_response(side):
        state["unresolved"] = "keep"
        if _looks_numeric_person(q) or _looks_definition_clue(q):
            state["keep_risk"] = "high"
        return None

    side_clean = _clean_side_output(side, phrases)
    if not side_clean:
        state["unresolved"] = "non_context"
        return None

    side_key = _norm_text(side_clean)
    if side_key == original_key:
        state["unresolved"] = "keep"
        if _looks_numeric_person(q) or _looks_definition_clue(q):
            state["keep_risk"] = "high"
        return None
    if side_key not in phrases:
        state["unresolved"] = "non_context"
        return None

    ctx_text = _context_text(ctx.question)
    cleaned = _strip_surrounding(_best_phrase(phrases[side_key], ctx_text))
    cleaned_key = _norm_text(cleaned)
    if cleaned_key == original_key:
        state["unresolved"] = "keep"
        if _looks_numeric_person(q) or _looks_definition_clue(q):
            state["keep_risk"] = "high"
        return None
    if len(cleaned.split()) > len(original.split()):
        ctx.trace.event(
            "short_answer_verify_rejected",
            reason="side_longer_than_draft",
            draft=original,
            side=cleaned,
        )
        state["unresolved"] = "side_longer"
        return None

    ctx.trace.event(
        "short_answer_verify_replace",
        draft=original,
        replacement=cleaned,
    )
    state["unresolved"] = "replaced"
    return {"action": "replace", "answer": cleaned}

texts.46e0a20a13ddb7aef0c98f3828fe624f75e448ac:
"""Pre-flight short-answer output-contract and question-shape reminder.

When the user's request explicitly requires a bare short answer, this hook adds
a one-time reminder immediately before the first LLM call. The reminder repeats
the user's output contract plus the canonical-surface-form rule, and appends one
short question-shape directive when the question matches a high-risk pattern
(definition/category, "one of these/those", or a bare quoted fragment). It is
deliberately tiny and bounded: it fires only once per task (turn 1) and only
when the exact benchmark instruction is present, so it adds a small, fixed
prompt cost and never loops or re-rolls.

The primary model remains the sole author of the final answer; this hook only
makes the output contract and the question-shape guidance the most recent
instruction before the model's first attempt.
"""

from __future__ import annotations

import re
from typing import Any

_DEFINITION_START_RE = re.compile(r"^(?:an?|the)\s+[a-z]", re.IGNORECASE)
_DEFINITION_MARKER_RE = re.compile(
    r"\b(?:the term for|this type of|type of|the crime for which|it's the)\b",
    re.IGNORECASE,
)
_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_FRAGMENT_RE = re.compile(r'^"(?:\.\.\.)?[^"]*"$')


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _is_definition_category_clue(q: str) -> bool:
    if not q:
        return False
    if _DEFINITION_MARKER_RE.search(q):
        return True
    return bool(_DEFINITION_START_RE.match(q))


def _shape_note(q: str) -> str | None:
    if not q:
        return None
    if _is_definition_category_clue(q):
        return (
            "Question shape: this is a definition/category clue. Return the "
            "general category term whose function the supplied context states, "
            "not a salient example that shares only one property."
        )
    if _ONE_OF_THESE_RE.search(q):
        return (
            "Question shape: this is a 'one of these/those' clue. Name the "
            "category or entity described by the quoted phrase, using the exact "
            "context wording; do not echo the quoted phrase."
        )
    if _QUOTED_FRAGMENT_RE.match(q.strip()):
        return (
            "Question shape: this is a bare quoted-fragment clue. Find the "
            "supplied context title or passage that contains the fragment as a "
            "contiguous phrase and return the entity that completes or names "
            "that title; do not default to the most frequent matching article."
        )
    return None


async def before_llm(messages: list[dict], ctx: Any) -> list[dict]:
    """Append a one-turn format reminder when the task demands a bare answer."""
    if ctx.turn != 1:
        return messages
    if not _short_answer_requested(ctx.question):
        return messages

    note = _shape_note(_question_line(ctx.question))
    content = (
        "Format reminder: the user's request says \"Return only the short "
        "answer.\" Your final message must be exactly the requested answer "
        "phrase and nothing else. Copy the exact wording from the supplied "
        "context (spelling, capitalization, hyphens, and name extent). "
        "Keep full names and titles exactly as the context introduces them: "
        "do not shorten a correct full name to a surname or replace a name "
        "with an epithet. No sentence, lead-in, explanation, parenthetical, "
        "citation, markdown, quote, or trailing punctuation."
    )
    if note:
        content += " " + note

    reminder = {"role": "user", "content": content}
    return messages + [reminder]

texts.49a3ff47ca36149ec3165b377164d6edfb719c82:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic surface cleaner. It asks the *primary* model for
a bounded retry only when the cleaned candidate is still unlikely to satisfy a
bare exact-match short-answer instruction because it is:

  * prose-like (sentence-shaped or long enough that it cannot be a bare short
    answer), or
  * not a verbatim phrase from the supplied context, so it cannot be the
    exact-match answer copied from that context.

The primary model remains the only author of the final answer. The runtime's
remaining-turn and final-continue budgets bound every retry, and this hook has
its own hard cap, so it cannot loop.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\b", re.IGNORECASE
)
_ARTICLE_OPEN_RE = re.compile(r"^(?:a|an|the)\s+", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_LEADING_ARTICLE = {"a", "an", "the"}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _context_phrase_keys(question: str) -> set[str]:
    """Return chunk keys for every context n-gram up to five tokens."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(5, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                key = _chunk_key(" ".join(tokens[i : i + n]))
                if key:
                    keys.add(key)
    return keys


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _passages(question: str) -> list[str]:
    """Split the supplied context into [DOC]-bounded documents."""
    ctx = _context_text(question)
    passages: list[str] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if raw.strip():
            passages.append(raw)
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using every token would
    let a trailing category word (``Mint``, ``Company``, ``Network``) match a
    question restatement and hide the constraint gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.casefold() not in _LEADING_ARTICLE:
            return token
    return None


def _missing_amount_feedback(amounts: list[str], candidate: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        f"A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + candidate
        + "\n\n"
        f"Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


def _looks_like_prose(text: str) -> bool:
    """A bare short answer is compact; prose is not.

    This is intentionally conservative. It only fires when the candidate is
    clearly sentence-shaped (long, or containing sentence/gloss punctuation
    plus a discourse lead or article), so clean short phrases are never
    re-rolled.
    """
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 7:
        return True
    if len(words) >= 4 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    if (
        len(words) == 2
        and _ARTICLE_OPEN_RE.match(text)
        and _SENTENCE_END_RE.search(text)
    ):
        return True
    return False


def _generic_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer or was not copied "
        "verbatim from the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from the "
        "supplied context. No lead-in, explanation, parenthetical, gloss, date, "
        "or extra punctuation."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    state = ctx.state["short_answer_retry"]
    fired = state.get("fired", 0)
    if fired >= 2:
        return None

    # Trigger 1: numeric constraint gap. If the question names a monetary
    # amount and the candidate's supporting document omits that amount while
    # another supplied document contains it, the model likely anchored on a
    # keyword-only distractor. Fire this before the generic non-context trigger
    # so the feedback names the missing hard constraint.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_chunk = _chunk_key(key)
                candidate_docs = [
                    raw for raw in passages if key_chunk in _chunk_key(raw)
                ]
                if candidate_docs:
                    missing = [
                        amount
                        for amount in amounts
                        if not any(amount in raw for raw in candidate_docs)
                        and any(amount in raw for raw in passages)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_amount_feedback(missing, original),
                        }

    keys = _context_phrase_keys(ctx.question)
    reason = None
    if _looks_like_prose(original):
        reason = "prose"
    elif _chunk_key(original) not in keys:
        reason = "non_context"

    if reason is None:
        return None

    state["fired"] = fired + 1
    ctx.trace.event(
        "short_answer_retry_continue",
        candidate=original,
        reason=reason,
    )
    return {"action": "continue", "feedback": _generic_feedback(original)}

texts.4b40d2ccd977edba23bbbfed8119af553b9c5dac:
"""Deterministic final-answer cleaner for explicit short-answer QA.

Runs only when the user's request says to return only the short answer. It
removes generic wrapper text that breaks exact-match scoring and, for a small
set of recurring clue shapes, reduces the answer to the requested short form.
It never calls a model and never substitutes a different entity.

The rules are lexical and generic:
  * code fences / matched surrounding quotes
  * "answer is / answer:" and True/False/Yes/No discourse lead-ins
  * parenthetical and bracket glosses
  * trailing dash glosses
  * leading wrapper articles
  * trailing sentence punctuation (periods and repeated !? are stripped;
    a single !/? is stripped only when the bare form is in the context)
  * factual-person statements: keep the leading 2-3 word name run
  * bare role/title clues: keep the country/state/organization after "of"
  * bare pair/list clues: keep the shared label after "from/of/in"
  * "this fruit/vegetable/berry" clues: restore the plural produce form
  * Jeopardy-style "this ..." / "whose ..." person clues: keep the surname
  * short-form clues: drop a trailing category noun ("Party", "Network", ...)
    and reduce "the term for ..." / organization clues to the minimal head
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_ANSWER_LEAD_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_ARTICLE_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s+(?P<gloss>.+)$", re.DOTALL)
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.([A-Za-z]\.)?$")
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")
_ALL_CAPS_RE = re.compile(r"\b[A-Z]{2,}\b")

_DEF_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how)\b",
    re.IGNORECASE,
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|his|him|she|her|hers)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|whose)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
)
_TERM_MARKERS = ("term for",)
_ORG_MARKERS = (
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
)
_CATEGORY_NOUNS = {
    "party",
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
    "alliance",
    "group",
    "service",
    "system",
}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _add_seq(seq: list[tuple[str, str]], surface_map: dict[str, dict[str, int]]) -> None:
    max_n = min(6, len(seq))
    for n in range(1, max_n + 1):
        for i in range(len(seq) - n + 1):
            toks = seq[i : i + n]
            key = "".join(t[0] for t in toks)
            phrase = " ".join(t[1] for t in toks)
            bucket = surface_map.setdefault(key, {})
            bucket[phrase] = bucket.get(phrase, 0) + 1


def _context_index(question: str) -> tuple[set[str], dict[str, dict[str, int]]]:
    """Return (normalized n-gram key set, key -> surface counts)."""
    ctx = _context_text(question)
    keys: set[str] = set()
    surface_map: dict[str, dict[str, int]] = {}
    if not ctx:
        return keys, surface_map

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    _add_seq(seq, surface_map)
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    _add_seq(seq, surface_map)
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            _add_seq(seq, surface_map)

    keys.update(surface_map.keys())
    return keys, surface_map


def _best_surface(bucket: dict[str, int]) -> str:
    def quality(item: tuple[str, int]) -> tuple:
        surface, count = item
        stripped = surface.strip(" .,;:!?\"'`")
        return (
            count,
            0 if stripped.isupper() else 1,
            1 if stripped[:1].isupper() else 0,
            -len(stripped),
        )

    return max(bucket.items(), key=quality)[0].strip(" .,;:!?\"'`")


def _strip_code_fences_and_quotes(text: str) -> str:
    t = (text or "").strip()
    if t.startswith("```") and t.endswith("```") and len(t) > 6:
        inner = t[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            t = inner
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                t = inner
                break
    return t.strip()


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail:
            return tail
    return text


def _strip_answer_lead(text: str) -> str:
    return _ANSWER_LEAD_RE.sub("", text).strip()


def _strip_parentheticals(text: str) -> str:
    text = re.sub(r"\s*\([^()]{0,120}\)", " ", text)
    text = re.sub(r"\s*\[[^\[\]]{0,120}\]", " ", text)
    return " ".join(text.split())


def _strip_trailing_dash_gloss(text: str, keys: set[str]) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and (_norm_text(before) in keys or len(before.split()) <= 4):
        return before
    return text


def _strip_leading_article(text: str) -> str:
    match = _ARTICLE_RE.match(text)
    if match:
        rest = match.group("rest").strip()
        if rest:
            return rest
    return text


def _strip_trailing_punct(text: str, keys: set[str]) -> str:
    t = text
    while True:
        if t.endswith(".") and not t.endswith("..") and len(t) > 2:
            if _ABBREV_RE.search(t):
                return t
            if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", t, re.IGNORECASE):
                return t
            t = t[:-1].rstrip()
            continue

        match = re.search(r"[!?]+$", t)
        if not match:
            return t
        run = match.group(0)
        stripped = t[: match.start()].rstrip()
        if not stripped:
            return t
        if len(run) >= 2 or _norm_text(stripped) in keys:
            t = stripped
            continue
        return t


def _looks_factual_person_statement(question_line: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(question_line)) and not bool(
        _PERSON_DEMO_RE.search(question_line)
    )


def _extract_person_name_run(text: str, keys: set[str]) -> str | None:
    words = text.split()
    if len(words) < 2:
        return None
    # Take the first run of 2-3 consecutive title-case name tokens.
    run: list[str] = []
    for word in words:
        cleaned = word.strip(".,;:!?\"'`")
        if cleaned and _NAME_TOKEN_RE.match(cleaned):
            run.append(cleaned)
            if len(run) == 3:
                break
        else:
            break
    for length in range(len(run), 1, -1):
        candidate = " ".join(run[:length])
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _looks_role_title_clue(question_line: str) -> bool:
    if not question_line or "," in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    words = question_line.split()
    if not (2 <= len(words) <= 6):
        return False
    return all(word[:1].isupper() for word in words if word)


def _extract_role_title_place(text: str, keys: set[str]) -> str | None:
    matches = re.findall(r"\bof\s+([A-Z][A-Za-z]+)", text)
    for candidate in reversed(matches):
        if _norm_text(candidate) in keys:
            return candidate
    match = re.search(r"\bfrom\s+([A-Z][A-Za-z]+)", text)
    if match and _norm_text(match.group(1)) in keys:
        return match.group(1)
    return None


def _looks_pair_list_clue(question_line: str) -> bool:
    if not question_line or "," not in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        words = part.split()
        if not (1 <= len(words) <= 5):
            return False
        if not all(word[:1].isupper() for word in words if word):
            return False
    return True


def _extract_pair_list_label(text: str, keys: set[str]) -> str | None:
    match = re.search(r"\b(?:from|of|in)\s+([A-Z][A-Za-z]+)(?=\s+(?:and|,)|$)", text)
    if match:
        candidate = match.group(1)
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _looks_person_short_clue(question_line: str) -> bool:
    q = question_line.lower()
    if not _PERSON_DEMO_RE.search(q):
        return False
    if _PERSON_PRONOUN_RE.search(q):
        return False
    return any(role in q for role in _PERSON_ROLE_WORDS)


def _shorten_person_name(text: str, keys: set[str]) -> str | None:
    words = text.split()
    if len(words) not in (2, 3):
        return None
    if not all(_NAME_TOKEN_RE.match(word) for word in words):
        return None
    full_key = _norm_text(text)
    last_key = _norm_text(words[-1])
    if not last_key or last_key == full_key or last_key not in keys or full_key not in keys:
        return None
    return words[-1]


def _has_short_form_marker(question_line: str) -> bool:
    q = question_line.lower()
    return any(marker in q for marker in _SHORT_FORM_MARKERS)


def _drop_trailing_category(text: str, keys: set[str], question_line: str) -> str | None:
    if not _has_short_form_marker(question_line):
        return None
    words = text.split()
    if len(words) < 2:
        return None
    last = words[-1].strip(".,;:!?\"'`").lower()
    if last not in _CATEGORY_NOUNS:
        return None
    prefix = " ".join(words[:-1])
    if _norm_text(prefix) in keys:
        return prefix
    return None


def _has_term_marker(question_line: str) -> bool:
    q = question_line.lower()
    return any(marker in q for marker in _TERM_MARKERS)


def _shorten_term_phrase(text: str, keys: set[str], question_line: str) -> str | None:
    if not _has_term_marker(question_line):
        return None
    words = text.split()
    if len(words) < 2:
        return None
    first = words[0].strip(".,;:!?\"'`")
    if first and first[:1].isupper() and _norm_text(first) in keys:
        return first
    return None


def _has_org_marker(question_line: str) -> bool:
    q = question_line.lower()
    return any(marker in q for marker in _ORG_MARKERS)


def _shorten_org_name(text: str, keys: set[str], question_line: str) -> str | None:
    if not _has_org_marker(question_line):
        return None
    if any(ch in text for ch in "()[]"):
        return None
    words = text.split()
    if len(words) not in (2, 3):
        return None
    first = words[0].strip(".,;:!?\"'`")
    if first and first[:1].isupper() and _norm_text(first) in keys:
        return first
    return None


def _prefer_plural_produce(text: str, keys: set[str], question_line: str) -> str | None:
    if not _PRODUCE_RE.search(question_line):
        return None
    words = text.split()
    if len(words) != 1:
        return None
    word = words[0].strip(".,;:!?\"'`")
    if not word:
        return None
    candidates: list[str] = []
    if re.search(r"[^aeiou]y$", word, re.IGNORECASE):
        candidates.append(word[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", word, re.IGNORECASE):
        candidates.append(word + "es")
    candidates.append(word + "s")
    for candidate in candidates:
        if _norm_text(candidate) in keys:
            return candidate
    return None




def _echo_dominant_surface(text: str, surface_map: dict[str, dict[str, int]], question_line: str) -> str:
    """When the clue contains an acronym, prefer the dominant context surface
    for the same normalized token sequence (fixes hyphen/space variants)."""
    if not _ALL_CAPS_RE.search(question_line):
        return text
    key = _norm_text(text)
    bucket = surface_map.get(key)
    if not bucket or len(bucket) < 2:
        return text
    if text.casefold() not in {s.casefold() for s in bucket}:
        return text
    best = _best_surface(bucket)
    if best and best.casefold() != text.casefold():
        return best
    return text

def _clean(text: str, question: str) -> str:
    t = " ".join((text or "").split())
    if not t:
        return t

    keys, surface_map = _context_index(question)

    t = _strip_code_fences_and_quotes(t)
    t = _strip_discourse_lead(t)
    t = _strip_answer_lead(t)
    t = _strip_parentheticals(t)
    t = _strip_trailing_dash_gloss(t, keys)
    t = _strip_leading_article(t)
    t = _strip_trailing_punct(t, keys)

    q = _question_line(question)
    t = _echo_dominant_surface(t, surface_map, q)

    if _looks_factual_person_statement(q) and len(t.split()) > 3:
        extracted = _extract_person_name_run(t, keys)
        if extracted:
            t = extracted
    elif _looks_role_title_clue(q):
        extracted = _extract_role_title_place(t, keys)
        if extracted:
            t = extracted
    elif _looks_pair_list_clue(q):
        extracted = _extract_pair_list_label(t, keys)
        if extracted:
            t = extracted

    if _looks_person_short_clue(q):
        shortened = _shorten_person_name(t, keys)
        if shortened:
            t = shortened

    produce = _prefer_plural_produce(t, keys, q)
    if produce:
        t = produce

    dropped = _drop_trailing_category(t, keys, q)
    if dropped:
        t = dropped

    term = _shorten_term_phrase(t, keys, q)
    if term:
        t = term

    org = _shorten_org_name(t, keys, q)
    if org:
        t = org

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean a final short answer into its bare requested form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.4fd926e40685ed3c7c445c2ce9d5091bb3611908:
"""Bounded self-correction gate for short-answer QA.

Runs after the deterministic cleaner and the side-LLM canonical verifier. Two
bounded triggers ask the *primary* model to re-emit the same answer in the
required form:

1. The candidate still looks like prose rather than the requested bare short
   answer.
2. The candidate is compact but is not a verbatim phrase from the supplied
   context, so it cannot be the exact-match answer the task expects.

The primary model remains the only author of the final answer; the loop is
bounded by the runtime's continue budget, remaining turns, and this hook's
own retry cap.
"""

from __future__ import annotations

import re

_MARKER = re.compile(r"^\[[^\]]*\]$")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


_PROSE_STOPWORDS = re.compile(
    r"\b(the|a|an|from|of|and|in|for|with|to|as|by)\b", re.IGNORECASE
)


def _looks_prose(text: str) -> bool:
    """A bare short answer is compact; prose is not.

    The primary trigger stays at seven words to avoid false positives on
    legitimate multi-word phrases. A lower trigger is allowed only when the
    draft also contains connective/function words, which are rare in the
    compact title/name/nickname answers this task family expects.
    """
    words = text.split()
    if len(words) >= 7:
        return True
    if len(words) >= 4 and _PROSE_STOPWORDS.search(text):
        return True
    return False


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrases(question: str) -> set[str]:
    """Return normalized n-gram keys that appear verbatim in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    sequences: list[list[str]] = []
    current: list[str] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append(norm)
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                keys.add("".join(seq[i : i + n]))
    return keys


def _is_context_phrase(text: str, question: str) -> bool:
    key = _norm_text(text)
    if not key:
        return False
    return key in _context_phrases(question)


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Keep the same answer, but reformat it as only the requested short "
        "phrase: no sentence, no lead-in, no explanation, no parenthetical, "
        "no role/date/title gloss, no trailing punctuation. "
        "Use the exact wording from the supplied context. "
        "Return only the corrected short answer."
    )


def _context_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not a verbatim phrase from the supplied context, "
        "so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "context phrase that satisfies every clue in the question, then return "
        "only that exact phrase: no sentence, no explanation, no parenthetical, "
        "no extra formatting."
    )


async def before_final(candidate, ctx):
    """Continue once or twice when a short-answer draft still needs repair."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_gate"]
    fired = state.get("fired", 0)
    if fired >= 2:
        # Explicit exit condition: do not keep reformatting the same chain.
        return None

    if _looks_prose(original):
        state["fired"] = fired + 1
        state["prose_fired"] = state.get("prose_fired", 0) + 1
        return {"action": "continue", "feedback": _prose_feedback(original)}

    if not _is_context_phrase(original, ctx.question):
        state["fired"] = fired + 1
        state["context_fired"] = state.get("context_fired", 0) + 1
        return {"action": "continue", "feedback": _context_feedback(original)}

    return None

texts.55ec641667e0f194da95240e6123c350032c2c7a:
"""Deterministic surface-only final-answer cleaner for short-answer QA.

This hook runs only when the user request contains the explicit short-answer
instruction (``return only the short answer``). It never calls a model and
never changes which entity or term the model selected: it removes generic
surface wrappers around an answer candidate and re-echoes the supplied
context's dominant surface form for the same normalized token sequence.

Removals are deliberately generic and reversible:

  * surrounding code fences / matched quotes
  * ``Answer is:`` / ``The answer is`` lead-ins
  * discourse lead-ins such as ``True -- ...``
  * a trailing sentence period (abbreviations and initialisms are preserved)
  * trailing parenthetical/bracket glosses
  * trailing em/en-dash glosses whose head is supported by the context
  * decorative trailing ``!``/``?`` marks when the base is context-supported
  * a leading article when the article-less form is context-supported
  * canonical surface echo: case, spacing, and hyphenation are copied from the
    most frequent supplied-context variant of the same normalized phrase

After the surface cleanup above, a conservative minimal-form pass trims only
the shortest context-supported form for question types that conventionally ask
for it (nickname/short name, Jeopardy-style person surname, produce plural,
definition term head, ``of these/those`` demonstrative head, and bare
role/pair clues). Every replacement in that pass is a verbatim n-gram from the
supplied context, so it never invents an answer and never substitutes a
different entity.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_CODE_FENCE_RE = re.compile(r"^```[A-Za-z]*\s*\n(.*?)\n?```$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:-]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAIL_PAREN_RE = re.compile(r"\s*\([^()]{1,160}\)\s*$")
_TRAIL_BRACKET_RE = re.compile(r"\s*\[[^\[\]]{1,160}\]\s*$")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_TRAIL_PERIOD_RE = re.compile(r"\.$")
_TRAIL_BANG_RE = re.compile(r"[!?]+$")
_ARTICLE_RE = re.compile(r"^(a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)

_ABBREV_RE = re.compile(
    r"(?:\b[A-Za-z]\.){2,}$|\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", re.IGNORECASE
)

# ---------------------------------------------------------------------------
# Minimal-form extraction constants
# ---------------------------------------------------------------------------

_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "referred to as",
    "called it",
    "term for",
    "surname",
    "acronym",
    "pre-",
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
    "league",
)
_CATEGORY_SUFFIXES = {
    "party",
    "company",
    "network",
    "radio",
    "mint",
    "association",
    "organization",
    "organisation",
    "league",
    "corporation",
    "corp",
    "inc",
    "ltd",
    "system",
    "satellite",
}
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "singer",
    "director",
    "composer",
)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")
_ROLE_TITLE_WORDS = (
    "president",
    "sultan",
    "king",
    "queen",
    "emperor",
    "mayor",
    "governor",
    "senator",
    "chancellor",
    "secretary",
)
_OF_FROM_BLOCKLIST = {
    "state",
    "office",
    "department",
    "ministry",
    "government",
    "republic",
    "kingdom",
    "party",
    "house",
    "senate",
    "congress",
    "parliament",
}
_QUESTION_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"he|she|his|her|him)\b",
    re.IGNORECASE,
)
_OF_THESE_RE = re.compile(r"\bof\s+(?:these|those)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    """Casefold and collapse every non-alphanumeric run to a single space."""
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _strip_surrounding(text: str) -> str:
    return (text or "").strip(" \t\r\n.,;:!?\"'`")


def _surface_map(question: str) -> dict[str, list[tuple[str, int]]]:
    """Map normalized n-gram keys to (surface, count) variants from context."""
    ctx = _context_text(question)
    surfaces: dict[str, list[tuple[str, int]]] = {}
    if not ctx:
        return surfaces

    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(6, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                phrase = " ".join(tokens[i : i + n])
                key = _chunk_key(phrase)
                if not key:
                    continue
                bucket = surfaces.setdefault(key, [])
                if all(surface != phrase for surface, _ in bucket):
                    bucket.append((phrase, 0))

    ctx_lower = ctx.lower()
    for key, bucket in surfaces.items():
        for idx, (surface, _) in enumerate(bucket):
            bucket[idx] = (surface, ctx_lower.count(surface.lower()))
    return surfaces


def _surface_quality(item: tuple[str, int], candidate: str) -> tuple:
    surface, count = item
    stripped = _strip_surrounding(surface)
    return (
        count,
        1 if surface.casefold() == candidate.casefold() else 0,
        1 if stripped[:1].isupper() else 0,
        1 if not stripped.isupper() else 0,
        -stripped.count("-"),
        -len(stripped),
    )


def _best_surface(bucket: list[tuple[str, int]], candidate: str) -> str:
    if not bucket:
        return candidate
    best = max(bucket, key=lambda item: _surface_quality(item, candidate))
    return _strip_surrounding(best[0])


def _has_key(text: str, surfaces: dict) -> bool:
    key = _chunk_key(text)
    return bool(key) and key in surfaces


def _strip_code_fence(text: str) -> str:
    match = _CODE_FENCE_RE.match(text.strip())
    if match:
        return match.group(1).strip()
    return text


def _strip_surrounding_quotes(text: str) -> str:
    t = text.strip()
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                return inner
    return t


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_RE.match(text.strip())
    if match and match.group("tail").strip():
        return match.group("tail").strip()
    return text


def _strip_answer_lead(text: str) -> str:
    return _LEAD_IN_RE.sub("", text.strip()).strip()


def _strip_trailing_parentheticals(text: str) -> str:
    cur = text.strip()
    for _ in range(8):
        prev = cur
        for pattern in (_TRAIL_PAREN_RE, _TRAIL_BRACKET_RE):
            match = pattern.search(cur)
            if match:
                nxt = cur[: match.start()].strip()
                if nxt and nxt != cur:
                    cur = nxt
                    break
        if cur == prev:
            break
    return cur


def _strip_trailing_dash_gloss(text: str, surfaces: dict) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _has_key(before, surfaces):
        return before
    return text


def _strip_trailing_period(text: str, surfaces: dict) -> str:
    cur = text.strip()
    for _ in range(4):
        if not cur.endswith(".") or cur.endswith(".."):
            break
        if _ABBREV_RE.search(cur):
            break
        nxt = cur[:-1].rstrip()
        if not nxt:
            break
        if cur[-2].islower() or cur[-2] in ")]}\"'" or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_trailing_bang(text: str, surfaces: dict) -> str:
    """Strip decorative trailing !/? when the base is context-supported or the
    mark is doubled. Repeated marks are surface decoration, not an entity."""
    cur = text.strip()
    for _ in range(4):
        match = _TRAIL_BANG_RE.search(cur)
        if not match:
            break
        run = match.group(0)
        nxt = cur[: match.start()].rstrip()
        if not nxt:
            break
        if len(run) >= 2 or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_leading_article(text: str, surfaces: dict) -> str:
    match = _ARTICLE_RE.match(text.strip())
    if not match:
        return text.strip()
    rest = match.group("rest").strip()
    if not rest:
        return text.strip()
    if _has_key(rest, surfaces) or rest[0].isupper() or rest[0].isdigit():
        return rest
    return text.strip()


def _echo_context_form(text: str, surfaces: dict, original: str) -> str:
    key = _chunk_key(text)
    if not key or key not in surfaces:
        return text
    return _best_surface(surfaces[key], original)


# ---------------------------------------------------------------------------
# Minimal-form extraction
# ---------------------------------------------------------------------------


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _word_in_question(word: str, question_line: str) -> bool:
    w = re.sub(r"[^A-Za-z0-9]", "", word.casefold())
    if not w:
        return False
    return w in set(re.findall(r"[A-Za-z0-9]+", question_line.casefold()))


def _has_short_form_cue(question_line: str) -> bool:
    q = question_line.lower()
    if any(marker in q for marker in _SHORT_FORM_MARKERS):
        return True
    return bool(
        re.search(
            r"\bthis\s+(?:\w+\s+)?(?:company|network|mint|radio|association|"
            r"organization|organisation|league)\b",
            q,
        )
    )


def _drop_trailing_descriptors(text: str, question_line: str, surfaces: dict) -> str:
    """Drop trailing category words or question descriptors when a shorter
    context-supported prefix remains. Used for nickname/short-name clues
    where a trailing category noun should be removed."""
    if not _has_short_form_cue(question_line):
        return text
    if re.search(r"[()\[\]]", text):
        return text
    words = text.split()
    if len(words) < 2:
        return text

    cur = text
    for end in range(len(words) - 1, 0, -1):
        prefix = " ".join(words[:end])
        dropped = words[end]
        drop_word = re.sub(r"[^A-Za-z0-9]", "", dropped.casefold())
        if drop_word in _CATEGORY_SUFFIXES or _word_in_question(dropped, question_line):
            if _has_key(prefix, surfaces):
                cur = prefix
                continue
            break
        break
    return cur


def _person_surname(text: str, question_line: str, surfaces: dict) -> str:
    """For Jeopardy-style ``this ...`` / ``whose ...`` person clues, keep only
    the surname/target name when the supplied context also provides that
    surname alone. Factual ``he/she/his/her`` statements are excluded because
    those usually want the person's name exactly as the context introduces it."""
    q = question_line.lower()
    if _PERSON_PRONOUN_RE.search(q):
        return text
    if not _PERSON_DEMO_RE.search(q):
        return text
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return text

    words = text.split()
    if len(words) not in (2, 3, 4):
        return text
    if not all(_NAME_TOKEN_RE.match(word) for word in words):
        return text

    surname = words[-1]
    if _has_key(surname, surfaces):
        return _best_surface(surfaces[_chunk_key(surname)], surname)
    return text


def _plural_candidates(word: str) -> list[str]:
    base = word.strip()
    if not base:
        return []
    candidates: list[str] = []
    if re.search(r"[^aeiou]y$", base, re.IGNORECASE):
        candidates.append(base[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", base, re.IGNORECASE):
        candidates.append(base + "es")
    candidates.append(base + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question_line: str, surfaces: dict) -> str:
    """Restore the context's plural produce form for ``this fruit/vegetable/
    berry/plant`` clues."""
    if len(text.split()) != 1:
        return text
    if not _PRODUCE_RE.search(question_line):
        return text

    word = text.strip()
    for candidate in _plural_candidates(word):
        if _has_key(candidate, surfaces):
            return _best_surface(surfaces[_chunk_key(candidate)], candidate)
    return text


def _is_pair_list_clue(question_line: str) -> bool:
    """Bare pair/list clues such as ``A,B`` or ``A,B,C`` with no other
    predicate."""
    if "," not in question_line:
        return False
    if _QUESTION_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 6):
        return False
    for part in parts:
        tokens = [t for t in re.findall(r'"[^"]+"|[A-Za-z][A-Za-z\'\-]*', part) if t]
        if not tokens:
            return False
        if not all(t[:1].isupper() or t.startswith('"') for t in tokens):
            return False
    return True


def _is_role_title_clue(question_line: str) -> bool:
    """Bare role/title clues such as ``President X`` or ``Sultan X``. The
    requested short answer is the associated place/office label, not a
    sentence about the role."""
    if "," in question_line:
        return False
    if _QUESTION_DEMO_RE.search(question_line):
        return False
    q = question_line.lower()
    if not any(word in q for word in _ROLE_TITLE_WORDS):
        return False
    return len(question_line.split()) <= 8


def _extract_of_from_head(text: str, surfaces: dict) -> str:
    """Extract a capitalized place/office head after ``of``/``from`` in a
    verbose draft, but only when that head is supplied verbatim by the
    context and is not a generic title/office word."""
    match = re.search(
        r"\b(?:of|from)\s+([A-Z][A-Za-z]+(?:[ \t]+[A-Z][A-Za-z]+){0,2})",
        text,
    )
    if not match:
        return text
    candidate = _strip_surrounding(match.group(1))
    if not candidate:
        return text
    if candidate.casefold() in _OF_FROM_BLOCKLIST:
        return text
    if _has_key(candidate, surfaces):
        return _best_surface(surfaces[_chunk_key(candidate)], candidate)
    return text


def _definition_term_head(text: str, question_line: str, surfaces: dict) -> str:
    """For ``term for`` clues, keep the head term before ``of X`` when the
    head is context-supported and the tail is either a proper noun or is
    already named in the question."""
    if "term for" not in question_line.lower():
        return text
    match = re.match(r"^(.+?)\s+of\s+(.+)$", text)
    if not match:
        return text
    head = match.group(1).strip()
    tail = match.group(2).strip()
    if not _has_key(head, surfaces):
        return text

    tail_words = re.findall(r"[A-Za-z0-9]+", tail)
    tail_in_question = bool(tail_words) and all(
        _word_in_question(word, question_line) for word in tail_words
    )
    if tail_in_question or (tail[:1].isupper() if tail else False):
        return _best_surface(surfaces[_chunk_key(head)], head)
    return text


def _extract_demonstrative_of_head(text: str, question_line: str, surfaces: dict) -> str:
    """For ``of these/those ...`` clues, drop leading modifiers from a draft
    that is not itself a context phrase and keep the shortest context-supported
    suffix. This recovers the head noun (e.g. ``laundries``) from an
    overqualified phrase such as ``Chinese hand laundries``."""
    if not _OF_THESE_RE.search(question_line):
        return text
    words = text.split()
    if len(words) < 2:
        return text
    if _has_key(text, surfaces):
        return text

    for n in range(1, min(4, len(words))):
        suffix = " ".join(words[-n:])
        if suffix != text and _has_key(suffix, surfaces):
            return _best_surface(surfaces[_chunk_key(suffix)], suffix)
    return text


def _minimal_form(text: str, question: str, surfaces: dict) -> str:
    """Return the shortest context-supported form for question types that
    conventionally ask for one. Each rewrite is a verbatim context n-gram."""
    question_line = _question_line(question)
    cur = text

    cur = _drop_trailing_descriptors(cur, question_line, surfaces)
    cur = _person_surname(cur, question_line, surfaces)
    cur = _prefer_plural_produce_form(cur, question_line, surfaces)
    cur = _definition_term_head(cur, question_line, surfaces)
    cur = _extract_demonstrative_of_head(cur, question_line, surfaces)

    if _is_pair_list_clue(question_line) or _is_role_title_clue(question_line):
        cur = _extract_of_from_head(cur, surfaces)

    return cur


def _clean(original: str, question: str) -> str:
    surfaces = _surface_map(question)

    text = original.strip()
    text = _strip_code_fence(text)
    text = _strip_surrounding_quotes(text)
    text = _strip_discourse_lead(text)
    text = _strip_answer_lead(text)
    text = _strip_trailing_dash_gloss(text, surfaces)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_parentheticals(text)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_bang(text, surfaces)
    text = _strip_leading_article(text, surfaces)

    # Canonicalize spacing/case/hyphenation from the supplied context.
    text = _echo_context_form(text, surfaces, original)

    # Echo may re-introduce decorative title punctuation; strip it one final
    # time without re-echoing so we do not undo the punctuation cleanup.
    text = _strip_trailing_bang(text, surfaces)

    # Now that the candidate is wrapper-free, select the minimal context form
    # only for question types that ask for a short/nickname/surname/term.
    text = _minimal_form(text, question, surfaces)
    text = _strip_trailing_bang(text, surfaces)

    return " ".join(text.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.56ce4b664cc80df195fa1cca45dea31112e1a5f4:
"""Bounded side-LLM verifier for short-answer QA.

Runs after the deterministic cleaner. For suspicious multi-token drafts it asks
a side model to re-derive the exact context phrase that satisfies every clue.
It only replaces the draft when the side output is a verbatim phrase from the
supplied context and is not longer than the draft. At most one side call is made
per task, with an explicit exit condition.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER = re.compile(r"^\[[^\]]*\]$")
_SHORT_FORM_MARKERS = (
    "term for",
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "pre-",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "mayor",
    "governor",
    "politician",
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_DEFINITION_RE = re.compile(
    r"^(?:an?|the)\s+[a-z]",
    re.IGNORECASE,
)
_DEFINITION_VERB_RE = re.compile(
    r"\b(applied|used|known|called|termed|named|designed|worn)\b",
    re.IGNORECASE,
)
_DIGIT_RE = re.compile(r"\d")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _phrase_quality(phrase: str) -> tuple:
    stripped = _strip_surrounding(phrase)
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        stripped.count(" "),
        -stripped.count("-"),
        len(stripped),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _looks_person_short_form(q: str) -> bool:
    ql = q.lower()
    if not _PERSON_DEMO_RE.search(q):
        return False
    return any(role in ql for role in _PERSON_ROLE_WORDS)


def _looks_definition_clue(q: str) -> bool:
    return bool(_DEFINITION_RE.match(q)) and bool(_DEFINITION_VERB_RE.search(q))


def _looks_numeric_person(q: str) -> bool:
    ql = q.lower()
    if not _DIGIT_RE.search(q):
        return False
    return any(role in ql for role in _PERSON_ROLE_WORDS)


def _should_verify(q: str, in_context: bool) -> bool:
    if not in_context:
        return True
    ql = q.lower()
    if any(marker in ql for marker in _SHORT_FORM_MARKERS):
        return True
    if _looks_person_short_form(q):
        return True
    if _looks_numeric_person(q):
        return True
    if _looks_definition_clue(q):
        return True
    return False


def _clean_side_output(text: str, phrases: dict[str, list[str]]) -> str | None:
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines:
        return None
    cleaned_lines: list[str] = []
    for raw in lines:
        out = raw.strip().strip("\"'`").strip()
        out = re.sub(
            r"^(?:answer\s*(?:is|:)?\s*)", "", out, flags=re.IGNORECASE
        ).strip()
        if not out:
            continue
        if out.lower().strip(" .") == "keep" or out.lower().startswith("keep"):
            return None
        cleaned_lines.append(out)
        if _norm_text(out) in phrases:
            return out
    if not cleaned_lines:
        return None
    last = cleaned_lines[-1]
    return last if _norm_text(last) in phrases else None


def _prompt(question: str, draft: str) -> str:
    return (
        "You are checking a short-answer QA draft. Use ONLY the supplied context below.\n\n"
        + question
        + "\n\nDraft answer:\n"
        + draft
        + "\n\n"
        "Check the draft against every clue in the question.\n"
        "If the draft already satisfies every clue, return exactly KEEP.\n"
        "Otherwise, find the exact phrase in the supplied context that satisfies "
        "every clue and return that phrase.\n\n"
        "Rules:\n"
        "- Prefer the passage that states every number, date, denomination, "
        "function, or relationship in the question.\n"
        "- For a definition clue (for example 'An X that does Y'), return the "
        "general category/term whose function is stated, not a salient example.\n"
        "- For a Jeopardy-style 'this ...' or 'whose ...' clue, return the "
        "shortest blank-filling phrase from the context (nickname, term, surname, "
        "acronym, or short company/network/mint/association name), not a full "
        "name or title expansion.\n"
        "- For a factual statement about a person ('he/his/her ...'), return the "
        "person's full name exactly as the context introduces it.\n"
        "- Preserve the exact spelling, capitalization, hyphenation, number, and "
        "articles of the context phrase.\n"
        "- Return only KEEP or the corrected answer string. No explanation, "
        "quotes, or formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Replace a suspicious multi-token draft only with a context-backed answer."""
    if not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_verify"]
    if state.get("fired", 0) >= 1:
        return None

    original = (candidate or "").strip()
    if len(original.split()) < 2:
        return None

    phrases, _ = _context_phrases(ctx.question)
    if not phrases:
        return None

    q = _question_line(ctx.question)
    original_key = _norm_text(original)
    in_context = original_key in phrases
    if not _should_verify(q, in_context):
        return None

    state["fired"] = 1
    try:
        side = await ctx.side_text(
            _prompt(ctx.question, original),
            purpose="short_answer_verify",
            max_tokens=80,
        )
    except Exception as e:
        ctx.trace.event("short_answer_verify_error", error=str(e))
        return None
    if not side:
        return None

    side_clean = _clean_side_output(side, phrases)
    if not side_clean:
        return None

    side_key = _norm_text(side_clean)
    if side_key == original_key or side_key not in phrases:
        return None

    ctx_text = _context_text(ctx.question)
    cleaned = _strip_surrounding(_best_phrase(phrases[side_key], ctx_text))
    cleaned_key = _norm_text(cleaned)
    if cleaned_key == original_key:
        return None
    if len(cleaned.split()) > len(original.split()):
        ctx.trace.event(
            "short_answer_verify_rejected",
            reason="side_longer_than_draft",
            draft=original,
            side=cleaned,
        )
        return None

    ctx.trace.event(
        "short_answer_verify_replace",
        draft=original,
        replacement=cleaned,
    )
    return {"action": "replace", "answer": cleaned}

texts.5e71269937092281e42f43d254e786bdb010ebed:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate that is a verbatim context phrase with a shorter context-phrase
   prefix/suffix and the question explicitly asks for a short name form
   (surname, nickname, acronym, initials, or a "known as" target). Generic
   "this ..." person/company clues and definition/type terms are deliberately
   not shortened.
4. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").
5. Single-token person/brand candidate whose supplied context also gives a
   fuller canonical proper-name form ending in that token; this is an
   over-shortening recovery trigger, the inverse of trigger 3.
6. "one of these/those" candidate that merely echoes the quoted clue phrase
   instead of naming the category/entity it describes.
7. "type of X" candidate that names the general X (or a general descriptor
   ending in X) instead of the specific type.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

# Strong cues that the requested form is shorter than the full context phrase.
_SHORT_FORM_MARKERS = (
    "surname",
    "nickname",
    "nicknamed",
    "acronym",
    "short name",
    "initials",
    "known as",
    "referred to as",
    "called it",
)

_EXPLICIT_MINIMAL_NAME_MARKERS = (
    "surname",
    "nickname",
    "nicknamed",
    "acronym",
    "short name",
    "initials",
)

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)

_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_THIS_PERSON_RE = re.compile(r"\bthis\s+(man|woman|person|boy|girl)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "man", "woman", "person", "boy", "girl", "founder", "author", "writer",
    "novelist", "poet", "playwright", "actor", "actress", "singer",
    "bandleader", "composer", "artist", "painter", "director", "senator",
    "president", "mayor", "governor", "sultan", "king", "queen", "emperor",
    "explorer", "frontiersman", "circumnavigator", "pioneer", "leader",
    "chief", "thief", "boxer", "golfer", "inventor", "scientist", "engineer",
    "aviator", "pilot", "sailor", "politician", "diplomat", "general",
    "admiral", "captain", "colonel", "marshal", "knight", "criminal",
    "detective", "sleuth", "outlaw",
)
_BRAND_CATEGORY_RE = re.compile(
    r"\b(company|store|chain|brand|retailer|restaurant|network|association|"
    r"organization|organisation|alliance|agency|mint|radio|hardware|market|"
    r"shop|dealer|manufacturer)\b",
    re.IGNORECASE,
)
_HONORIFIC_TOKENS = {"lord", "sir", "dr", "mr", "mrs", "ms", "st", "prof"}

_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_PHRASE_RE = re.compile(r'"([^"]+)"')
_TYPE_OF_HEAD_RE = re.compile(
    r"\btype of\s+(?P<head>[A-Za-z][A-Za-z0-9' -]+?)"
    r"(?=\s+(?:that|which|is|are|was|were|made|used|called|known|for|to|with|from|,|\.)|\s*$)",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _looks_person_clue(q: str) -> bool:
    """True for person clues that normally want the full canonical name."""
    if not q:
        return False
    ql = q.lower()
    if _PERSON_PRONOUN_RE.search(q):
        return True
    if _THIS_PERSON_RE.search(q):
        return True
    return any(re.search(r"\b" + re.escape(word) + r"\b", ql) for word in _PERSON_ROLE_WORDS)


def _looks_brand_clue(q: str) -> bool:
    """True for 'this ...' brand/entity clues that may want a fuller name."""
    if not q:
        return False
    ql = q.lower()
    return bool(re.search(r"\bthis\b", ql) and _BRAND_CATEGORY_RE.search(ql))


def _proper_name_like(word: str) -> bool:
    word = (word or "").strip(" .,;:!?\"'`")
    if not word:
        return False
    if word.lower() in _HONORIFIC_TOKENS:
        return True
    return bool(_NAME_TOKEN_RE.match(word))


def _fuller_proper_forms(question: str, candidate: str) -> list[str]:
    """Return fuller proper-name context surfaces ending in ``candidate``.

    Only multi-word surfaces whose final token normalizes to the candidate are
    returned, so a bare given-name answer (e.g. ``Anastasia``) is never
    expanded from a following surname, while a bare surname answer (e.g.
    ``Drake``) can be restored to its fuller introduced form.
    """
    key = _norm_text(candidate)
    if not key:
        return []
    surfaces = _context_surfaces(question)
    forms: list[tuple[int, str]] = []
    for skey, bucket in surfaces.items():
        if not skey.endswith(key) or skey == key:
            continue
        for surface, count in bucket.items():
            words = [word.strip(" .,;:!?\"'`") for word in surface.split()]
            words = [word for word in words if word]
            if not (2 <= len(words) <= 4):
                continue
            if not all(_proper_name_like(word) for word in words):
                continue
            if _norm_text(words[-1]) != key:
                continue
            cleaned_surface = " ".join(words)
            forms.append((count, cleaned_surface))
    forms.sort(key=lambda item: (-item[0], -len(item[1].split()), item[1].casefold()))
    return [surface for _, surface in forms]


def _looks_undershortened_proper_name(text: str, question: str) -> bool:
    """Detect a one-token answer that is likely an over-shortened person/brand."""
    words = text.split()
    if len(words) != 1:
        return False
    q = _question_line(question)
    if not q:
        return False
    ql = q.lower()
    if any(marker in ql for marker in _EXPLICIT_MINIMAL_NAME_MARKERS):
        return False
    if not (_looks_person_clue(q) or _looks_brand_clue(q)):
        return False
    return bool(_fuller_proper_forms(question, text))


def _looks_echoed_clue_phrase(text: str, question: str) -> bool:
    """True when a "one of these/those" answer merely echoes the quoted clue."""
    q = _question_line(question)
    if not _ONE_OF_THESE_RE.search(q):
        return False
    quoted = _QUOTED_PHRASE_RE.findall(q)
    if not quoted:
        return False
    key = _norm_text(text)
    return bool(key) and any(key == _norm_text(phrase) for phrase in quoted)


def _looks_general_type_answer(text: str, question: str) -> bool:
    """True when a "type of X" clue is answered with the general X or a
    general descriptor ending in X instead of the specific type."""
    q = _question_line(question)
    match = _TYPE_OF_HEAD_RE.search(q)
    if not match:
        return False
    head = match.group("head").strip()
    head_norm = _norm_text(head)
    if not head_norm:
        return False
    text_norm = _norm_text(text)
    return text_norm == head_norm or text_norm.endswith(head_norm)


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    q = _question_line(question).lower()
    words = text.split()
    if len(words) < 2:
        return False

    keys = _context_phrase_keys(question)
    key = _norm_text(text)
    if key not in keys:
        return False

    # Only explicit short-name requests justify asking for a shorter phrase.
    # Generic "this ..." person/company clues and organization/association
    # clues are deliberately excluded because evidence shows they make the
    # model over-shorten correct full names (Oliver Brown -> Brown,
    # Ace Hardware -> Ace, Lord Robert Baden-Powell -> Robert Baden-Powell).
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False

    for n in range(1, len(words)):
        if _norm_text(" ".join(words[:n])) in keys:
            return True
    last = _norm_text(words[-1])
    if last in keys and last != key:
        return True
    return False


def _question_token_set(question: str) -> set[str]:
    """Return normalized single-word tokens present in the question line."""
    q = _question_line(question)
    return {_norm_token(token) for token in q.split() if _norm_token(token)}


def _clue_stated_qualifier_shorter(text: str, question: str) -> list[str]:
    """Find shorter context phrases obtained by dropping a leading or trailing
    run of words that are all already stated in the question.

    This is deliberately narrower than the old generic overexpansion trigger:
    it only proposes a shorter phrase when every dropped word is a token that
    the question itself already contains, and the whole candidate is NOT simply
    a quoted phrase echoed from the question. Full proper names whose extra
    words are not in the question (for example a person's full legal name) never fire.
    """
    words = text.split()
    if len(words) < 2:
        return []

    keys = _context_phrase_keys(question)
    if _norm_text(text) not in keys:
        return []

    q_norm = _norm_text(_question_line(question))
    if _norm_text(text) in q_norm:
        return []

    q_tokens = _question_token_set(question)
    candidates: list[str] = []

    # Leading qualifier(s): "Chinese laundries" -> "laundries".
    for n in range(1, len(words)):
        dropped = words[:n]
        if not dropped:
            continue
        if not all(_norm_token(word) and _norm_token(word) in q_tokens for word in dropped):
            continue
        shorter = " ".join(words[n:]).strip()
        if shorter and _norm_text(shorter) in keys:
            candidates.append(shorter)

    # Trailing qualifier(s): "SCTV Network" -> "SCTV";
    # "Anastasia Romanov" -> "Anastasia";
    # "Sirius Satellite Radio" -> "Sirius".
    for n in range(1, len(words)):
        dropped = words[-n:]
        if not dropped:
            continue
        if not all(_norm_token(word) and _norm_token(word) in q_tokens for word in dropped):
            continue
        shorter = " ".join(words[:-n]).strip()
        if shorter and _norm_text(shorter) in keys:
            candidates.append(shorter)

    # Prefer the shortest surviving context phrase, then a stable lexical order.
    unique: dict[str, str] = {}
    for candidate in candidates:
        unique[candidate.casefold()] = candidate
    return [
        candidate
        for candidate in sorted(
            unique.values(), key=lambda s: (len(s.split()), s.casefold())
        )
        if candidate.casefold() != text.casefold()
    ]


def _clue_stated_qualifier_feedback(draft: str, shorter: list[str]) -> str:
    forms = ", ".join(shorter[:4]) if shorter else "none"
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer repeats a word or phrase that is already stated "
        "in the question.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "If the repeated word(s) are only a qualifier or category already "
        "present in the question, return the shorter exact phrase from the "
        "supplied context without them. Candidate context phrase(s): "
        + forms
        + ".\n"
        "If the repeated word is part of the entity's proper name (for "
        "example a person's full legal name or a company's full registered name), keep "
        "your previous answer unchanged.\n"
        "Copy the exact wording and extent from the supplied context, and "
        "return only the corrected exact phrase."
    )


def _echoed_clue_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "This is a 'one of these/those' clue. Your previous answer echoes the "
        "quoted phrase from the question, but the quoted phrase is a clue, not "
        "the answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the category "
        "or entity that the quoted phrase describes (for example the object, "
        "class, or term), and return only that exact phrase, copied verbatim "
        "from the supplied context. Do not echo the quoted phrase, and do not "
        "include any lead-in, explanation, or extra punctuation."
    )


def _type_of_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "This is a 'type of ...' clue. Your previous answer names the general "
        "category or a general descriptor, but the clue asks for the specific "
        "type.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the specific type named there "
        "that satisfies every clue. Return only that specific type, copied "
        "verbatim from the supplied context. If your previous answer already "
        "names the specific type, return it unchanged."
    )


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not include any lead-in, explanation, "
        "parenthetical, gloss, date, or extra punctuation. If the question "
        "quotes a phrase, that quoted phrase is a clue, not the answer; do "
        "not echo it. For a 'these ...' or 'one of these ...' clue, return "
        "the category term for the group, not the quoted phrase itself and "
        "not a phrase that repeats a qualifier already present in the "
        "question. If the question is a definition or category clue (\"An X "
        "that does Y\", \"this type of ...\", \"the term for ...\"), "
        "return the general category or term whose function the context "
        "states, not a specific example that shares only one property."
    )


def _short_form_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer appears to be longer than the requested short "
        "form, or uses a fuller name than the clue asks for.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question. Determine the shortest exact phrase from the "
        "supplied context that still satisfies every clue (for example a "
        "nickname, term, acronym, surname, or short company/network/mint/"
        "association name). For a definition or category clue (\"An X that "
        "does Y\", \"this type of ...\", \"the term for ...\"), return "
        "the general category or term whose function the context states, not "
        "a specific example sharing only one property. If the shorter phrase "
        "no longer satisfies every clue or no longer names the same entity, "
        "keep the full phrase. Do not drop given names, honorifics, or "
        "required company words, and do not replace a name with an epithet "
        "or descriptor. Return only the correct exact phrase."
    )


def _undershorten_feedback(draft: str, fuller_forms: list[str]) -> str:
    forms_text = ", ".join(fuller_forms[:4]) if fuller_forms else "none"
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may be over-shortened. The supplied context "
        "also introduces this person or entity with fuller canonical name "
        "forms: " + forms_text + ".\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. If the question "
        "explicitly asks for only a surname, nickname, acronym, or initials, "
        "keep your answer unchanged. Otherwise return the fuller canonical "
        "name exactly as the supplied context introduces it (including any "
        "given name or honorific the context uses). Copy the exact wording "
        "and extent from the context, and return only that phrase."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 2.3: "one of these/those" clue answered by echoing the quoted
    # phrase instead of naming the category/entity it describes.
    if state.get("echoed_clue_fired", 0) < 1:
        if _looks_echoed_clue_phrase(original, ctx.question):
            state["echoed_clue_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_echoed_clue", candidate=original)
            return {
                "action": "continue",
                "feedback": _echoed_clue_feedback(original),
            }

    # Trigger 2.35: "type of X" clue answered with the general X or a general
    # descriptor ending in X instead of the specific type.
    if state.get("type_of_fired", 0) < 1:
        if _looks_general_type_answer(original, ctx.question):
            state["type_of_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_type_of", candidate=original)
            return {
                "action": "continue",
                "feedback": _type_of_feedback(original),
            }

    # Trigger 2.4: candidate is a context phrase that repeats a qualifier or
    # category word already stated in the question. Ask the primary model to
    # drop only the repeated qualifier; full proper names are explicitly
    # protected in the feedback.
    if state.get("clue_stated_qualifier_fired", 0) < 1:
        shorter = _clue_stated_qualifier_shorter(original, ctx.question)
        if shorter:
            state["clue_stated_qualifier_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event(
                "short_answer_retry_clue_stated_qualifier",
                candidate=original,
                shorter=shorter[:4],
            )
            return {
                "action": "continue",
                "feedback": _clue_stated_qualifier_feedback(original, shorter),
            }

    # Trigger 2.5: single-token candidate that is likely an over-shortened
    # person or brand answer. The inverse of the overexpansion trigger: it only
    # fires when the answer is already a bare token and the context supplies a
    # fuller canonical proper-name surface ending in that token.
    if state.get("undershorten_fired", 0) < 1:
        if _looks_undershortened_proper_name(original, ctx.question):
            fuller = _fuller_proper_forms(ctx.question, original)
            state["undershorten_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event(
                "short_answer_retry_undershorten",
                candidate=original,
                fuller_forms=fuller[:4],
            )
            return {
                "action": "continue",
                "feedback": _undershorten_feedback(original, fuller),
            }

    # Trigger 3: candidate is a context phrase but longer than the requested
    # short form. The primary model decides whether a shorter phrase is valid.
    if state.get("overexpanded_fired", 0) < 1 and _looks_overexpanded(
        original, ctx.question
    ):
        state["overexpanded_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_overexpanded", candidate=original)
        return {"action": "continue", "feedback": _short_form_feedback(original)}

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.619fe4f7d40e6adbf50c11b4e856d693b7f58643:
"""Deterministic short-answer surface cleaner.

This hook runs only for tasks whose instruction says to return only the short
answer. It removes generic surface wrappers that break exact-match scoring:
discourse lead-ins, parenthetical/bracket glosses, dash glosses, trailing
sentence punctuation, and wrapper articles. It then prefers the exact surface
form used by the supplied context, restores plural produce nouns, and extracts
the minimal head for bare role/title and pair/list clues.

It never calls a model and never changes the selected entity or term. All
edits are lexical and reversible by construction.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER = re.compile(r"^\[[^\]]*\]$")
_PAREN_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]*[\)\]]")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAILING_PUNCT_RE = re.compile(r"[.!?]+$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.[A-Za-z]\.?$")
_ARTICLE_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)
_OF_FROM_RE = re.compile(r"\b(of|from)\s+(.+)$", re.IGNORECASE)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|"
    r"berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|"
    r"why|how|his|her|he|she|him)\b",
    re.IGNORECASE,
)

_SHORT_FORM_MARKERS = (
    "term for",
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "mayor",
    "governor",
    "politician",
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-\.]*$")
_CATEGORY_SUFFIXES = (
    "party",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)
_TERM_OF_RE = re.compile(r"^(?P<head>[A-Za-z][A-Za-z'\-]*)\s+of\s+(?P<tail>.+)$")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _strip_bracket_wrappers(text: str) -> str:
    """Remove one matched pair of surrounding brackets/parentheses only when it
    wraps the whole phrase."""
    for open_ch, close_ch in (("(", ")"), ("[", "]")):
        if text.startswith(open_ch) and text.endswith(close_ch):
            inner = text[1:-1].strip()
            if inner and _norm_text(inner) == _norm_text(text):
                return inner
    return text


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized n-grams back to the surface phrases that produced them."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _phrase_quality(phrase: str) -> tuple:
    stripped = _strip_surrounding(phrase)
    bracket_penalty = sum(1 for ch in phrase if ch in "()[]")
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        stripped.count(" "),
        -stripped.count("-"),
        -bracket_penalty,
        len(stripped),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _echo_context_form(text: str, question: str) -> str:
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    key = _norm_text(text)
    if not key or key not in phrases:
        return text
    ctx = _context_text(question)
    best = _strip_surrounding(_best_phrase(phrases[key], ctx))
    return _strip_bracket_wrappers(best)


def _supported(phrase: str, question: str) -> bool:
    key = _norm_text(phrase)
    if not key:
        return False
    phrases, _ = _context_phrases(question)
    if key in phrases:
        return True
    return phrase.casefold() in question.casefold()


def _strip_parentheticals(text: str) -> str:
    cur = text
    for _ in range(8):
        nxt = _PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            cur = nxt
            continue
        break
    return cur


def _strip_dash_gloss(text: str, question: str) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _supported(before, question):
        return before
    return text


def _strip_lead(text: str) -> str:
    text = _LEAD_IN_RE.sub("", text).strip()
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail and len(tail.split()) >= 3:
            return tail
    return text


def _strip_trailing_punct(text: str) -> str:
    while True:
        match = _TRAILING_PUNCT_RE.search(text)
        if not match:
            return text
        if _ABBREV_RE.search(text):
            return text
        nxt = text[: match.start()].rstrip()
        if not nxt:
            return text
        text = nxt


def _strip_leading_article(text: str, question: str) -> str:
    """Drop a wrapper article only when the article-less form is itself
    supported by the task text. Preserves canonical phrases that genuinely
    begin with an article (titles, brand names, works of art)."""
    match = _ARTICLE_RE.match(text)
    if not match:
        return text
    rest = match.group("rest").strip()
    if not rest:
        return text
    if _supported(rest, question) and not _supported(text, question):
        return rest
    return text


def _plural_candidates(word: str) -> list[str]:
    if not word or word.endswith("s"):
        return []
    candidates = []
    if re.search(r"[^aeiou]y$", word, re.IGNORECASE):
        candidates.append(word[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", word, re.IGNORECASE):
        candidates.append(word + "es")
    candidates.append(word + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question: str) -> str:
    if len(text.split()) != 1:
        return text
    q = _question_line(question)
    if not _PRODUCE_RE.search(q):
        return text
    word = _strip_surrounding(text)
    if not word or word.endswith("s"):
        return text
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    for candidate in _plural_candidates(word):
        key = _norm_text(candidate)
        if key and key in phrases:
            ctx = _context_text(question)
            return _strip_surrounding(_best_phrase(phrases[key], ctx))
    return text


def _capitalized_words(text: str) -> list[str]:
    return [t for t in re.findall(r"[A-Za-z][A-Za-z'\-]*", text)]


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _extract_minimal_head(text: str, question: str) -> str:
    match = _OF_FROM_RE.search(text)
    if not match:
        return text
    tail = match.group(2).strip().strip(" .,;:!?\"'`")
    tail = re.sub(r"^(?:the|a|an)\s+", "", tail, flags=re.IGNORECASE)
    run: list[str] = []
    for tok in tail.split():
        if tok and tok[0].isupper() and not tok[0].isdigit():
            run.append(tok)
        else:
            break
    if len(run) != 1:
        return text
    candidate = run[0]
    return _echo_context_form(candidate, question) or candidate



def _looks_person_short_form(q: str) -> bool:
    ql = q.lower()
    return bool(_PERSON_DEMO_RE.search(q)) and any(
        role in ql for role in _PERSON_ROLE_WORDS
    )


def _looks_factual_person_statement(q: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(q)) and not bool(_PERSON_DEMO_RE.search(q))


def _name_tokens(text: str) -> list[str]:
    run: list[str] = []
    for tok in text.split():
        bare = _strip_surrounding(tok)
        if _NAME_TOKEN_RE.match(bare):
            run.append(bare)
        else:
            break
    return run


def _extract_person_subject(text: str, question: str) -> str:
    q = _question_line(question)
    if not _looks_factual_person_statement(q):
        return text
    words = text.split()
    if len(words) <= 4:
        return text
    run = _name_tokens(text)
    if not run:
        return text
    # Do not truncate a compact name that already occupies the whole text.
    if len(run) == len(words):
        return text
    return " ".join(run)


def _extract_surname(text: str, question: str) -> str:
    q = _question_line(question)
    if not _looks_person_short_form(q):
        return text
    toks = text.split()
    if not (2 <= len(toks) <= 3):
        return text
    if not all(_NAME_TOKEN_RE.match(_strip_surrounding(tok)) for tok in toks):
        return text
    surname = _strip_surrounding(toks[-1])
    phrases, _ = _context_phrases(question)
    if _norm_text(surname) not in phrases:
        return text
    return _echo_context_form(surname, question) or surname


def _extract_term_head(text: str, question: str) -> str:
    q = _question_line(question)
    if "term for" not in q.lower():
        return text
    match = _TERM_OF_RE.match(text)
    if not match:
        return text
    head = match.group("head").strip()
    if not (head and _supported(head, question)):
        return text
    # For definition/term clues the context often carries the article as part
    # of the answer phrase ("a transit"). Prefer that exact phrase when present.
    phrases, _ = _context_phrases(question)
    for article in ("a", "an", "the"):
        key = _norm_text(f"{article} {head}")
        if key in phrases:
            ctx = _context_text(question)
            return _strip_surrounding(_best_phrase(phrases[key], ctx)) or head
    return _echo_context_form(head, question) or head


def _strip_trailing_category(text: str, question: str) -> str:
    q = _question_line(question).lower()
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return text
    toks = text.split()
    if len(toks) < 2:
        return text
    last = _strip_surrounding(toks[-1]).lower()
    if last not in _CATEGORY_SUFFIXES:
        return text
    prefix = " ".join(toks[:-1])
    # Only strip a category suffix when the remaining form is still a
    # multi-token phrase. A single-token remainder is often a distractor or
    # needs the side verifier to check it against the question constraints.
    if len(prefix.split()) < 2:
        return text
    if _supported(prefix, question):
        return _echo_context_form(prefix, question) or prefix
    return text

def _clean(text: str, question: str) -> str:
    t = _strip_lead(text)
    t = _strip_parentheticals(t)
    t = _strip_dash_gloss(t, question)
    t = _strip_leading_article(t, question)
    t = _strip_trailing_punct(t)
    t = " ".join(t.split())
    t = _echo_context_form(t, question)

    if _short_answer_requested(question):
        q = _question_line(question)
        t = _extract_person_subject(t, question)
        t = _extract_surname(t, question)
        t = _extract_term_head(t, question)
        t = _strip_trailing_category(t, question)
        t = _prefer_plural_produce_form(t, question)
        if _is_role_title_clue(q) or _is_pair_list_clue(q):
            t = _extract_minimal_head(t, question)
        t = _echo_context_form(t, question)
    return t


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.6d8b40c868cd6c573d9bcb8bbf13e0a372980845:
"""Deterministic surface-only final-answer cleaner for short-answer QA.

This hook runs only when the user request contains the explicit short-answer
instruction (``return only the short answer``). It never calls a model and
never changes which entity or term the model selected: it removes generic
surface wrappers around an answer candidate and re-echoes the supplied
context's dominant surface form for the same normalized token sequence.

Removals are deliberately generic and reversible:

  * surrounding code fences / matched quotes
  * ``Answer is:`` / ``The answer is`` lead-ins
  * discourse lead-ins such as ``True -- ...``
  * a trailing sentence period (abbreviations and initialisms are preserved)
  * trailing parenthetical/bracket glosses
  * trailing em/en-dash glosses whose head is supported by the context
  * decorative trailing ``!``/``?`` marks when the base is context-supported
  * a leading article when the article-less form is context-supported
  * canonical surface echo: case, spacing, and hyphenation are copied from the
    most frequent supplied-context variant of the same normalized phrase
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_CODE_FENCE_RE = re.compile(r"^```[A-Za-z]*\s*\n(.*?)\n?```$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:-]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAIL_PAREN_RE = re.compile(r"\s*\([^()]{1,160}\)\s*$")
_TRAIL_BRACKET_RE = re.compile(r"\s*\[[^\[\]]{1,160}\]\s*$")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_TRAIL_PERIOD_RE = re.compile(r"\.$")
_TRAIL_BANG_RE = re.compile(r"[!?]+$")
_ARTICLE_RE = re.compile(r"^(a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)

_ABBREV_RE = re.compile(
    r"(?:\b[A-Za-z]\.){2,}$|\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", re.IGNORECASE
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    """Casefold and collapse every non-alphanumeric run to a single space."""
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _strip_surrounding(text: str) -> str:
    return (text or "").strip(" \t\r\n.,;:!?\"'`")


def _surface_map(question: str) -> dict[str, list[tuple[str, int]]]:
    """Map normalized n-gram keys to (surface, count) variants from context."""
    ctx = _context_text(question)
    surfaces: dict[str, list[tuple[str, int]]] = {}
    if not ctx:
        return surfaces

    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(6, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                phrase = " ".join(tokens[i : i + n])
                key = _chunk_key(phrase)
                if not key:
                    continue
                bucket = surfaces.setdefault(key, [])
                if all(surface != phrase for surface, _ in bucket):
                    bucket.append((phrase, 0))

    ctx_lower = ctx.lower()
    for key, bucket in surfaces.items():
        for idx, (surface, _) in enumerate(bucket):
            bucket[idx] = (surface, ctx_lower.count(surface.lower()))
    return surfaces


def _surface_quality(item: tuple[str, int], candidate: str) -> tuple:
    surface, count = item
    stripped = _strip_surrounding(surface)
    return (
        count,
        1 if surface.casefold() == candidate.casefold() else 0,
        1 if stripped[:1].isupper() else 0,
        1 if not stripped.isupper() else 0,
        -stripped.count("-"),
        -len(stripped),
    )


def _best_surface(bucket: list[tuple[str, int]], candidate: str) -> str:
    if not bucket:
        return candidate
    best = max(bucket, key=lambda item: _surface_quality(item, candidate))
    return _strip_surrounding(best[0])


def _has_key(text: str, surfaces: dict) -> bool:
    key = _chunk_key(text)
    return bool(key) and key in surfaces


def _strip_code_fence(text: str) -> str:
    match = _CODE_FENCE_RE.match(text.strip())
    if match:
        return match.group(1).strip()
    return text


def _strip_surrounding_quotes(text: str) -> str:
    t = text.strip()
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                return inner
    return t


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_RE.match(text.strip())
    if match and match.group("tail").strip():
        return match.group("tail").strip()
    return text


def _strip_answer_lead(text: str) -> str:
    return _LEAD_IN_RE.sub("", text.strip()).strip()


def _strip_trailing_parentheticals(text: str) -> str:
    cur = text.strip()
    for _ in range(8):
        prev = cur
        for pattern in (_TRAIL_PAREN_RE, _TRAIL_BRACKET_RE):
            match = pattern.search(cur)
            if match:
                nxt = cur[: match.start()].strip()
                if nxt and nxt != cur:
                    cur = nxt
                    break
        if cur == prev:
            break
    return cur


def _strip_trailing_dash_gloss(text: str, surfaces: dict) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _has_key(before, surfaces):
        return before
    return text


def _strip_trailing_period(text: str, surfaces: dict) -> str:
    cur = text.strip()
    for _ in range(4):
        if not cur.endswith(".") or cur.endswith(".."):
            break
        if _ABBREV_RE.search(cur):
            break
        nxt = cur[:-1].rstrip()
        if not nxt:
            break
        if cur[-2].islower() or cur[-2] in ")]}\"'" or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_trailing_bang(text: str, surfaces: dict) -> str:
    """Strip decorative trailing !/? when the base is context-supported or the
    mark is doubled. Repeated marks are surface decoration, not an entity."""
    cur = text.strip()
    for _ in range(4):
        match = _TRAIL_BANG_RE.search(cur)
        if not match:
            break
        run = match.group(0)
        nxt = cur[: match.start()].rstrip()
        if not nxt:
            break
        if len(run) >= 2 or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_leading_article(text: str, surfaces: dict) -> str:
    match = _ARTICLE_RE.match(text.strip())
    if not match:
        return text.strip()
    rest = match.group("rest").strip()
    if not rest:
        return text.strip()
    if _has_key(rest, surfaces) or rest[0].isupper() or rest[0].isdigit():
        return rest
    return text.strip()


def _echo_context_form(text: str, surfaces: dict, original: str) -> str:
    key = _chunk_key(text)
    if not key or key not in surfaces:
        return text
    return _best_surface(surfaces[key], original)


def _clean(original: str, question: str) -> str:
    surfaces = _surface_map(question)

    text = original.strip()
    text = _strip_code_fence(text)
    text = _strip_surrounding_quotes(text)
    text = _strip_discourse_lead(text)
    text = _strip_answer_lead(text)
    text = _strip_trailing_dash_gloss(text, surfaces)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_parentheticals(text)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_bang(text, surfaces)
    text = _strip_leading_article(text, surfaces)

    # Canonicalize spacing/case/hyphenation from the supplied context.
    text = _echo_context_form(text, surfaces, original)

    # Echo may re-introduce decorative title punctuation; strip it one final
    # time without re-echoing so we do not undo the punctuation cleanup.
    text = _strip_trailing_bang(text, surfaces)

    return " ".join(text.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.6ffdfdf0a5b175bb1c452895238558bb9a7210f9:
"""Bounded primary-model self-correction for short-answer format failures.

After the deterministic cleaner runs, this hook asks the primary model for up
to two bounded attempts when the candidate still looks like prose, is a longer
context phrase whose shorter prefix is the requested form, is a full person name
for a Jeopardy-style person clue, or is a multi-word non-context draft. It is
deliberately conservative:

  * only tasks with an explicit "return only the short answer" instruction;
  * at most two continuations per task (the runtime's turn budget is checked);
  * clean compact context phrases are never re-rolled.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "referred to as",
    "called it",
    "term for",
    "surname",
    "acronym",
    "pre-",
    "company",
    "network",
    "association",
    "organization",
    "organisation",
    "mint",
    "radio",
)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_PROSE_WORDS_RE = re.compile(
    r"\b(the|a|an|from|of|and|in|for|with|to|as|by|is|was|were|are)\b",
    re.IGNORECASE,
)
_LEAD_IN_RE = re.compile(
    r"^(true|false|yes|no|correct|right|answer|note|indeed)\b", re.IGNORECASE
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in (text or "").split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for seg in _MARKER_RE.split(ctx):
        toks = []
        for raw in seg.split():
            norm = _norm_token(raw)
            if norm:
                toks.append(norm)
        max_n = min(5, len(toks))
        for n in range(1, max_n + 1):
            for i in range(len(toks) - n + 1):
                keys.add("".join(toks[i : i + n]))
    return keys


def _looks_like_prose(text: str, ctx_keys: set[str] | None = None) -> bool:
    words = text.split()
    if len(words) >= 6:
        return True
    if _LEAD_IN_RE.match(text):
        return True
    if len(words) >= 3:
        is_ctx = bool(ctx_keys) and _norm_text(text) in ctx_keys
        if is_ctx and not _SENTENCE_END_RE.search(text):
            return False
        if _SENTENCE_END_RE.search(text) or _PROSE_WORDS_RE.search(text):
            return True
    return False


def _looks_overexpanded(text: str, question: str, ctx_keys: set[str]) -> bool:
    """Compact context phrase that is longer than the requested short form."""
    q = _question_line(question).lower()
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False
    words = text.split()
    if len(words) < 3:
        return False
    full_key = _norm_text(text)
    if full_key not in ctx_keys:
        return False
    for n in range(len(words) - 1, 0, -1):
        prefix_key = _norm_text(" ".join(words[:n]))
        if prefix_key in ctx_keys:
            return True
    return False


def _looks_full_name_draft(text: str, question: str, ctx_keys: set[str]) -> bool:
    """Full first+last name for a Jeopardy-style 'this ...'/'whose ...' clue."""
    q = _question_line(question).lower()
    if _PERSON_PRONOUN_RE.search(q):
        return False
    if not _PERSON_DEMO_RE.search(q):
        return False
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return False

    words = text.split()
    if len(words) not in (2, 3):
        return False
    if not all(_NAME_TOKEN_RE.match(w) for w in words):
        return False
    surname_key = _norm_text(words[-1])
    return bool(surname_key and surname_key in ctx_keys)


def _looks_non_context(text: str, ctx_keys: set[str]) -> bool:
    words = text.split()
    if len(words) < 3:
        return False
    return _norm_text(text) not in ctx_keys


def _feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare requested item.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item, then reply with only that item. Use the exact wording "
        "from the supplied context and the shortest form that still satisfies "
        "every clue (nickname, surname, term, acronym, or short label rather "
        "than a full name, title, date, or organization expansion). Do not "
        "include any explanation, lead-in, parenthetical, or punctuation that "
        "is not part of the requested item."
    )


def _person_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "This is a Jeopardy-style person clue, so the requested answer is the "
        "person's surname/target name only, not a full first+last name.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Return only the surname/target name exactly as the supplied context "
        "gives it, with no first name, dates, or extra words."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_retry"]
    fired = state.get("fired", 0)
    if fired >= 2:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    ctx_keys = _context_phrase_keys(ctx.question)

    if _looks_like_prose(original, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _feedback(original)}

    if _looks_full_name_draft(original, ctx.question, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _person_feedback(original)}

    if _looks_overexpanded(original, ctx.question, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _feedback(original)}

    if _looks_non_context(original, ctx_keys):
        state["fired"] = fired + 1
        return {"action": "continue", "feedback": _feedback(original)}

    return None

texts.7d9a8f9e7a627ddfe072ff9b4a15b3ff04192dbe:
"""Bounded primary-model self-correction for short-answer output format.

Runs after the deterministic cleaner and side verifier. When the remaining
candidate still looks like prose, or is a context phrase that is longer than the
short form requested by the clue, this hook asks the primary model for one more
bounded attempt. It also escalates when the side verifier ran but could not
produce a context-backed correction, and when the side verifier kept a draft for
a high-risk numeric/definition clue.

Clean short phrases are never re-rolled, and the runtime's final-continue and
remaining-turn budgets bound the retry.
"""

from __future__ import annotations

import re
from typing import Any

_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_ARTICLE_OPEN_RE = re.compile(r"^(?:a|an|the)\s+", re.I)
_MARKER = re.compile(r"^\[[^\]]*\]$")
_SHORT_FORM_MARKERS = (
    "term for",
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "pre-",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
)
_UNRESOLVED_ESCALATE = {"side_unavailable", "non_context", "side_longer"}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    sequences: list[list[str]] = []
    current: list[str] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append(norm)
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                keys.add("".join(seq[i : i + n]))
    return keys


def _looks_like_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 7:
        return True
    if len(words) >= 4 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    if (
        len(words) == 2
        and _ARTICLE_OPEN_RE.match(text)
        and _SENTENCE_END_RE.search(text)
    ):
        return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    q = _question_line(question).lower()
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False
    words = text.split()
    if len(words) < 3:
        return False
    ctx_keys = _context_phrase_keys(question)
    if _norm_text(text) not in ctx_keys:
        return False
    for n in range(len(words) - 1, 0, -1):
        prefix_key = _norm_text(" ".join(words[:n]))
        if prefix_key in ctx_keys:
            return True
    return False


def _looks_like_overanswer(text: str, question: str) -> bool:
    return _looks_like_prose(text) or _looks_overexpanded(text, question)


def _feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" Your previous "
        "answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "or trailing punctuation."
    )


def _constraint_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A side-check did not establish your previous answer as the exact "
        "context phrase that satisfies every clue.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and list every explicit constraint (numbers, "
        "dates, denominations, abbreviations, functions, relationships, and the "
        "requested short form). Then find the single context phrase that "
        "satisfies all of those constraints. If a candidate matches only a "
        "keyword but conflicts with a number, date, denomination, or function, "
        "discard it. Return only that exact context phrase, with no extra words."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    if not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_retry"]
    if state.get("fired", 0) >= 1:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    original = (candidate or "").strip()
    if _looks_like_overanswer(original, ctx.question):
        state["fired"] = 1
        return {"action": "continue", "feedback": _feedback(original)}

    verify_state = ctx.state["short_answer_verify"]
    unresolved = verify_state.get("unresolved")
    should_escalate = unresolved in _UNRESOLVED_ESCALATE or (
        unresolved == "keep" and verify_state.get("keep_risk") == "high"
    )
    if should_escalate:
        state["fired"] = 1
        return {"action": "continue", "feedback": _constraint_feedback(original)}

    return None

texts.7f0fe9bf368975887d7ddc3aa29efabde53a3cf3:
"""Deterministic surface cleaner for short-answer QA.

Runs only when the user explicitly requested a bare short answer
(``return only the short answer``). It performs reversible, lexical-only
normalization on the final answer:

  * strip code fences and a matched pair of surrounding quotes
  * strip ``answer is / answer:`` lead-ins
  * strip a single sentence-final period (initialisms and abbreviations are
    preserved)
  * strip trailing parenthetical/bracket glosses and short dash glosses
  * strip a leading article only when the article-less form is a supplied
    context phrase
  * echo the supplied context's exact surface form for the remaining token
    sequence, so spacing, capitalization, and hyphenation come from the task
    text rather than from the model's paraphrase

It never calls a model and never changes which entity or term is selected:
it only removes wrapper text around the answer and normalizes the surface
spelling of the selected term to the form already present in the context.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_ARTICLE_RE = re.compile(r"^(a|an|the)\s+(.+)$", re.IGNORECASE)
_DISCOURSE_LEAD = {
    "true",
    "false",
    "yes",
    "no",
    "correct",
    "right",
    "answer",
    "note",
    "indeed",
}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    """Return a casefolded alphanumeric-chunk key for a phrase.

    Non-word characters (including hyphens, asterisks, apostrophes, and other
    punctuation) are treated as chunk separators. Unicode letters are
    preserved, so an accented name does not collide with an unaccented one.
    """
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _build_surface_map(question: str) -> dict[str, dict[str, int]]:
    """Map each context n-gram chunk key to its verbatim surface forms.

    Counts are kept per surface so the dominant context spelling can be
    selected when the same token sequence appears in several typographic
    variants (for example space-separated versus hyphenated).
    """
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(5, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                phrase = " ".join(tokens[i : i + n])
                key = _chunk_key(phrase)
                bucket = surfaces.setdefault(key, {})
                bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _strip_code_fences_and_quotes(text: str) -> str:
    t = (text or "").strip()
    if t.startswith("```") and t.endswith("```") and len(t) > 6:
        inner = t[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            t = inner
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                t = inner
                break
    return t.strip()


def _strip_lead_in(text: str) -> str:
    return _LEAD_IN_RE.sub("", (text or "").strip()).strip()


def _strip_sentence_period(text: str, surfaces: dict[str, dict[str, int]]) -> str:
    t = (text or "").strip()
    if not (t.endswith(".") and not t.endswith("..") and len(t) > 2):
        return t
    # Preserve initialisms (U.S.), single initials, and common abbreviations.
    if re.search(r"\b[A-Za-z](\.[A-Za-z])+\.?$", t):
        return t
    if re.match(r"^[A-Za-z]\.$", t):
        return t
    if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", t, re.IGNORECASE):
        return t
    nxt = t[:-1].rstrip()
    if (
        _chunk_key(nxt) in surfaces
        or t[-2].islower()
        or t[-2] in ")]}\"'`"
    ):
        return nxt
    return t


def _strip_surrounding(text: str) -> str:
    """Remove surrounding separators while preserving internal punctuation.

    Trailing question/exclamation marks are deliberately preserved so a later
    hook can decide whether they are decorative rather than part of the title.
    """
    return (text or "").strip(" \t\r\n.,;:\"'`—-")


def _best_surface(bucket: dict[str, int]) -> str:
    """Pick the dominant, cleanest context surface for a chunk key."""

    def quality(item: tuple[str, int]) -> tuple:
        surface, count = item
        cleaned = _strip_surrounding(surface)
        title_case = 1 if cleaned[:1].isupper() else 0
        all_caps = 1 if cleaned.isupper() else 0
        return (count, title_case, -all_caps, -len(cleaned))

    best = max(bucket.items(), key=quality)[0]
    return _strip_surrounding(best)


def _clean(candidate: str, question: str) -> str:
    surfaces = _build_surface_map(question)

    t = _strip_code_fences_and_quotes(candidate)
    t = _strip_lead_in(t)

    # Iteratively remove one surface wrapper at a time. The order and the
    # context checks keep the pass lexical and reversible.
    for _ in range(8):
        prev = t

        nxt = _strip_sentence_period(t, surfaces)
        if nxt != t:
            t = nxt
            continue

        # Trailing parenthetical gloss, e.g. "M*A*S*H (1970)" -> "M*A*S*H".
        m = re.search(r"\s*\([^()]{1,80}\)\s*$", t)
        if m:
            nxt = t[: m.start()].strip()
            if nxt:
                t = nxt
                continue

        # Trailing bracketed gloss.
        m = re.search(r"\s*\[[^\[\]]{1,80}\]\s*$", t)
        if m:
            nxt = t[: m.start()].strip()
            if nxt:
                t = nxt
                continue

        # Trailing dash gloss, but never strip a bare discourse lead-in such
        # as "True — ..." into just "True".
        m = re.search(r"\s+[—–-]\s+(.+)$", t, re.DOTALL)
        if m:
            before = t[: m.start()].strip()
            if (
                before
                and before.lower() not in _DISCOURSE_LEAD
                and _chunk_key(before) in surfaces
            ):
                t = before
                continue

        # Leading article, only when the article-less form is itself a
        # supplied context phrase.
        m = _ARTICLE_RE.match(t)
        if m:
            rest = m.group(2).strip()
            if rest and _chunk_key(rest) in surfaces:
                t = rest
                continue

        if t == prev:
            break

    # Echo the context's dominant surface form for the cleaned token sequence.
    key = _chunk_key(t)
    bucket = surfaces.get(key)
    if bucket:
        t = _best_surface(bucket)

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare context-supported surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        return {"action": "replace", "answer": cleaned}
    return None

texts.7f7196972c75fd0541791c4eb2af26b147305016:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. A numeric/currency constraint gap between the candidate and the question.
2. Prose-like candidate under an explicit "return only the short answer"
   instruction.
3. A non-person, non-quoted context phrase that is overexpanded for an
   "of these/those" category clue, where a shorter prefix/suffix is itself a
   context phrase. This replaces the previous broad "overexpanded short form"
   trigger with a narrow, category-clue-only path that never asks the model to
   shorten a person's full name.
4. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
5. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").
6. A one-word produce/plant candidate with a same-stem context variant
   (usually singular vs plural).

The previous narrow "quote-echo" trigger was removed: unconditionally treating
a candidate equal to a 'these/those'-introduced quoted phrase as wrong is not
universally valid. The non-context feedback instead tells the model not to echo
a quoted clue descriptor and to return the category/entity it describes.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_OF_THESE_RE = re.compile(r"\bof\s+(?:these|those)\b", re.IGNORECASE)
_QUOTED_PHRASE_RE = re.compile(r'"([^"]+)"')


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _word_in_text(word: str, text: str) -> bool:
    key = _norm_token(word)
    if not key:
        return False
    return key in {_norm_token(tok) for tok in (text or "").split() if _norm_token(tok)}


def _candidate_is_question_quote(text: str, question_line: str) -> bool:
    cand_key = _norm_text(text)
    if not cand_key:
        return False
    for match in _QUOTED_PHRASE_RE.finditer(question_line):
        quoted = match.group(1).strip()
        if _norm_text(quoted) != cand_key:
            continue
        prefix = question_line[: match.start()].rstrip()
        if re.search(r"\b(?:these|those)\s*$", prefix, re.IGNORECASE):
            return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    """Return True only for non-person category answers with redundant words.

    This is intentionally narrow: it fires only for "of these/those" category
    clues, never for a candidate that echoes the question's own quoted phrase,
    and only when the candidate is itself a context phrase with a shorter
    context prefix or a question-duplicated leading qualifier. Person-name
    candidates are not shortened here; the cleaner and this hook's other
    triggers handle surface form separately.
    """
    text = (text or "").strip()
    words = text.split()
    if len(words) < 2:
        return False

    qline = _question_line(question)
    if not _OF_THESE_RE.search(qline):
        return False
    if _candidate_is_question_quote(text, qline):
        return False

    keys = _context_phrase_keys(question)
    key = _norm_text(text)
    if key not in keys:
        return False

    # A shorter leading prefix that is itself a context phrase means the draft
    # carries extra trailing words beyond the requested category head.
    for n in range(1, len(words)):
        if _norm_text(" ".join(words[:n])) in keys:
            return True

    # A shorter trailing suffix that is itself a context phrase and whose
    # dropped leading words are already stated in the question means those
    # leading words are redundant qualifiers.
    for n in range(1, len(words)):
        suffix = " ".join(words[n:])
        if _norm_text(suffix) in keys and all(
            _word_in_text(word, qline) for word in words[:n]
        ):
            return True

    return False


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _short_form_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is a fuller context phrase than the category the "
        "clue asks for.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question. For a clue of the form 'one/these/those ...', "
        "return the general category or term named by the context, dropping "
        "qualifiers that are already stated in the question. Do NOT shorten a "
        "person's full name to a surname or replace a name with an epithet. "
        "If the shorter phrase no longer satisfies every clue, keep the full "
        "phrase. Return only the corrected exact phrase."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. If the question quotes a phrase such as 'one of "
        "these \"...\"', do not echo that quoted phrase; name the category or "
        "entity it describes, using the exact context wording. Do not include "
        "any lead-in, explanation, parenthetical, gloss, date, or extra "
        "punctuation. If the question is a definition or category clue "
        "(\"An X that does Y\", \"this type of ...\", \"the term for ...\"), "
        "return the general category or term whose function the context states, "
        "not a specific example that shares only one property. If your previous "
        "answer was the right entity but the wrong singular/plural or surface "
        "form, fix only that form and keep the entity."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: non-person, non-quoted overexpanded category phrase.
    if state.get("overexpanded_fired", 0) < 1 and _looks_overexpanded(
        original, ctx.question
    ):
        state["overexpanded_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_overexpanded", candidate=original)
        return {"action": "continue", "feedback": _short_form_feedback(original)}

    # Trigger 3: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.822c791e6b5cd1007cbf96a668c24423225d8309:
"""Pre-flight short-answer format and question-shape reminder.

When the user's request explicitly requires a bare short answer, this hook adds
a one-time reminder immediately before the first LLM call. The reminder repeats
the user's output contract plus the canonical-surface-form rule, and appends a
single question-shape directive when the question matches a high-risk pattern
from the measured failure modes:

  * "one of these/those" with a quoted phrase: the quote is a clue, not the
    answer
  * "type of ..." clues: return the specific named type, not the general class
  * factual-person clues that quote a title: return the person, not the title
  * definition/category clues: return the general term, not a named example

It is deliberately tiny and bounded: it fires only once per task (turn 1) and
only when the exact benchmark instruction is present, so it adds a small, fixed
prompt cost and never loops or re-rolls.

The primary model remains the sole author of the final answer; this hook only
makes the output contract and the question-shape guidance the most recent
instruction before the model's first attempt.
"""

from __future__ import annotations

import re
from typing import Any

_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_PHRASE_RE = re.compile(r'"[^"]+"')
_TYPE_OF_RE = re.compile(r"\btype of\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(?:he|she|his|her)\b", re.IGNORECASE)
_DEFINITION_START_RE = re.compile(r"^(?i:an?|the)\s+(?-i:[a-z])")
_DEFINITION_MARKER_RE = re.compile(
    r"\b(?:the term for|the crime for which|it's the)\b", re.IGNORECASE
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _shape_note(q: str) -> str | None:
    """Return a one-line high-risk shape directive, or None if none applies."""
    if not q:
        return None

    # Order matters: a "one of these ..." clue with a quoted phrase should not
    # be mistaken for a factual-person quote clue, and a definition start such
    # as "An astringent ..." should not be matched by the type-of rule.
    if _ONE_OF_THESE_RE.search(q) and _QUOTED_PHRASE_RE.search(q):
        return (
            "Question shape: this is a 'one of these/those' clue. The quoted "
            "phrase is a clue, not the answer; return the category or entity it "
            "describes, copied verbatim from the supplied context."
        )
    if _TYPE_OF_RE.search(q):
        return (
            "Question shape: this is a 'type of ...' clue. Return the specific "
            "type named in the supplied context, not the general category and "
            "not a general descriptor such as 'modern ...' or 'regular ...'."
        )
    if _PERSON_PRONOUN_RE.search(q) and _QUOTED_PHRASE_RE.search(q):
        return (
            "Question shape: the question describes a person and quotes a title "
            "or phrase. Return the person the statement is about, not the quoted "
            "title or phrase."
        )
    if _DEFINITION_MARKER_RE.search(q) or _DEFINITION_START_RE.match(q.strip()):
        return (
            "Question shape: this is a definition/category clue. Return the "
            "general category or term whose function the supplied context states, "
            "not a specific example that shares only one property."
        )
    return None


async def before_llm(messages: list[dict], ctx: Any) -> list[dict]:
    """Append a one-turn format and shape reminder when the task demands a bare answer."""
    if ctx.turn != 1:
        return messages
    if not _short_answer_requested(ctx.question):
        return messages

    content = (
        "Format reminder: the user's request says \"Return only the short "
        "answer.\" Your final message must be exactly the requested answer "
        "phrase and nothing else. Copy the exact wording from the supplied "
        "context (spelling, capitalization, hyphens, and name extent). No "
        "sentence, lead-in, explanation, parenthetical, citation, markdown, "
        "quote, or trailing punctuation."
    )
    note = _shape_note(_question_line(ctx.question))
    if note:
        content += " " + note

    reminder = {"role": "user", "content": content}
    return messages + [reminder]

texts.84d6c9488fb43d1748a8f210183bc02190e4e56c:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate that is a verbatim context phrase but has a shorter context-phrase
   prefix/suffix while the question asks for a short form, or is a two/three-
   token full name for a "this ..."/"whose ..." clue whose surname alone is
   also a context phrase.
4. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

# Strong cues that the requested form is shorter than the full context phrase.
_SHORT_FORM_MARKERS = (
    "known as",
    "nickname",
    "nicknamed",
    "called",
    "referred to as",
    "term for",
    "type of",
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
    "alliance",
    "surname",
    "acronym",
    "short name",
    "initials",
)

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    q = _question_line(question).lower()
    words = text.split()
    if len(words) < 2:
        return False

    keys = _context_phrase_keys(question)
    key = _norm_text(text)
    if key not in keys:
        return False

    # A two/three-token full name for a "this ..."/"whose ..." clue whose
    # surname alone is also a context phrase is likely over-expanded.
    if len(words) in (2, 3):
        if all(_NAME_TOKEN_RE.match(word) for word in words):
            if ("this" in q or "whose" in q) and _norm_text(words[-1]) in keys:
                return True

    # Otherwise only short-form cues justify asking for a shorter phrase.
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False

    for n in range(1, len(words)):
        if _norm_text(" ".join(words[:n])) in keys:
            return True
    last = _norm_text(words[-1])
    if last in keys and last != key:
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not include any lead-in, explanation, "
        "parenthetical, gloss, date, or extra punctuation."
    )


def _short_form_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer appears to be longer than the requested short "
        "form, or uses a fuller name than the clue asks for.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question. Determine the shortest exact phrase from the "
        "supplied context that still satisfies every clue (for example a "
        "nickname, term, acronym, surname, or short company/network/mint/"
        "association name). If the shorter phrase no longer satisfies every "
        "clue, keep the full phrase. Return only the correct exact phrase."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 3: candidate is a context phrase but longer than the requested
    # short form. The primary model decides whether a shorter phrase is valid.
    if state.get("overexpanded_fired", 0) < 1 and _looks_overexpanded(
        original, ctx.question
    ):
        state["overexpanded_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_overexpanded", candidate=original)
        return {"action": "continue", "feedback": _short_form_feedback(original)}

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.8510a98f88bdf9498fd5a6c8c2bfe6d3814e996b:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").
4. A one-word produce/plant candidate with a same-stem context variant
   (usually singular vs plural).

It also includes two deterministic wrong-entity triggers:

5. A "one of these/those" clue whose candidate merely echoes the quoted clue
   phrase instead of naming the category/entity it describes.
6. A bare list clue whose candidate is a descriptive lower-case phrase about
   the listed people/items instead of the shared title/label/location.

The previous "overexpanded short form" trigger has been removed: asking the
primary model to shorten a correct full name was causing exact-match regressions
(Oliver Brown -> Brown, Daniel Boone -> Boone, Ace Hardware -> Ace). This hook
no longer requests a shorter form for any context phrase.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_QUESTION_WORD_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"he|she|his|her|him)\b",
    re.IGNORECASE,
)
_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_PHRASE_RE = re.compile(r'"([^"]+)"')

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _is_bare_list_clue(q: str) -> bool:
    if not q or "," not in q:
        return False
    if _QUESTION_WORD_RE.search(q):
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 6):
        return False
    return all(any(ch.isupper() for ch in part) for part in parts)


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. If the question quotes a phrase such as 'one "
        "of these \"...\"', do not echo that quoted phrase; name the "
        "category or entity it describes, using the exact context wording. "
        "If the question is a definition or category clue (\"An X that does "
        "Y\", \"this type of ...\", \"the term for ...\"), return the "
        "general category or term whose function the context states, not a "
        "specific example that shares only one property. If your previous "
        "answer was the right entity but the wrong singular/plural or surface "
        "form, fix only that form and keep the entity. Do not include any "
        "lead-in, explanation, parenthetical, gloss, date, or extra punctuation."
    )


def _echoed_clue_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "This is a 'one of these/those' clue. Your previous answer echoes the "
        "quoted phrase from the question, but the requested short answer is the "
        "category or entity that the quoted phrase describes.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the category "
        "or entity that the quoted phrase describes (for example the object, "
        "class, or term), and return only that exact context phrase, with no "
        "lead-in, explanation, or extra punctuation."
    )


def _bare_list_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "This is a bare list clue. Your previous answer describes the listed "
        "people or items, but the requested short answer is the shared title, "
        "label, or location that the supplied context gives for the whole list.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and return only the shared title, label, "
        "or location, copied verbatim from the context. Do not return a "
        "description of the people or items."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 2.5: "one of these/those" candidate that only echoes the quoted
    # clue phrase instead of naming the category/entity it describes.
    if state.get("echoed_clue_fired", 0) < 1:
        q = _question_line(ctx.question)
        if _ONE_OF_THESE_RE.search(q):
            quoted = _QUOTED_PHRASE_RE.findall(q)
            key = _norm_text(original)
            if key and any(key == _norm_text(phrase) for phrase in quoted):
                state["echoed_clue_fired"] = 1
                state["fired"] = state.get("fired", 0) + 1
                ctx.trace.event(
                    "short_answer_retry_echoed_clue", candidate=original
                )
                return {
                    "action": "continue",
                    "feedback": _echoed_clue_feedback(original),
                }

    # Trigger 2.6: bare list clue answered with a lower-case descriptive phrase
    # about the listed people/items rather than the shared title/label/location.
    if state.get("bare_list_descriptor_fired", 0) < 1:
        q = _question_line(ctx.question)
        if _is_bare_list_clue(q) and original and not original[:1].isupper():
            state["bare_list_descriptor_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event(
                "short_answer_retry_bare_list_descriptor", candidate=original
            )
            return {
                "action": "continue",
                "feedback": _bare_list_feedback(original),
            }

    # Trigger 3: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 4: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.8746d579fc733f61c19a900cead888230a3d210e:
"""Bounded side-model verification gate for short-answer QA.

Runs after the deterministic cleaner and the primary-model retry hooks, so it
only inspects candidates those hooks already accepted. It asks a side model to
re-derive the answer and judge the draft. When the verdict is WRONG it returns
a bounded ``continue`` so the primary model gets one more attempt with the
reason.

The side model never authors the final answer: it only supplies a verdict and
a short reason. The primary model remains the sole author of the final message.

The side prompt is augmented with a short question-shape focus so the checker
applies the right standard for the failure-prone shapes in this task family:
definition/category clues must not accept a salient example, "one of
these/those" clues must not accept an echoed quoted phrase, and bare quoted
fragment clues must not default to the most frequent matching article.

Bounds:
  * at most two side calls per task
  * at most one ``continue`` from this hook per task
  * candidates that the deterministic cleaner just produced are trusted and
    skipped (the cleaner only strips surface wrappers around a selected entity)
  * single-token candidates are skipped; the retry hook handles their
    inflection/plural mismatches
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_DEFINITION_START_RE = re.compile(r"^(?:an?|the)\s+[a-z]", re.IGNORECASE)
_DEFINITION_MARKER_RE = re.compile(
    r"\b(?:the term for|this type of|type of|the crime for which|it's the)\b",
    re.IGNORECASE,
)
_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_FRAGMENT_RE = re.compile(r'^"(?:\.\.\.)?[^"]*"$')


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrase_keys(question: str) -> set[str]:
    """Return normalized n-gram keys for the supplied context (up to 6 tokens)."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _is_definition_category_clue(q: str) -> bool:
    if not q:
        return False
    if _DEFINITION_MARKER_RE.search(q):
        return True
    return bool(_DEFINITION_START_RE.match(q))


def _question_shape_focus(question: str) -> str | None:
    """Return the checker standard for this question shape, if one applies."""
    q = _question_line(question)
    if not q:
        return None
    if _is_definition_category_clue(q):
        return (
            "The question is a definition/category clue. The draft is CORRECT "
            "only if it names the general category or term whose function the "
            "context states. Reject a draft that is only a salient example "
            "sharing one property."
        )
    if _ONE_OF_THESE_RE.search(q):
        return (
            "The question asks for the category or entity described by a quoted "
            "phrase. Reject a draft that merely echoes the quoted phrase."
        )
    if _QUOTED_FRAGMENT_RE.match(q.strip()):
        return (
            "The question is a bare quoted fragment that may match many "
            "passages. Prefer the passage where the fragment occurs as a "
            "contiguous part of a title and judge the draft against that "
            "passage's entity; do not accept the most frequent matching artist "
            "or article solely because it appears often."
        )
    return None


def _prompt(question: str, draft: str) -> str:
    focus = _question_shape_focus(question)
    prompt = (
        "You are checking a short-answer draft for an exact-match grader. "
        "Use ONLY the supplied context below.\n\n"
        "Step 1: Determine the single correct short answer.\n"
        "- Apply every clue and constraint in the question.\n"
        "- Choose the context passage that satisfies all of them.\n"
        "- For a definition/category clue (\"An X that does Y\", \"the term for ...\", "
        "\"this type of ...\"), return the general category or term whose function "
        "is stated, not a salient example sharing only one property.\n"
        "- For a person clue, verify every stated fact, number, date, or role is "
        "stated in the chosen person's passage.\n"
        "- Use the exact wording from the supplied context for the requested form "
        "(short name, surname, plural, hyphenation).\n"
    )
    if focus:
        prompt += focus + "\n"
    prompt += (
        "Step 2: Compare your answer to the draft below. Do not write out your answer.\n\n"
        + question
        + "\n\nDraft answer:\n"
        + draft
        + "\n\n"
        "End your reply with exactly one line, either:\n"
        "CORRECT\n"
        "or\n"
        "WRONG <brief reason the draft fails, without stating the correct answer>"
    )
    return prompt


def _parse_verdict(text: str) -> tuple[str | None, str]:
    """Return (verdict, reason) from the last recognizable verdict line."""
    verdict: str | None = None
    reason = ""
    lines = [line.strip() for line in (text or "").splitlines() if line.strip()]
    for i, line in enumerate(lines):
        match = re.match(r"^(CORRECT|WRONG)\b[:\-]?\s*(.*)$", line, re.IGNORECASE)
        if not match:
            continue
        verdict = match.group(1).lower()
        reason = match.group(2).strip()
        if not reason and verdict == "wrong" and i + 1 < len(lines):
            nxt = lines[i + 1]
            if not re.match(r"^(CORRECT|WRONG)\b", nxt, re.IGNORECASE):
                reason = nxt
    return verdict, reason


def _feedback(draft: str, reason: str) -> str:
    reason_text = f" It said: {reason}" if reason else ""
    return (
        "The instruction says: \"Return only the short answer.\" "
        "An independent check found that your previous answer may not satisfy "
        "every clue in the question or may not be the exact requested form."
        + reason_text
        + "\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "If your previous answer already satisfies every clue and is copied "
        "verbatim from the supplied context, return it unchanged. Otherwise list "
        "every explicit clue and constraint, find the single context phrase that "
        "satisfies all of them, and discard a specific example or partial match "
        "when the question asks for a general category or term. Return only the "
        "corrected short answer, copied verbatim from the supplied context."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Judge a settled short-answer candidate and, on a wrong verdict, ask the
    primary model for one more bounded attempt."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    words = original.split()
    if len(words) < 2:
        return None

    # The deterministic cleaner only removes wrappers around a selected entity.
    # Trusting its replacement avoids spending side calls on already-cleaned
    # surface form and keeps this gate focused on wrong-entity selection.
    clean_state = ctx.state.get("short_answer_clean") or {}
    if clean_state.get("replaced_this_turn"):
        return None

    context_keys = _context_phrase_keys(ctx.question)
    if _norm_text(original) not in context_keys:
        return None

    state = ctx.state.setdefault("short_answer_verify", {})
    if state.get("continued", 0) >= 1:
        return None
    if state.get("side_calls", 0) >= 2:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    state["side_calls"] = state.get("side_calls", 0) + 1
    try:
        extracted = await ctx.side_text(
            _prompt(ctx.question, original),
            purpose="short_answer_verify",
            max_tokens=120,
        )
    except Exception as e:
        ctx.trace.event("short_answer_verify_error", error=str(e))
        return None

    if not extracted:
        return None

    verdict, reason = _parse_verdict(extracted)
    if verdict == "correct":
        ctx.trace.event("short_answer_verify_accept", draft=original)
        return None

    if verdict != "wrong":
        ctx.trace.event(
            "short_answer_verify_ignored",
            reason="unrecognized_verdict",
            side=extracted,
        )
        return None

    ctx.trace.event("short_answer_verify_wrong", draft=original, reason=reason)
    state["continued"] = 1
    return {"action": "continue", "feedback": _feedback(original, reason)}

texts.888723ee99b3dbdd9cd4a47667cc63fea0f0e65f:
"""Side-LLM canonical short-answer verifier.

Runs after the deterministic cleaner. For short-answer QA, one bounded side
call re-derives the single correct answer from the supplied context and maps
it back to the exact context surface form. It only replaces the draft when the
side answer is a verbatim context phrase, is no longer than the draft, and is
not a forbidden surname-only shortening of a factual person statement.
"""

from __future__ import annotations

import re

_MARKER = re.compile(r"^\[[^\]]*\]$")
_PERSON_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_DEMO_RE = re.compile(r"\b(this|these|that|those)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_text(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _looks_factual_person_statement(question: str) -> bool:
    """A factual statement about a person usually wants the full name, not a
    bare surname. Jeopardy-style 'this ...' clues are handled separately."""
    q = _question_text(question)
    return bool(_PERSON_RE.search(q)) and not bool(_DEMO_RE.search(q))


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to their original context phrases."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _phrase_quality(phrase: str) -> tuple:
    """Prefer title case over ALL CAPS and preserve stylized punctuation."""
    stripped = _strip_surrounding(phrase)
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        len(stripped),
        stripped.count(" "),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    """Pick the dominant context surface form for a normalized key."""
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _clean_side_output(text: str) -> str:
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines:
        return ""
    out = lines[0].strip().strip("\"'`").strip()
    out = re.sub(r"^(?:answer\s*(?:is|:)?\s*)", "", out, flags=re.IGNORECASE).strip()
    return out


def _prompt(question: str, draft: str) -> str:
    return (
        "You are checking a short-answer QA draft. Use ONLY the supplied context below.\n\n"
        + question
        + "\n\nDraft answer:\n"
        + draft
        + "\n\n"
        "Determine the single correct short answer and return only that answer string, "
        "using the exact spelling, capitalization, hyphenation, number, and name extent "
        "from the context. If the draft is already the correct bare short answer, return "
        "it unchanged; otherwise return the corrected bare short answer.\n"
        "Rules:\n"
        "- For a Jeopardy-style 'this ...' clue, return the phrase that fills the blank, "
        "not a longer title or full name unless the clue itself requires the full name.\n"
        "- If the clue asks for a nickname, surname, acronym, term, place, or category, "
        "return only that form.\n"
        "- If the clue is a factual statement about a person, return the person's name "
        "exactly as the context introduces it.\n"
        "- Do not add articles unless the context phrase includes them.\n"
        "- Return only the answer string, with no explanation, quotes, or formatting."
    )


async def before_final(candidate, ctx):
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    # The deterministic cleaner already canonicalizes single-token drafts; a
    # side rewrite here would risk replacing a correct one-token answer with a
    # nearby distractor.
    if len(original.split()) < 2:
        return None

    state = ctx.state["verify_short_answer"]
    if state.get("fired", 0) >= 1:
        return None
    state["fired"] = 1

    phrases, _ = _context_phrases(ctx.question)
    if not phrases:
        return None

    try:
        extracted = await ctx.side_text(
            _prompt(ctx.question, original),
            purpose="verify_short_answer",
            max_tokens=64,
        )
    except Exception:
        ctx.trace.event("verify_short_answer_error", error="side_text_raised")
        return None
    if not extracted:
        return None

    side_key = _norm_text(_clean_side_output(extracted))
    original_key = _norm_text(original)
    if not side_key or side_key == original_key:
        return None
    if side_key not in phrases:
        ctx.trace.event(
            "verify_short_answer_rejected", reason="side_not_context_phrase"
        )
        return None

    ctx_text = _context_text(ctx.question)
    cleaned = _strip_surrounding(_best_phrase(phrases[side_key], ctx_text))
    cleaned_key = _norm_text(cleaned)
    if cleaned_key == original_key:
        return None

    # Do not shorten a factual person statement to a bare surname when the
    # draft already uses the person's full context name.
    if (
        _looks_factual_person_statement(ctx.question)
        and original_key in phrases
        and len(original.split()) >= 2
        and len(cleaned.split()) < 2
    ):
        ctx.trace.event(
            "verify_short_answer_rejected", reason="person_name_shortening_guard"
        )
        return None

    if len(cleaned.split()) > len(original.split()):
        ctx.trace.event(
            "verify_short_answer_rejected", reason="side_longer_than_draft"
        )
        return None

    ctx.trace.event(
        "verify_short_answer_replace",
        draft=original,
        replacement=cleaned,
        length_before=len(original.split()),
        length_after=len(cleaned.split()),
    )
    return {"action": "replace", "answer": cleaned}

texts.8ad3c115a2db1af1d80cd79916fe7c4dfe0cac2a:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").

The previous "overexpanded short form" trigger was removed: it repeatedly
asked the model to shorten an already-correct full name or title to a surname
or single word, causing exact-match regressions after a correct first answer.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_QUOTED_PHRASE_RE = re.compile(r'"([^"]+)"')


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _looks_clue_quote_echo(text: str, question: str) -> bool:
    """Return True when the candidate is the question's own quoted descriptor.

    For clues such as 'one of these "..."', a quoted phrase introduced by
    "these"/"those" is usually a descriptor for the requested category, not the
    requested short answer. This fires only when the candidate equals that
    quoted phrase and the quote is directly introduced by "these" or "those",
    which makes echo of the clue phrase a strong wrong-answer signal.
    """
    text = (text or "").strip()
    if not text or len(text.split()) > 6:
        return False
    qline = _question_line(question)
    cand_key = _norm_text(text)
    if not cand_key:
        return False

    for match in _QUOTED_PHRASE_RE.finditer(qline):
        quoted = match.group(1).strip()
        if not quoted or _norm_text(quoted) != cand_key:
            continue
        prefix = qline[: match.start()].rstrip()
        if re.search(r"\b(?:these|those)\s*$", prefix, re.IGNORECASE):
            return True
    return False


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not repeat the question's own quoted words "
        "unless the context shows those exact words are the answer. Do not "
        "include any lead-in, explanation, parenthetical, gloss, date, or "
        "extra punctuation. If the question is a definition or category clue "
        "(\"An X that does Y\", \"this type of ...\", \"the term for ...\"), "
        "return the general category or term whose function the context states, "
        "not a specific example that shares only one property. If your previous "
        "answer was the right entity but the wrong singular/plural or surface "
        "form, fix only that form and keep the entity."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


def _clue_quote_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer repeats the question's own quoted wording. "
        "That quoted phrase is a clue descriptor, not the requested short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question. For a clue such as 'one of these \"...\"' or "
        "'one of those \"...\"', the quoted phrase is usually a descriptor for "
        "the requested category or entity; return that category or entity using "
        "the exact term from the supplied context. If the quoted phrase is only "
        "the clue's descriptor, do not return it. Return only the correct exact phrase."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: candidate repeats the question's own quoted descriptor.
    if state.get("quote_echo_fired", 0) < 1 and _looks_clue_quote_echo(
        original, ctx.question
    ):
        state["quote_echo_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_quote_echo", candidate=original)
        return {"action": "continue", "feedback": _clue_quote_feedback(original)}

    # Trigger 2: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 3: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.9472d42b5de04ffd1813bb2a51356ce8936a532f:
"""Bounded primary-model self-correction for short-answer output format.

Runs after the deterministic cleaner and side verifier. When the remaining
candidate still looks like prose, or is a context phrase that is longer than the
short form requested by the clue, this hook asks the primary model for one more
bounded attempt. Clean short phrases are never re-rolled, and the runtime's
final-continue and remaining-turn budgets bound the retry.
"""

from __future__ import annotations

import re
from typing import Any

_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_ARTICLE_OPEN_RE = re.compile(r"^(?:a|an|the)\s+", re.I)
_MARKER = re.compile(r"^\[[^\]]*\]$")
_SHORT_FORM_MARKERS = (
    "term for",
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "pre-",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    sequences: list[list[str]] = []
    current: list[str] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append(norm)
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                keys.add("".join(seq[i : i + n]))
    return keys


def _looks_like_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 7:
        return True
    if len(words) >= 4 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    if (
        len(words) == 2
        and _ARTICLE_OPEN_RE.match(text)
        and _SENTENCE_END_RE.search(text)
    ):
        return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    q = _question_line(question).lower()
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False
    words = text.split()
    if len(words) < 3:
        return False
    ctx_keys = _context_phrase_keys(question)
    if _norm_text(text) not in ctx_keys:
        return False
    for n in range(len(words) - 1, 0, -1):
        prefix_key = _norm_text(" ".join(words[:n]))
        if prefix_key in ctx_keys:
            return True
    return False


def _looks_like_overanswer(text: str, question: str) -> bool:
    return _looks_like_prose(text) or _looks_overexpanded(text, question)


def _feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" Your previous "
        "answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "or trailing punctuation."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    if not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_retry"]
    if state.get("fired", 0) >= 1:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    original = (candidate or "").strip()
    if not _looks_like_overanswer(original, ctx.question):
        return None

    state["fired"] = 1
    return {"action": "continue", "feedback": _feedback(original)}

texts.966d80273105e60d034073b48f9f68b1b9c4c40e:
"""Deterministic final-answer cleaner for short-answer QA tasks.

Removes only generic wrapper text that breaks exact-match scoring:
discourse lead-ins, parentheticals, dash glosses, leading articles, and
trailing punctuation. When the candidate's normalized token sequence matches
a phrase in the supplied context, it prefers the context's exact surface
form. No task-specific answer strings or answer forms are encoded here.
"""

from __future__ import annotations

import re

_DISCOURSE_LEAD = {
    "true",
    "false",
    "yes",
    "no",
    "correct",
    "right",
    "answer",
    "note",
    "indeed",
}
_MARKER = re.compile(r"^\[[^\]]*\]$")
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"his|her|he|she|him)\b",
    re.IGNORECASE,
)
_OF_FROM_RE = re.compile(r"\b(of|from)\s+(.+)$", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to their original context phrases."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _phrase_quality(phrase: str) -> tuple:
    """Prefer title case over ALL CAPS and preserve stylized punctuation."""
    stripped = _strip_surrounding(phrase)
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        len(stripped),
        stripped.count(" "),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    """Pick the dominant context surface form for a normalized key."""
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _echo_context_form(text: str, question: str) -> str:
    """Prefer the supplied context's exact surface form for a matched phrase."""
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    key = _norm_text(text)
    if not key or key not in phrases:
        return text
    ctx = _context_text(question)
    best = _strip_surrounding(_best_phrase(phrases[key], ctx))
    # If the candidate already equals the dominant form after ignoring
    # surrounding punctuation, keep it (preserves stylized punctuation).
    if best.lower() == _strip_surrounding(text).lower():
        return text
    return best


def _strip_wrappers(text: str) -> str:
    return text.strip().strip("\"'`").strip()


_LEAD_IN = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)\s*",
    re.IGNORECASE,
)


def _strip_lead_in(text: str) -> str:
    return _LEAD_IN.sub("", text).strip()


def _strip_parentheticals(text: str) -> str:
    return re.sub(r"\s*\([^()]*\)", "", text).strip()


def _strip_dash_gloss(text: str) -> str:
    parts = re.split(r"\s+[\u2014\u2013]\s+", text)
    if len(parts) < 2:
        return text
    left = parts[0].strip().strip("\"'")
    if left.lower() in _DISCOURSE_LEAD:
        return parts[1].strip()
    return left


def _strip_leading_article(text: str) -> str:
    return re.sub(r"^(a|an|the)\s+(?=[a-z])", "", text, flags=re.IGNORECASE).strip()


def _strip_trailing_punct(text: str) -> str:
    while True:
        m = re.search(r"[.!?]+$", text)
        if not m:
            return text
        # Preserve abbreviations and initials such as "U.S." or "J. R.".
        if re.search(r"\b[A-Za-z]\.[A-Za-z]\.?$", text) or re.search(
            r"\b[A-Za-z]\.$", text
        ):
            return text
        run = m.group(0)
        # A single ! or ? is more likely part of a title than sentence
        # punctuation, so only strip repeated exclamation/question marks.
        if ("!" in run or "?" in run) and len(run) == 1:
            return text
        text = text[: m.start()].rstrip()
        if not text:
            return text


# ---------------------------------------------------------------------------
# Minimal-head extraction for bare role/title and pair/list clues
# ---------------------------------------------------------------------------


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _capitalized_words(text: str) -> list[str]:
    return [t for t in re.findall(r"[A-Za-z][A-Za-z'\-]*", text)]


def _is_role_title_clue(q: str) -> bool:
    """Bare role/title clue like 'President Tran Duc Luong'.

    These clues contain no demonstrative/question/definition words and consist
    of a short title followed by a proper name. The requested short answer is
    the associated place/state/organization, not the role description.
    """
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return bool(toks) and all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    """Bare pair/list clue like 'Edward Kennedy,John Kerry'.

    These clues list two or more proper names with no other predicates. The
    requested short answer is the shared label/location, not a sentence about
    their relationship.
    """
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _extract_minimal_head(text: str, question: str) -> str:
    """Extract the head place/label after 'of'/'from' in a verbose draft.

    Only used for bare role/title and pair/list clues. For example:
      'President of Vietnam from 1997 to 2006' -> 'Vietnam'
      '... Senators from Massachusetts and close political allies' -> 'Massachusetts'

    The head is only extracted when it is a single capitalized token; longer
    compounds are left for the side verifier to handle.
    """
    match = _OF_FROM_RE.search(text)
    if not match:
        return text
    tail = match.group(2).strip().strip(" .,;:!?\"'`")
    tail = re.sub(r"^(the|a|an)\s+", "", tail, flags=re.IGNORECASE)
    run: list[str] = []
    for tok in tail.split():
        if tok and tok[0].isupper() and not tok[0].isdigit():
            run.append(tok)
        else:
            break
    if len(run) != 1:
        return text
    candidate = run[0]
    return _echo_context_form(candidate, question)


def _clean(text: str, question: str) -> str:
    t = _strip_wrappers(text)
    t = _strip_lead_in(t)
    t = _strip_parentheticals(t)
    t = _strip_dash_gloss(t)
    t = _strip_leading_article(t)
    t = _strip_trailing_punct(t)
    t = _echo_context_form(t, question)
    t = _strip_leading_article(t)
    t = _strip_trailing_punct(t)
    t = " ".join(t.split())
    if _short_answer_requested(question):
        q = _question_line(question)
        if _is_role_title_clue(q) or _is_pair_list_clue(q):
            extracted = _extract_minimal_head(t, question)
            if _norm_text(extracted) != _norm_text(t):
                return extracted
    return t


async def before_final(candidate, ctx):
    """Clean the final short answer into its bare canonical form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        return {"action": "replace", "answer": cleaned}
    return None

texts.9c5e4a2a3df18131aec5d181af1e4e2bee259be1:
"""Bounded side-model verification gate for short-answer QA.

Runs after the deterministic cleaner and the primary-model retry hooks, so it
only inspects candidates those hooks already accepted. It asks a side model to
re-derive the answer and judge the draft. When the verdict is WRONG it returns
a bounded ``continue`` so the primary model gets one more attempt with the
reason.

The side model never authors the final answer: it only supplies a verdict and
a short reason. The primary model remains the sole author of the final message.

Bounds:
  * at most two side calls per task
  * at most one ``continue`` from this hook per task
  * candidates that the deterministic cleaner just produced are trusted and
    skipped (the cleaner only strips surface wrappers around a selected entity)
  * single-token candidates are skipped; the retry hook handles their
    inflection/plural mismatches
  * context-backed full-name answers to generic ``this ...`` / ``whose ...``
    person clues are skipped so the side model cannot over-shorten a correct
    full name to a surname
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose)\b", re.IGNORECASE)
_SHORT_NAME_MARKERS = ("surname", "nickname", "acronym", "short name", "initials")
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-.]*$")

_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "man", "woman", "person", "boy", "girl", "founder", "author", "writer",
    "novelist", "poet", "playwright", "actor", "actress", "singer",
    "bandleader", "composer", "artist", "painter", "director", "senator",
    "president", "mayor", "governor", "sultan", "king", "queen", "emperor",
    "explorer", "frontiersman", "circumnavigator", "pioneer", "leader",
    "chief", "thief", "boxer", "golfer", "inventor", "scientist", "engineer",
    "aviator", "pilot", "sailor", "politician", "diplomat", "general",
    "admiral", "captain", "colonel", "marshal", "knight", "criminal",
    "detective", "sleuth", "outlaw",
)
_BRAND_DEMO_RE = re.compile(
    r"\b(this|that|whose)\b[^\n]{0,60}?\b"
    r"(company|store|chain|brand|retailer|restaurant|network|association|"
    r"organization|organisation|alliance|agency|mint|radio|hardware|market|"
    r"shop|dealer|manufacturer)\b",
    re.IGNORECASE,
)
_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_PHRASE_RE = re.compile(r'"([^"]+)"')
_DEFINITION_START_RE = re.compile(r"^(?:an?|the)\s+[a-z]", re.IGNORECASE)
_DEFINITION_MARKER_RE = re.compile(
    r"\b(?:the term for|this type of|type of|the crime for which|it's the)\b",
    re.IGNORECASE,
)
_TYPE_OF_RE = re.compile(r"\btype of\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _is_person_or_brand_demo_clue(question: str) -> bool:
    """True only for demonstrative person/brand clues where a full proper name
    should be protected from surname-only or brand-shortening rewrites."""
    q = _question_line(question).lower()
    if not _PERSON_DEMO_RE.search(q):
        return False
    if _PERSON_PRONOUN_RE.search(q):
        return True
    if _BRAND_DEMO_RE.search(q):
        return True
    return any(
        re.search(r"\b" + re.escape(word) + r"\b", q)
        for word in _PERSON_ROLE_WORDS
    )


def _is_full_name_demo_clue(question: str, draft: str) -> bool:
    """True for a context-backed full-name answer to a generic this/whose
    person or brand clue. These are deliberately skipped so the side model
    cannot demand a surname-only or brand-shortening rewrite that would break
    exact match. Non-person 'these/those' and 'type of' phrases are NOT
    skipped, so the side gate can still reject wrong-entity echoes."""
    q = _question_line(question).lower()
    if not _is_person_or_brand_demo_clue(question):
        return False
    if any(marker in q for marker in _SHORT_NAME_MARKERS):
        return False
    words = draft.split()
    if not (2 <= len(words) <= 4):
        return False
    return all(_NAME_TOKEN_RE.match(word) for word in words)


def _is_definition_category_clue(q: str) -> bool:
    if not q:
        return False
    if _DEFINITION_MARKER_RE.search(q):
        return True
    return bool(_DEFINITION_START_RE.match(q))


def _question_shape_focus(question: str) -> str | None:
    """Append a compact checker standard for the failure-prone clue shapes."""
    q = _question_line(question)
    if not q:
        return None
    if _PERSON_PRONOUN_RE.search(q) and not _PERSON_DEMO_RE.search(q):
        return (
            "The question is a factual statement about a person (\"he/his/her\"). "
            "The draft is CORRECT only if it is the person who performed the action "
            "or is described by the predicate. Reject a draft that is a publication "
            "title, quoted phrase, object, or a different person who does not satisfy "
            "every predicate. Keep the person's full name exactly as the context "
            "introduces it."
        )
    if re.search(r"\bnamed for\b|\bnamed after\b", q, re.IGNORECASE):
        return (
            "The question asks for the person or entity that something is named "
            "for. The draft is CORRECT only if it is the person/entity the context "
            "says the thing is named for; reject a draft that names the thing itself "
            "or a related person that does not match the 'named for' statement."
        )
    if _ONE_OF_THESE_RE.search(q) and _QUOTED_PHRASE_RE.search(q):
        return (
            "The question is a 'one of these/those' clue whose quoted phrase is "
            "a clue, not the answer. The draft is CORRECT only if it names the "
            "category or entity the quoted phrase describes; reject a draft that "
            "merely echoes the quoted phrase."
        )
    if _TYPE_OF_RE.search(q):
        return (
            "The question asks for a specific type ('this type of X'). The draft "
            "is CORRECT only if it names the specific type the context states; "
            "reject the general X or a general descriptor such as 'modern X' or "
            "'regular X'."
        )
    if _is_definition_category_clue(q):
        return (
            "The question is a definition/category clue. The draft is CORRECT "
            "only if it names the general category or term whose function the "
            "context states; reject a draft that is only a salient example "
            "sharing one property."
        )
    if re.search(r"\b(these|those)\b", q):
        return (
            "The question is a 'these/those' category clue. The draft is CORRECT "
            "only if it is the shortest exact context phrase that satisfies the "
            "clue; reject a draft that repeats a qualifier already stated in the "
            "question when the context supports the shorter noun as the answer."
        )
    return None


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrase_keys(question: str) -> set[str]:
    """Return normalized n-gram keys for the supplied context (up to 6 tokens)."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _prompt(question: str, draft: str) -> str:
    focus = _question_shape_focus(question)
    prompt = (
        "You are checking a short-answer draft for an exact-match grader. "
        "Use ONLY the supplied context below.\n\n"
        "Step 1: Determine the single correct short answer.\n"
        "- Apply every clue and constraint in the question.\n"
        "- Choose the context passage that satisfies all of them.\n"
        "- For a definition/category clue (\"An X that does Y\", \"the term for ...\", "
        "\"this type of ...\"), return the general category or term whose function "
        "is stated, not a salient example sharing only one property.\n"
        "- For a person clue, verify every stated fact, number, date, or role is "
        "stated in the chosen person's passage. For a factual statement about a "
        "person (\"he/his/her ...\"), keep the person's full name as introduced "
        "in the context; do not shorten a full name to a surname or drop an "
        "honorific unless the question explicitly asks for a surname, nickname, "
        "or initials.\n"
        "- For a Jeopardy-style \"this ...\" or \"whose ...\" person clue, "
        "accept a context-supported full name unless the question explicitly asks "
        "for a surname, nickname, or initials.\n"
        "- Use the exact wording from the supplied context for the requested form "
        "(short name, surname, plural, hyphenation).\n"
    )
    if focus:
        prompt += focus + "\n"
    prompt += (
        "\nStep 2: Compare your answer to the draft below. Do not write out your answer.\n\n"
        + question
        + "\n\nDraft answer:\n"
        + draft
        + "\n\n"
        "End your reply with exactly one line, either:\n"
        "CORRECT\n"
        "or\n"
        "WRONG <brief reason the draft fails, without stating the correct answer>"
    )
    return prompt


def _parse_verdict(text: str) -> tuple[str | None, str]:
    """Return (verdict, reason) from the last recognizable verdict line."""
    verdict: str | None = None
    reason = ""
    lines = [line.strip() for line in (text or "").splitlines() if line.strip()]
    for i, line in enumerate(lines):
        match = re.match(r"^(CORRECT|WRONG)\b[:\-]?\s*(.*)$", line, re.IGNORECASE)
        if not match:
            continue
        verdict = match.group(1).lower()
        reason = match.group(2).strip()
        if not reason and verdict == "wrong" and i + 1 < len(lines):
            nxt = lines[i + 1]
            if not re.match(r"^(CORRECT|WRONG)\b", nxt, re.IGNORECASE):
                reason = nxt
    return verdict, reason


def _feedback(draft: str, reason: str) -> str:
    reason_text = f" It said: {reason}" if reason else ""
    return (
        "The instruction says: \"Return only the short answer.\" "
        "An independent check found that your previous answer may not satisfy "
        "every clue in the question or may not be the exact requested form."
        + reason_text
        + "\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "If your previous answer already satisfies every clue and is copied "
        "verbatim from the supplied context, return it unchanged. Otherwise list "
        "every explicit clue and constraint, find the single context phrase that "
        "satisfies all of them, and discard a specific example or partial match "
        "when the question asks for a general category or term. Return only the "
        "corrected short answer, copied verbatim from the supplied context."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Judge a settled short-answer candidate and, on a wrong verdict, ask the
    primary model for one more bounded attempt."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    words = original.split()
    if len(words) < 2:
        return None

    # The deterministic cleaner only removes wrappers around a selected entity.
    # Trusting its replacement avoids spending side calls on already-cleaned
    # surface form and keeps this gate focused on wrong-entity selection.
    clean_state = ctx.state.get("short_answer_clean") or {}
    if clean_state.get("replaced_this_turn"):
        return None

    context_keys = _context_phrase_keys(ctx.question)
    if _norm_text(original) not in context_keys:
        return None

    # Full-name answers to generic this/whose person clues are correct as-is;
    # do not spend a side call that could over-shorten them to a surname.
    if _is_full_name_demo_clue(ctx.question, original):
        return None

    state = ctx.state.setdefault("short_answer_verify", {})
    if state.get("continued", 0) >= 1:
        return None
    if state.get("side_calls", 0) >= 2:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    state["side_calls"] = state.get("side_calls", 0) + 1
    try:
        extracted = await ctx.side_text(
            _prompt(ctx.question, original),
            purpose="short_answer_verify",
            max_tokens=120,
        )
    except Exception as e:
        ctx.trace.event("short_answer_verify_error", error=str(e))
        return None

    if not extracted:
        return None

    verdict, reason = _parse_verdict(extracted)
    if verdict == "correct":
        ctx.trace.event("short_answer_verify_accept", draft=original)
        return None

    if verdict != "wrong":
        ctx.trace.event(
            "short_answer_verify_ignored",
            reason="unrecognized_verdict",
            side=extracted,
        )
        return None

    ctx.trace.event("short_answer_verify_wrong", draft=original, reason=reason)
    state["continued"] = 1
    return {"action": "continue", "feedback": _feedback(original, reason)}

texts.9f2ad7edeaaf0cd11b13fbbb820807e9299a268d:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate that is a verbatim context phrase but has a shorter context-phrase
   prefix/suffix while the question asks for a short form, or is a two/three-
   token full name for a "this ..."/"whose ..." clue whose surname alone is
   also a context phrase.
4. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

# Strong cues that the requested form is shorter than the full context phrase.
_SHORT_FORM_MARKERS = (
    "known as",
    "nickname",
    "nicknamed",
    "called",
    "referred to as",
    "term for",
    "type of",
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
    "alliance",
    "surname",
    "acronym",
    "short name",
    "initials",
)

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    q = _question_line(question).lower()
    words = text.split()
    if len(words) < 2:
        return False

    keys = _context_phrase_keys(question)
    key = _norm_text(text)
    if key not in keys:
        return False

    # A two/three-token full name for a "this ..."/"whose ..." clue whose
    # surname alone is also a context phrase is likely over-expanded.
    if len(words) in (2, 3):
        if all(_NAME_TOKEN_RE.match(word) for word in words):
            if ("this" in q or "whose" in q) and _norm_text(words[-1]) in keys:
                return True

    # Otherwise only short-form cues justify asking for a shorter phrase.
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False

    for n in range(1, len(words)):
        if _norm_text(" ".join(words[:n])) in keys:
            return True
    last = _norm_text(words[-1])
    if last in keys and last != key:
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not include any lead-in, explanation, "
        "parenthetical, gloss, date, or extra punctuation."
    )


def _short_form_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer appears to be longer than the requested short "
        "form, or uses a fuller name than the clue asks for.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question. Determine the shortest exact phrase from the "
        "supplied context that still satisfies every clue (for example a "
        "nickname, term, acronym, surname, or short company/network/mint/"
        "association name). If the shorter phrase no longer satisfies every "
        "clue, keep the full phrase. Return only the correct exact phrase."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 3: candidate is a context phrase but longer than the requested
    # short form. The primary model decides whether a shorter phrase is valid.
    if state.get("overexpanded_fired", 0) < 1 and _looks_overexpanded(
        original, ctx.question
    ):
        state["overexpanded_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_overexpanded", candidate=original)
        return {"action": "continue", "feedback": _short_form_feedback(original)}

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.a3c2665145e3ec2f4f51487b6cd2533e2358480c:
"""Deterministic surface-only final-answer cleaner for short-answer QA.

This hook runs only when the user request contains the explicit short-answer
instruction (``return only the short answer``). It never calls a model and
never changes which entity or term the model selected: it removes generic
surface wrappers around an answer candidate and re-echoes the supplied
context's dominant surface form for the same normalized token sequence.

Removals are deliberately generic and reversible:

  * surrounding code fences / matched quotes
  * ``Answer is:`` / ``The answer is`` lead-ins
  * discourse lead-ins such as ``True -- ...``
  * a trailing sentence period (abbreviations and initialisms are preserved)
  * trailing parenthetical/bracket glosses
  * trailing em/en-dash glosses whose head is supported by the context
  * decorative trailing ``!``/``?`` marks when the base is context-supported
  * a leading article when the article-less form is context-supported
  * canonical surface echo: case, spacing, and hyphenation are copied from the
    most frequent supplied-context variant of the same normalized phrase

After the surface cleanup above, a conservative minimal-form pass trims only
the shortest context-supported form for question types that conventionally ask
for it (nickname/short name, Jeopardy-style person surname, produce plural,
definition term head, and bare role/pair clues). Every replacement in that
pass is a verbatim n-gram from the supplied context, so it never invents an
answer and never substitutes a different entity.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_CODE_FENCE_RE = re.compile(r"^```[A-Za-z]*\s*\n(.*?)\n?```$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:-]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAIL_PAREN_RE = re.compile(r"\s*\([^()]{1,160}\)\s*$")
_TRAIL_BRACKET_RE = re.compile(r"\s*\[[^\[\]]{1,160}\]\s*$")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_TRAIL_PERIOD_RE = re.compile(r"\.$")
_TRAIL_BANG_RE = re.compile(r"[!?]+$")
_ARTICLE_RE = re.compile(r"^(a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)

_ABBREV_RE = re.compile(
    r"(?:\b[A-Za-z]\.){2,}$|\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", re.IGNORECASE
)

# ---------------------------------------------------------------------------
# Minimal-form extraction constants
# ---------------------------------------------------------------------------

_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "referred to as",
    "called it",
    "term for",
    "surname",
    "acronym",
    "pre-",
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
    "league",
)
_CATEGORY_SUFFIXES = {
    "party",
    "company",
    "network",
    "radio",
    "mint",
    "association",
    "organization",
    "organisation",
    "league",
    "corporation",
    "corp",
    "inc",
    "ltd",
    "system",
    "satellite",
}
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "singer",
    "director",
    "composer",
)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")
_ROLE_TITLE_WORDS = (
    "president",
    "sultan",
    "king",
    "queen",
    "emperor",
    "mayor",
    "governor",
    "senator",
    "chancellor",
    "secretary",
)
_OF_FROM_BLOCKLIST = {
    "state",
    "office",
    "department",
    "ministry",
    "government",
    "republic",
    "kingdom",
    "party",
    "house",
    "senate",
    "congress",
    "parliament",
}
_QUESTION_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"he|she|his|her|him)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    """Casefold and collapse every non-alphanumeric run to a single space."""
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _strip_surrounding(text: str) -> str:
    return (text or "").strip(" \t\r\n.,;:!?\"'`")


def _surface_map(question: str) -> dict[str, list[tuple[str, int]]]:
    """Map normalized n-gram keys to (surface, count) variants from context."""
    ctx = _context_text(question)
    surfaces: dict[str, list[tuple[str, int]]] = {}
    if not ctx:
        return surfaces

    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(6, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                phrase = " ".join(tokens[i : i + n])
                key = _chunk_key(phrase)
                if not key:
                    continue
                bucket = surfaces.setdefault(key, [])
                if all(surface != phrase for surface, _ in bucket):
                    bucket.append((phrase, 0))

    ctx_lower = ctx.lower()
    for key, bucket in surfaces.items():
        for idx, (surface, _) in enumerate(bucket):
            bucket[idx] = (surface, ctx_lower.count(surface.lower()))
    return surfaces


def _surface_quality(item: tuple[str, int], candidate: str) -> tuple:
    surface, count = item
    stripped = _strip_surrounding(surface)
    return (
        count,
        1 if surface.casefold() == candidate.casefold() else 0,
        1 if stripped[:1].isupper() else 0,
        1 if not stripped.isupper() else 0,
        -stripped.count("-"),
        -len(stripped),
    )


def _best_surface(bucket: list[tuple[str, int]], candidate: str) -> str:
    if not bucket:
        return candidate
    best = max(bucket, key=lambda item: _surface_quality(item, candidate))
    return _strip_surrounding(best[0])


def _has_key(text: str, surfaces: dict) -> bool:
    key = _chunk_key(text)
    return bool(key) and key in surfaces


def _strip_code_fence(text: str) -> str:
    match = _CODE_FENCE_RE.match(text.strip())
    if match:
        return match.group(1).strip()
    return text


def _strip_surrounding_quotes(text: str) -> str:
    t = text.strip()
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                return inner
    return t


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_RE.match(text.strip())
    if match and match.group("tail").strip():
        return match.group("tail").strip()
    return text


def _strip_answer_lead(text: str) -> str:
    return _LEAD_IN_RE.sub("", text.strip()).strip()


def _strip_trailing_parentheticals(text: str) -> str:
    cur = text.strip()
    for _ in range(8):
        prev = cur
        for pattern in (_TRAIL_PAREN_RE, _TRAIL_BRACKET_RE):
            match = pattern.search(cur)
            if match:
                nxt = cur[: match.start()].strip()
                if nxt and nxt != cur:
                    cur = nxt
                    break
        if cur == prev:
            break
    return cur


def _strip_trailing_dash_gloss(text: str, surfaces: dict) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _has_key(before, surfaces):
        return before
    return text


def _strip_trailing_period(text: str, surfaces: dict) -> str:
    cur = text.strip()
    for _ in range(4):
        if not cur.endswith(".") or cur.endswith(".."):
            break
        if _ABBREV_RE.search(cur):
            break
        nxt = cur[:-1].rstrip()
        if not nxt:
            break
        if cur[-2].islower() or cur[-2] in ")]}\"'" or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_trailing_bang(text: str, surfaces: dict) -> str:
    """Strip decorative trailing !/? when the base is context-supported or the
    mark is doubled. Repeated marks are surface decoration, not an entity."""
    cur = text.strip()
    for _ in range(4):
        match = _TRAIL_BANG_RE.search(cur)
        if not match:
            break
        run = match.group(0)
        nxt = cur[: match.start()].rstrip()
        if not nxt:
            break
        if len(run) >= 2 or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_leading_article(text: str, surfaces: dict) -> str:
    match = _ARTICLE_RE.match(text.strip())
    if not match:
        return text.strip()
    rest = match.group("rest").strip()
    if not rest:
        return text.strip()
    if _has_key(rest, surfaces) or rest[0].isupper() or rest[0].isdigit():
        return rest
    return text.strip()


def _echo_context_form(text: str, surfaces: dict, original: str) -> str:
    key = _chunk_key(text)
    if not key or key not in surfaces:
        return text
    return _best_surface(surfaces[key], original)


# ---------------------------------------------------------------------------
# Minimal-form extraction
# ---------------------------------------------------------------------------


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _word_in_question(word: str, question_line: str) -> bool:
    w = re.sub(r"[^A-Za-z0-9]", "", word.casefold())
    if not w:
        return False
    return w in set(re.findall(r"[A-Za-z0-9]+", question_line.casefold()))


def _has_short_form_cue(question_line: str) -> bool:
    q = question_line.lower()
    if any(marker in q for marker in _SHORT_FORM_MARKERS):
        return True
    return bool(
        re.search(
            r"\bthis\s+(?:\w+\s+)?(?:company|network|mint|radio|association|"
            r"organization|organisation|league)\b",
            q,
        )
    )


def _drop_trailing_descriptors(text: str, question_line: str, surfaces: dict) -> str:
    """Drop trailing category words or question descriptors when a shorter
    context-supported prefix remains. Used for nickname/short-name clues
    where a trailing category noun should be removed."""
    if not _has_short_form_cue(question_line):
        return text
    if re.search(r"[()\[\]]", text):
        return text
    words = text.split()
    if len(words) < 2:
        return text

    cur = text
    for end in range(len(words) - 1, 0, -1):
        prefix = " ".join(words[:end])
        dropped = words[end]
        drop_word = re.sub(r"[^A-Za-z0-9]", "", dropped.casefold())
        if drop_word in _CATEGORY_SUFFIXES or _word_in_question(dropped, question_line):
            if _has_key(prefix, surfaces):
                cur = prefix
                continue
            break
        break
    return cur


def _person_surname(text: str, question_line: str, surfaces: dict) -> str:
    """For Jeopardy-style ``this ...`` / ``whose ...`` person clues, keep only
    the surname/target name when the supplied context also provides that
    surname alone. Factual ``he/she/his/her`` statements are excluded because
    those usually want the person's name exactly as the context introduces it."""
    q = question_line.lower()
    if _PERSON_PRONOUN_RE.search(q):
        return text
    if not _PERSON_DEMO_RE.search(q):
        return text
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return text

    words = text.split()
    if len(words) not in (2, 3, 4):
        return text
    if not all(_NAME_TOKEN_RE.match(word) for word in words):
        return text

    surname = words[-1]
    if _has_key(surname, surfaces):
        return _best_surface(surfaces[_chunk_key(surname)], surname)
    return text


def _plural_candidates(word: str) -> list[str]:
    base = word.strip()
    if not base:
        return []
    candidates: list[str] = []
    if re.search(r"[^aeiou]y$", base, re.IGNORECASE):
        candidates.append(base[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", base, re.IGNORECASE):
        candidates.append(base + "es")
    candidates.append(base + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question_line: str, surfaces: dict) -> str:
    """Restore the context's plural produce form for ``this fruit/vegetable/
    berry/plant`` clues."""
    if len(text.split()) != 1:
        return text
    if not _PRODUCE_RE.search(question_line):
        return text

    word = text.strip()
    for candidate in _plural_candidates(word):
        if _has_key(candidate, surfaces):
            return _best_surface(surfaces[_chunk_key(candidate)], candidate)
    return text


def _is_pair_list_clue(question_line: str) -> bool:
    """Bare pair/list clues such as ``A,B`` or ``A,B,C`` with no other
    predicate."""
    if "," not in question_line:
        return False
    if _QUESTION_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 6):
        return False
    for part in parts:
        tokens = [t for t in re.findall(r'"[^"]+"|[A-Za-z][A-Za-z\'\-]*', part) if t]
        if not tokens:
            return False
        if not all(t[:1].isupper() or t.startswith('"') for t in tokens):
            return False
    return True


def _is_role_title_clue(question_line: str) -> bool:
    """Bare role/title clues such as ``President X`` or ``Sultan X``. The
    requested short answer is the associated place/office label, not a
    sentence about the role."""
    if "," in question_line:
        return False
    if _QUESTION_DEMO_RE.search(question_line):
        return False
    q = question_line.lower()
    if not any(word in q for word in _ROLE_TITLE_WORDS):
        return False
    return len(question_line.split()) <= 8


def _extract_of_from_head(text: str, surfaces: dict) -> str:
    """Extract a capitalized place/office head after ``of``/``from`` in a
    verbose draft, but only when that head is supplied verbatim by the
    context and is not a generic title/office word."""
    match = re.search(
        r"\b(?:of|from)\s+([A-Z][A-Za-z]+(?:[ \t]+[A-Z][A-Za-z]+){0,2})",
        text,
    )
    if not match:
        return text
    candidate = _strip_surrounding(match.group(1))
    if not candidate:
        return text
    if candidate.casefold() in _OF_FROM_BLOCKLIST:
        return text
    if _has_key(candidate, surfaces):
        return _best_surface(surfaces[_chunk_key(candidate)], candidate)
    return text


def _definition_term_head(text: str, question_line: str, surfaces: dict) -> str:
    """For ``term for`` clues, keep the head term before ``of X`` when the
    head is context-supported and the tail is either a proper noun or is
    already named in the question."""
    if "term for" not in question_line.lower():
        return text
    match = re.match(r"^(.+?)\s+of\s+(.+)$", text)
    if not match:
        return text
    head = match.group(1).strip()
    tail = match.group(2).strip()
    if not _has_key(head, surfaces):
        return text

    tail_words = re.findall(r"[A-Za-z0-9]+", tail)
    tail_in_question = bool(tail_words) and all(
        _word_in_question(word, question_line) for word in tail_words
    )
    if tail_in_question or (tail[:1].isupper() if tail else False):
        return _best_surface(surfaces[_chunk_key(head)], head)
    return text


def _minimal_form(text: str, question: str, surfaces: dict) -> str:
    """Return the shortest context-supported form for question types that
    conventionally ask for one. Each rewrite is a verbatim context n-gram."""
    question_line = _question_line(question)
    cur = text

    cur = _drop_trailing_descriptors(cur, question_line, surfaces)
    cur = _person_surname(cur, question_line, surfaces)
    cur = _prefer_plural_produce_form(cur, question_line, surfaces)
    cur = _definition_term_head(cur, question_line, surfaces)

    if _is_pair_list_clue(question_line) or _is_role_title_clue(question_line):
        cur = _extract_of_from_head(cur, surfaces)

    return cur


def _clean(original: str, question: str) -> str:
    surfaces = _surface_map(question)

    text = original.strip()
    text = _strip_code_fence(text)
    text = _strip_surrounding_quotes(text)
    text = _strip_discourse_lead(text)
    text = _strip_answer_lead(text)
    text = _strip_trailing_dash_gloss(text, surfaces)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_parentheticals(text)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_bang(text, surfaces)
    text = _strip_leading_article(text, surfaces)

    # Canonicalize spacing/case/hyphenation from the supplied context.
    text = _echo_context_form(text, surfaces, original)

    # Echo may re-introduce decorative title punctuation; strip it one final
    # time without re-echoing so we do not undo the punctuation cleanup.
    text = _strip_trailing_bang(text, surfaces)

    # Now that the candidate is wrapper-free, select the minimal context form
    # only for question types that ask for a short/nickname/surname/term.
    text = _minimal_form(text, question, surfaces)
    text = _strip_trailing_bang(text, surfaces)

    return " ".join(text.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.a7169af49d66293aab37470666a4774c5e674325:
"""Bounded primary-model self-correction for short-answer candidates.

Runs after the deterministic surface cleaner. It asks the *primary* model for
one more bounded attempt when the cleaned candidate is still very unlikely to
be an exact-match short answer:

  * the candidate is not a verbatim phrase from the supplied context, or
  * the candidate carries decorative trailing ``!``/``?`` punctuation.

It is deliberately conservative:

  * only tasks with an explicit ``return only the short answer`` instruction;
  * at most two continuations per task, with the runtime's remaining-turn and
    final-continue budgets respected;
  * clean, verbatim, punctuation-free context phrases are never re-rolled.

The primary model remains the only author of the final answer.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _context_phrase_keys(question: str) -> set[str]:
    """Return chunk keys for every context n-gram up to five tokens."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(5, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                keys.add(_chunk_key(" ".join(tokens[i : i + n])))
    return keys


def _has_decorative_punctuation(text: str) -> bool:
    return bool(re.search(r"[!?]\s*$", (text or "").strip()))


def _generic_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer is not the bare, exact phrase from the supplied "
        "context that answers the question.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not include any lead-in, explanation, "
        "parenthetical, gloss, date, or extra punctuation."
    )


def _punctuation_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer has decorative trailing punctuation.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context. If the trailing '!' or '?' is part of "
        "the actual title or name, keep it; otherwise return the plain form "
        "exactly as the supplied context gives it, with no decorative "
        "punctuation and no extra words."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["short_answer_retry"]
    fired = state.get("fired", 0)
    if fired >= 2:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    context_keys = _context_phrase_keys(ctx.question)
    key = _chunk_key(original)

    if key not in context_keys:
        state["fired"] = fired + 1
        state["non_context_fired"] = state.get("non_context_fired", 0) + 1
        return {"action": "continue", "feedback": _generic_feedback(original)}

    if _has_decorative_punctuation(original):
        state["fired"] = fired + 1
        state["punctuation_fired"] = state.get("punctuation_fired", 0) + 1
        return {"action": "continue", "feedback": _punctuation_feedback(original)}

    return None

texts.aaca8192309d94550241d4449b71230f6e870095:
"""Conservative deterministic short-answer surface cleaner.

Runs only when the task explicitly says to return only the short answer.
It performs lexical-only, context-gated normalization:

  * strip code fences and one matched pair of surrounding quotes
  * strip "answer is / answer:" lead-ins
  * strip True/False/Yes/No discourse lead-ins ("True — ...")
  * strip a trailing sentence period or repeated !/? only when the remaining
    phrase is supported verbatim by the supplied context
  * strip trailing parenthetical/bracket glosses only when the remaining
    phrase is a verbatim context phrase
  * strip trailing em/en-dash glosses only when the remaining phrase is a
    verbatim context phrase

For three recurring generic clue shapes it also reduces a verbose draft to
the requested head phrase, but only when the extracted phrase is itself a
verbatim context phrase:

  * factual-person statements ("he/his/her ...") -> leading name run
  * bare role/title clues ("President X", "Sultan Y") -> associated place
  * bare pair/list clues ("A,B") -> shared label after of/from/in

It never calls a model, never changes the selected entity, and deliberately
does NOT strip leading articles, shorten an organization/term to its first
word, or rewrite surface punctuation (case/hyphenation). Those decisions are
left to the bounded primary-model retry hook.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_ANSWER_LEAD_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s+(?P<gloss>.+)$", re.DOTALL)
_TRAILING_GLOSS_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]{0,120}[\)\]]\s*[.!?]*$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.([A-Za-z]\.)?$")
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

_DEF_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how)\b",
    re.IGNORECASE,
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|his|him|she|her|hers)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|whose)\b", re.IGNORECASE)
_OF_THESE_RE = re.compile(r"\bof\s+(?:these|those)\b", re.IGNORECASE)
_TRAILING_CATEGORY_WORDS = {
    "radio", "network", "company", "association", "organization", "organisation",
    "mint", "league", "party", "corporation", "corp", "inc", "ltd", "system",
    "satellite", "business", "businesses", "industry", "group", "station",
    "channel", "store", "chain", "brand", "retailer", "restaurant", "agency",
    "market", "shop", "dealer", "manufacturer", "alliance", "federation",
}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_keys(question: str) -> set[str]:
    """Return normalized n-gram keys for the supplied context (up to 6 tokens)."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _strip_code_fences_and_quotes(text: str) -> str:
    t = (text or "").strip()
    if t.startswith("```") and t.endswith("```") and len(t) > 6:
        inner = t[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            t = inner
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                t = inner
                break
    return t.strip()


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail:
            return tail
    return text


def _strip_answer_lead(text: str) -> str:
    return _ANSWER_LEAD_RE.sub("", text).strip()


def _strip_trailing_punct(text: str, keys: set[str]) -> str:
    t = text
    while True:
        if t.endswith(".") and not t.endswith("..") and len(t) > 2:
            if _ABBREV_RE.search(t):
                return t
            if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", t, re.IGNORECASE):
                return t
            nxt = t[:-1].rstrip()
            if _norm_text(nxt) in keys:
                t = nxt
                continue
            return t

        match = re.search(r"[!?]+$", t)
        if not match:
            return t
        run = match.group(0)
        nxt = t[: match.start()].rstrip()
        if not nxt:
            return t
        if len(run) >= 2 or _norm_text(nxt) in keys:
            t = nxt
            continue
        return t


def _strip_trailing_parenthetical(text: str, keys: set[str]) -> str:
    match = _TRAILING_GLOSS_RE.search(text)
    if not match:
        return text
    nxt = text[: match.start()].strip()
    if nxt and _norm_text(nxt) in keys:
        return nxt
    return text


def _strip_trailing_dash_gloss(text: str, keys: set[str]) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _norm_text(before) in keys:
        return before
    return text


def _looks_factual_person_statement(question_line: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(question_line)) and not bool(
        _PERSON_DEMO_RE.search(question_line)
    )


def _extract_person_name_run(text: str, keys: set[str]) -> str | None:
    words = text.split()
    if len(words) < 2:
        return None
    run: list[str] = []
    for word in words:
        cleaned = word.strip(".,;:!?\"'`")
        if cleaned and _NAME_TOKEN_RE.match(cleaned):
            run.append(cleaned)
            if len(run) == 3:
                break
        else:
            break
    for length in range(len(run), 1, -1):
        candidate = " ".join(run[:length])
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _looks_role_title_clue(question_line: str) -> bool:
    if not question_line or "," in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    words = question_line.split()
    if not (2 <= len(words) <= 6):
        return False
    return all(word[:1].isupper() for word in words if word)


def _extract_role_title_place(text: str, keys: set[str]) -> str | None:
    matches = re.findall(r"\bof\s+([A-Z][A-Za-z]+)", text)
    for candidate in reversed(matches):
        if _norm_text(candidate) in keys:
            return candidate
    match = re.search(r"\bfrom\s+([A-Z][A-Za-z]+)", text)
    if match and _norm_text(match.group(1)) in keys:
        return match.group(1)
    return None


def _looks_pair_list_clue(question_line: str) -> bool:
    if not question_line or "," not in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        words = part.split()
        if not (1 <= len(words) <= 5):
            return False
        if not all(word[:1].isupper() for word in words if word):
            return False
    return True


def _extract_pair_list_label(text: str, keys: set[str]) -> str | None:
    match = re.search(r"\b(?:from|of|in)\s+([A-Z][A-Za-z]+)(?=\s+(?:and|,)|$)", text)
    if match:
        candidate = match.group(1)
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _question_token_set(question_line: str) -> set[str]:
    """Return normalized single-word tokens present in the question line."""
    return {_norm_token(token) for token in question_line.split() if _norm_token(token)}


def _allow_trailing_drop(dropped: list[str], question_line: str) -> bool:
    """Return True when a trailing drop is safe for this clue.

    A trailing word may be dropped when it is a common category/descriptor suffix
    (``Network``, ``Radio``, ``Company``, ...) or when the question line itself
    ends with that same word after a demonstrative clue (``this possible
    Romanov``), which signals the word is a clue qualifier rather than the head
    of the requested answer.
    """
    if not dropped:
        return False
    last = _norm_token(dropped[-1])
    if not last:
        return False
    if last in _TRAILING_CATEGORY_WORDS:
        return True
    q_stripped = question_line.strip().casefold()
    if not q_stripped:
        return False
    if q_stripped.endswith(dropped[-1].strip().casefold().rstrip(".,;:!?\"'`")):
        return bool(re.search(r"\b(this|that|these|those)\b", question_line, re.IGNORECASE))
    return False


def _drop_question_stated_qualifiers(text: str, question_line: str, keys: set[str]) -> str:
    """Drop leading/trailing words that the question itself already states.

    Exact-match grading often wants the shortest context phrase that names the
    requested entity, with any qualifier or category word already present in the
    clue removed (for example ``Chinese laundries`` -> ``laundries`` when the
    clue says ``these Chinese businesses``, or ``Anastasia Romanov`` ->
    ``Anastasia`` when the clue says ``this possible Romanov``). This pass is
    deterministic and deliberately narrow:

      * the candidate must be a multi-word context phrase;
      * at least one candidate word must NOT already be in the question, so a
        phrase that merely echoes the clue is never reduced;
      * every dropped word must be a token already present in the question;
      * the shorter phrase must itself be a verbatim context n-gram;
      * leading drops are allowed only for ``of these/those`` clues, which
        protects full proper-name prefixes such as ``New York Times``.
    """
    words = text.split()
    if len(words) < 2:
        return text

    q_tokens = _question_token_set(question_line)
    if not q_tokens:
        return text

    text_norm = _norm_text(text)
    if not text_norm:
        return text
    if text_norm in _norm_text(question_line):
        return text
    if not any(_norm_token(word) and _norm_token(word) not in q_tokens for word in words):
        return text

    candidates: list[str] = []

    # Trailing qualifiers/category words already present in the clue.
    for n in range(1, len(words)):
        dropped = words[-n:]
        if not all(_norm_token(word) and _norm_token(word) in q_tokens for word in dropped):
            continue
        if not _allow_trailing_drop(dropped, question_line):
            continue
        shorter = " ".join(words[:-n]).strip()
        if shorter and _norm_text(shorter) in keys:
            candidates.append(shorter)

    # Leading qualifiers already present in the clue. Only ``of these/those``
    # clues are strong enough signals that the head noun is the target; this
    # avoids cutting a full proper-name prefix such as ``New York Times``.
    if _OF_THESE_RE.search(question_line):
        for n in range(1, len(words)):
            dropped = words[:n]
            if not all(_norm_token(word) and _norm_token(word) in q_tokens for word in dropped):
                continue
            shorter = " ".join(words[n:]).strip()
            if shorter and _norm_text(shorter) in keys:
                candidates.append(shorter)

    if not candidates:
        return text

    unique = list(dict.fromkeys(candidates))
    best = min(unique, key=lambda s: (len(s.split()), s.casefold()))
    return best if _norm_text(best) != text_norm else text


def _clean(text: str, question: str) -> str:
    t = " ".join((text or "").split())
    if not t:
        return t

    keys = _context_keys(question)

    t = _strip_code_fences_and_quotes(t)
    t = _strip_discourse_lead(t)
    t = _strip_answer_lead(t)

    q = _question_line(question)

    # Iteratively remove one trailing surface wrapper at a time. Every removal
    # is gated on the remaining phrase being a verbatim context n-gram, so the
    # pass never changes the selected entity.
    for _ in range(10):
        prev = t
        t = _strip_trailing_punct(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_parenthetical(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_dash_gloss(t, keys)
        if t != prev:
            continue
        break

    if _looks_factual_person_statement(q) and len(t.split()) > 3:
        extracted = _extract_person_name_run(t, keys)
        if extracted:
            t = extracted
    elif _looks_role_title_clue(q):
        extracted = _extract_role_title_place(t, keys)
        if extracted:
            t = extracted
    elif _looks_pair_list_clue(q):
        extracted = _extract_pair_list_label(t, keys)
        if extracted:
            t = extracted

    t = _drop_question_stated_qualifiers(t, q, keys)

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean a final short answer into its bare requested surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_clean", {})
    state["replaced_this_turn"] = False

    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        state["replaced_this_turn"] = True
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.af6c04a6e5f90126399bae0e25a4ba95303f2943:
"""Deterministic short-answer surface cleaner.

This hook runs only when the user explicitly requested a bare short answer
(``return only the short answer``). It removes generic surface wrappers that
break exact-match scoring and, for a few clue shapes, extracts the requested
minimal form. It never calls a model and never changes the chosen entity.

Covered operations (all reversible, lexical only):
  * code fences and matched surrounding quotes
  * "answer is / answer:" lead-ins
  * trailing parenthetical/bracket glosses and short dash glosses
  * a trailing lowercase sentence period
  * bare role/title and pair/list head extraction ("... of/from X")
  * produce/plant plural restoration ("Strawberry" -> "strawberries")
  * hyphenated acronym expansion ("Picture-in-picture" -> "Picture in Picture")
  * repeated title punctuation on pair/list clues ("What's Happening!!")
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_TRAILING_PAREN_RE = re.compile(r"\s*\([^()]*\)\s*$")
_TRAILING_BRACKET_RE = re.compile(r"\s*\[[^\[\]]*\]\s*$")
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–-]\s+(?P<gloss>.+)$", re.DOTALL)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"his|her|he|she|him|whose)\b",
    re.IGNORECASE,
)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in (text or "").split() if _norm_token(t))


def _segments(ctx: str) -> list[str]:
    return [p.strip() for p in _MARKER_RE.split(ctx) if p.strip()]


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to original context surface forms."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    for seg in _segments(ctx):
        toks: list[tuple[str, str]] = []
        for raw in seg.split():
            norm = _norm_token(raw)
            if norm:
                toks.append((norm, raw))
        max_n = min(5, len(toks))
        for n in range(1, max_n + 1):
            for i in range(len(toks) - n + 1):
                key = "".join(t[0] for t in toks[i : i + n])
                phrase = " ".join(t[1] for t in toks[i : i + n])
                counts[phrase] = counts.get(phrase, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _best_phrase(bucket: list[str], counts: dict[str, int]) -> str:
    """Pick the dominant context surface form for a normalized key."""
    if not bucket:
        return ""
    return max(
        bucket,
        key=lambda p: (
            counts.get(p, 0),
            1 if p.strip().count(" ") > 0 else 0,
            -p.count("-"),
            len(p),
        ),
    )


def _strip_code_fences(text: str) -> str:
    text = (text or "").strip()
    if text.startswith("```") and text.endswith("```") and len(text) > 6:
        inner = text[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            text = inner
    return text.strip()


def _strip_outer_quotes(text: str) -> str:
    text = (text or "").strip()
    for quote in ('"', "'", "`"):
        if (
            len(text) >= 2
            and text.startswith(quote)
            and text.endswith(quote)
        ):
            inner = text[1:-1].strip()
            if inner:
                text = inner
                break
    return text.strip()


def _strip_lead_in(text: str) -> str:
    return _LEAD_IN_RE.sub("", (text or "").strip()).strip()


def _strip_trailing_glosses(text: str, phrases: dict[str, list[str]]) -> str:
    cur = (text or "").strip()
    for _ in range(5):
        prev = cur
        nxt = _TRAILING_PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            if _norm_text(nxt) in phrases:
                cur = nxt
                continue
        nxt = _TRAILING_BRACKET_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            if _norm_text(nxt) in phrases:
                cur = nxt
                continue
        match = _DASH_GLOSS_RE.search(cur)
        if match:
            before = cur[: match.start()].strip()
            gloss = match.group("gloss").strip()
            if (
                before
                and gloss
                and len(gloss.split()) <= 8
                and _norm_text(before) in phrases
            ):
                cur = before
                continue
        break
    return cur


def _strip_trailing_period(text: str, phrases: dict[str, list[str]]) -> str:
    cur = (text or "").strip()
    if (
        cur.endswith(".")
        and not cur.endswith("..")
        and len(cur) > 2
        and cur[-2].islower()
    ):
        nxt = cur[:-1].rstrip()
        if nxt and _norm_text(nxt) in phrases:
            return nxt
    return cur


def _capitalized_words(text: str) -> list[str]:
    return re.findall(r"[A-Za-z][A-Za-z'\-]*", text or "")


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _echo_context_form(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str:
    key = _norm_text(text)
    if key and key in phrases:
        return _best_phrase(phrases[key], counts)
    return text


def _extract_head(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    """Extract a single proper-noun head after ``of``/``from`` for bare
    role/title and pair/list clues. Longer proper-name runs are left intact."""
    q = _question_line(question)
    if not (_is_role_title_clue(q) or _is_pair_list_clue(q)):
        return text
    match = re.search(
        r"\b(?:of|from)\s+(?:(?:the|a|an)\s+)?([A-Z][A-Za-z'.\-]*)", text
    )
    if not match:
        return text
    head = match.group(1)
    rest = text[match.end() :].strip()
    next_token = rest.split()[0] if rest else ""
    if next_token and next_token[0].isupper():
        return text
    return _echo_context_form(head, phrases, counts)


def _plural_forms(word: str) -> list[str]:
    if not word:
        return []
    forms: list[str] = []
    if (
        len(word) > 1
        and word[-1].lower() == "y"
        and word[-2].lower() not in "aeiou"
    ):
        forms.append(word[:-1] + "ies")
    forms.append(word + "s")
    return forms


def _prefer_produce_plural(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if len(text.split()) != 1:
        return text
    if not _PRODUCE_RE.search(_question_line(question)):
        return text
    word = text.strip().strip(" .,;:!?\"'`")
    if not word or not word[:1].isupper():
        return text
    for form in _plural_forms(word):
        key = _norm_text(form)
        if key and key in phrases:
            return _best_phrase(phrases[key], counts)
    return text


def _fix_hyphenated_acronym(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if "-" not in text:
        return text
    acronyms = re.findall(r"\b[A-Z]{2,6}\b", _question_line(question))
    if not acronyms:
        return text
    key = _norm_text(text)
    if key not in phrases:
        return text
    words = text.replace("-", " ").split()
    if len(words) < 2:
        return text
    initials = "".join(w[0] for w in words).lower()
    for acr in acronyms:
        if acr.lower() != initials:
            continue
        candidates = [
            p
            for p in phrases[key]
            if "-" not in p and len(p.split()) == len(words)
        ]
        if not candidates:
            continue
        best = _best_phrase(candidates, counts)
        if best and best != text:
            return best
    return text


def _strip_title_bangs(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if not _is_pair_list_clue(_question_line(question)):
        return text
    if not re.search(r"[!?]{2,}$", (text or "").strip()):
        return text
    key = _norm_text(text)
    if key not in phrases:
        return text
    candidates = [p for p in phrases[key] if not re.search(r"[!?]{1,}$", p.strip())]
    if not candidates:
        return text
    return _best_phrase(candidates, counts)


def _clean(text: str, question: str) -> str:
    phrases, counts = _context_phrases(question)

    t = _strip_code_fences(text)
    t = _strip_outer_quotes(t)
    t = _strip_lead_in(t)
    t = _strip_trailing_glosses(t, phrases)
    t = _strip_trailing_period(t, phrases)

    q = _question_line(question)
    if _is_role_title_clue(q) or _is_pair_list_clue(q):
        t = _extract_head(t, question, phrases, counts)

    t = _prefer_produce_plural(t, question, phrases, counts)
    t = _fix_hyphenated_acronym(t, question, phrases, counts)
    t = _strip_title_bangs(t, question, phrases, counts)

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        return {"action": "replace", "answer": cleaned}
    return None

texts.b0841aa68da21f087a3a0cbce4990815837f9f1c:
"""Deterministic short-answer surface cleaner.

This hook runs only for tasks whose instruction says to return only the short
answer. It removes generic surface wrappers that break exact-match scoring:
discourse lead-ins, parenthetical/bracket glosses, dash glosses, trailing
sentence punctuation, and wrapper articles. It then prefers the exact surface
form used by the supplied context, restores plural produce nouns, and extracts
the minimal head for bare role/title and pair/list clues.

It never calls a model and never changes the selected entity or term. All
edits are lexical and reversible by construction.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER = re.compile(r"^\[[^\]]*\]$")
_PAREN_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]*[\)\]]")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAILING_PUNCT_RE = re.compile(r"[.!?]+$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.[A-Za-z]\.?$")
_ARTICLE_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)
_OF_FROM_RE = re.compile(r"\b(of|from)\s+(.+)$", re.IGNORECASE)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|"
    r"berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|"
    r"why|how|his|her|he|she|him)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _strip_bracket_wrappers(text: str) -> str:
    """Remove one matched pair of surrounding brackets/parentheses only when it
    wraps the whole phrase."""
    for open_ch, close_ch in (("(", ")"), ("[", "]")):
        if text.startswith(open_ch) and text.endswith(close_ch):
            inner = text[1:-1].strip()
            if inner and _norm_text(inner) == _norm_text(text):
                return inner
    return text


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized n-grams back to the surface phrases that produced them."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _phrase_quality(phrase: str) -> tuple:
    stripped = _strip_surrounding(phrase)
    bracket_penalty = sum(1 for ch in phrase if ch in "()[]")
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        stripped.count(" "),
        -stripped.count("-"),
        -bracket_penalty,
        len(stripped),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _echo_context_form(text: str, question: str) -> str:
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    key = _norm_text(text)
    if not key or key not in phrases:
        return text
    ctx = _context_text(question)
    best = _strip_surrounding(_best_phrase(phrases[key], ctx))
    return _strip_bracket_wrappers(best)


def _supported(phrase: str, question: str) -> bool:
    key = _norm_text(phrase)
    if not key:
        return False
    phrases, _ = _context_phrases(question)
    if key in phrases:
        return True
    return phrase.casefold() in question.casefold()


def _strip_parentheticals(text: str) -> str:
    cur = text
    for _ in range(8):
        nxt = _PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            cur = nxt
            continue
        break
    return cur


def _strip_dash_gloss(text: str, question: str) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _supported(before, question):
        return before
    return text


def _strip_lead(text: str) -> str:
    text = _LEAD_IN_RE.sub("", text).strip()
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail and len(tail.split()) >= 3:
            return tail
    return text


def _strip_trailing_punct(text: str) -> str:
    while True:
        match = _TRAILING_PUNCT_RE.search(text)
        if not match:
            return text
        if _ABBREV_RE.search(text):
            return text
        nxt = text[: match.start()].rstrip()
        if not nxt:
            return text
        text = nxt


def _strip_leading_article(text: str, question: str) -> str:
    """Drop a wrapper article only when the article-less form is itself
    supported by the task text. Preserves canonical phrases that genuinely
    begin with an article (titles, brand names, works of art)."""
    match = _ARTICLE_RE.match(text)
    if not match:
        return text
    rest = match.group("rest").strip()
    if not rest:
        return text
    if _supported(rest, question) and not _supported(text, question):
        return rest
    return text


def _plural_candidates(word: str) -> list[str]:
    if not word or word.endswith("s"):
        return []
    candidates = []
    if re.search(r"[^aeiou]y$", word, re.IGNORECASE):
        candidates.append(word[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", word, re.IGNORECASE):
        candidates.append(word + "es")
    candidates.append(word + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question: str) -> str:
    if len(text.split()) != 1:
        return text
    q = _question_line(question)
    if not _PRODUCE_RE.search(q):
        return text
    word = _strip_surrounding(text)
    if not word or word.endswith("s"):
        return text
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    for candidate in _plural_candidates(word):
        key = _norm_text(candidate)
        if key and key in phrases:
            ctx = _context_text(question)
            return _strip_surrounding(_best_phrase(phrases[key], ctx))
    return text


def _capitalized_words(text: str) -> list[str]:
    return [t for t in re.findall(r"[A-Za-z][A-Za-z'\-]*", text)]


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _extract_minimal_head(text: str, question: str) -> str:
    match = _OF_FROM_RE.search(text)
    if not match:
        return text
    tail = match.group(2).strip().strip(" .,;:!?\"'`")
    tail = re.sub(r"^(?:the|a|an)\s+", "", tail, flags=re.IGNORECASE)
    run: list[str] = []
    for tok in tail.split():
        if tok and tok[0].isupper() and not tok[0].isdigit():
            run.append(tok)
        else:
            break
    if len(run) != 1:
        return text
    candidate = run[0]
    return _echo_context_form(candidate, question) or candidate


def _clean(text: str, question: str) -> str:
    t = _strip_lead(text)
    t = _strip_parentheticals(t)
    t = _strip_dash_gloss(t, question)
    t = _strip_leading_article(t, question)
    t = _strip_trailing_punct(t)
    t = " ".join(t.split())
    t = _echo_context_form(t, question)

    if _short_answer_requested(question):
        t = _prefer_plural_produce_form(t, question)
        q = _question_line(question)
        if _is_role_title_clue(q) or _is_pair_list_clue(q):
            t = _extract_minimal_head(t, question)
            t = _echo_context_form(t, question)
    return t


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.b6e4ef5121bdba7cedf223489efa84415a385f40:
"""Deterministic final-answer cleaner for short-answer QA tasks.

This hook runs only when the user request contains the explicit short-answer
instruction (``return only the short answer``). It never calls a model and
never changes which entity or term the model selected: it removes surface
wrappers and re-echoes the supplied context's dominant surface form for the
same normalized token sequence.

Each removal is deliberately narrow and reversible:

  * surrounding code fences / matched quotes
  * ``Answer is:`` / ``The answer is`` lead-ins
  * discourse lead-ins such as ``True -- ...``
  * a trailing sentence period (abbreviations and initialisms are preserved)
  * trailing parenthetical/bracket glosses
  * trailing em/en-dash glosses whose head is supported by the context
  * decorative trailing ``!``/``?`` marks when the base is context-supported
  * a leading article when the article-less form is context-supported
  * a trailing category suffix or ``of <Name>`` qualifier when the question
    asks for a short form (nickname, term, company, network, mint, etc.)
  * canonical surface echo: case, spacing, and hyphenation are copied from the
    most frequent supplied-context variant of the same normalized phrase
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_CODE_FENCE_RE = re.compile(r"^```[A-Za-z]*\s*\n(.*?)\n?```$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:-]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAIL_PAREN_RE = re.compile(r"\s*\([^()]{1,160}\)\s*$")
_TRAIL_BRACKET_RE = re.compile(r"\s*\[[^\[\]]{1,160}\]\s*$")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_TRAIL_PERIOD_RE = re.compile(r"\.$")
_TRAIL_BANG_RE = re.compile(r"[!?]+$")
_ARTICLE_RE = re.compile(r"^(a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)
_OF_QUAL_RE = re.compile(r"^(?P<head>.+?)\s+of\s+(?P<tail>[A-Z][A-Za-z]*)$")

_ABBREV_RE = re.compile(
    r"(?:\b[A-Za-z]\.){2,}$|\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", re.IGNORECASE
)

_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "called it",
    "referred to as",
    "term for",
    "surname",
    "acronym",
    "pre-",
    "type of",
    "company",
    "network",
    "mint",
    "association",
    "organization",
    "organisation",
    "radio",
    "alliance",
)

_CATEGORY_SUFFIXES = {
    "party",
    "network",
    "mint",
    "radio",
    "satellite",
    "television",
    "film",
    "show",
    "sitcom",
}

_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "comedian",
)

_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who|what|which)\b", re.IGNORECASE)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")
_TITLE_CASE_SEQ_RE = re.compile(
    r"\b[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]*(?:\s+[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]*)+\b"
)

_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    """Casefold and collapse every non-alphanumeric run to a single space."""
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _strip_surrounding(text: str) -> str:
    return (text or "").strip(" \t\r\n.,;:!?\"'`")


def _surface_map(question: str) -> dict[str, list[tuple[str, int]]]:
    """Map normalized n-gram keys to (surface, count) variants from context."""
    ctx = _context_text(question)
    surfaces: dict[str, list[tuple[str, int]]] = {}
    if not ctx:
        return surfaces

    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(6, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                phrase = " ".join(tokens[i : i + n])
                key = _chunk_key(phrase)
                if not key:
                    continue
                bucket = surfaces.setdefault(key, [])
                if all(surface != phrase for surface, _ in bucket):
                    bucket.append((phrase, 0))
    # Fill counts from the raw context (case-insensitive, exact surface).
    ctx_lower = ctx.lower()
    for key, bucket in surfaces.items():
        for idx, (surface, _) in enumerate(bucket):
            bucket[idx] = (surface, ctx_lower.count(surface.lower()))
    return surfaces


def _surface_quality(item: tuple[str, int], candidate: str) -> tuple:
    surface, count = item
    stripped = _strip_surrounding(surface)
    return (
        count,
        1 if surface.casefold() == candidate.casefold() else 0,
        1 if stripped[:1].isupper() else 0,
        1 if not stripped.isupper() else 0,
        -stripped.count("-"),
        -len(stripped),
    )


def _best_surface(bucket: list[tuple[str, int]], candidate: str) -> str:
    if not bucket:
        return candidate
    best = max(bucket, key=lambda item: _surface_quality(item, candidate))
    return _strip_surrounding(best[0])


def _has_key(text: str, surfaces: dict) -> bool:
    key = _chunk_key(text)
    return bool(key) and key in surfaces


def _strip_code_fence(text: str) -> str:
    match = _CODE_FENCE_RE.match(text.strip())
    if match:
        return match.group(1).strip()
    return text


def _strip_surrounding_quotes(text: str) -> str:
    t = text.strip()
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                return inner
    return t


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_RE.match(text.strip())
    if match and match.group("tail").strip():
        return match.group("tail").strip()
    return text


def _strip_answer_lead(text: str) -> str:
    return _LEAD_IN_RE.sub("", text.strip()).strip()


def _strip_trailing_parentheticals(text: str) -> str:
    cur = text.strip()
    for _ in range(8):
        prev = cur
        for pattern in (_TRAIL_PAREN_RE, _TRAIL_BRACKET_RE):
            match = pattern.search(cur)
            if match:
                nxt = cur[: match.start()].strip()
                if nxt and nxt != cur:
                    cur = nxt
                    break
        if cur == prev:
            break
    return cur


def _strip_trailing_dash_gloss(text: str, surfaces: dict) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _has_key(before, surfaces):
        return before
    return text


def _strip_trailing_period(text: str, surfaces: dict) -> str:
    cur = text.strip()
    for _ in range(4):
        if not cur.endswith(".") or cur.endswith(".."):
            break
        if _ABBREV_RE.search(cur):
            break
        nxt = cur[:-1].rstrip()
        if not nxt:
            break
        if cur[-2].islower() or cur[-2] in ")]}\"'" or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_trailing_bang(text: str, surfaces: dict) -> str:
    """Strip decorative trailing !/? when the base is context-supported or the
    mark is doubled. Titles such as ``What's Happening!!`` become the plain
    context-supported form."""
    cur = text.strip()
    for _ in range(4):
        match = _TRAIL_BANG_RE.search(cur)
        if not match:
            break
        run = match.group(0)
        nxt = cur[: match.start()].rstrip()
        if not nxt:
            break
        if len(run) >= 2 or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_leading_article(text: str, surfaces: dict) -> str:
    match = _ARTICLE_RE.match(text.strip())
    if not match:
        return text.strip()
    rest = match.group("rest").strip()
    if not rest:
        return text.strip()
    if _has_key(rest, surfaces) or rest[0].isupper() or rest[0].isdigit():
        return rest
    return text.strip()


def _short_form_clue(question: str) -> bool:
    q = _question_line(question).lower()
    return any(marker in q for marker in _SHORT_FORM_MARKERS)


def _strip_of_qualifier(text: str, surfaces: dict, question: str) -> str:
    if not _short_form_clue(question):
        return text
    match = _OF_QUAL_RE.match(text.strip())
    if not match:
        return text
    head = match.group("head").strip()
    if head and _has_key(head, surfaces):
        return head
    return text


def _strip_category_suffix(text: str, surfaces: dict, question: str) -> str:
    if not _short_form_clue(question):
        return text
    cur = text.strip()
    for _ in range(5):
        words = cur.split()
        if len(words) <= 1:
            break
        if words[-1].lower().strip(".,;:!?") not in _CATEGORY_SUFFIXES:
            break
        prefix = " ".join(words[:-1]).strip()
        if not prefix or not _has_key(prefix, surfaces):
            break
        cur = prefix
    return cur


def _echo_context_form(text: str, surfaces: dict, original: str) -> str:
    key = _chunk_key(text)
    if not key or key not in surfaces:
        return text
    return _best_surface(surfaces[key], original)


def _looks_sentence(text: str) -> bool:
    words = text.split()
    return len(words) >= 5 and re.search(
        r"\b(is|was|are|were|published|wrote|invented)\b", text, re.IGNORECASE
    ) is not None


def _is_person_surname_clue(question: str) -> bool:
    q = _question_line(question).lower()
    if not _PERSON_DEMO_RE.search(q):
        return False
    if _PERSON_PRONOUN_RE.search(q):
        return False
    return any(role in q for role in _PERSON_ROLE_WORDS)


def _is_factual_person_clue(question: str) -> bool:
    q = _question_line(question).lower()
    return bool(_PERSON_PRONOUN_RE.search(q)) and not bool(_DEMO_RE.search(q))


def _extract_surname(text: str, surfaces: dict, question: str) -> str:
    if not _is_person_surname_clue(question):
        return text
    words = text.split()
    if len(words) not in (2, 3):
        return text
    if not all(_NAME_TOKEN_RE.match(word.strip(".,;:!?")) for word in words):
        return text
    surname = words[-1].strip(".,;:!?")
    if _has_key(surname, surfaces):
        return surname
    return text


def _extract_factual_person(text: str, surfaces: dict, question: str) -> str:
    """For ``After he ... he published ...`` clues, keep only the leading
    context-supported proper-name phrase instead of the full sentence."""
    if not _is_factual_person_clue(question):
        return text
    if not _looks_sentence(text):
        return text
    for match in _TITLE_CASE_SEQ_RE.finditer(text):
        phrase = match.group(0).strip()
        if len(phrase.split()) >= 2 and _has_key(phrase, surfaces):
            return phrase
    return text


def _is_bare_role_title_clue(question: str) -> bool:
    q = _question_line(question)
    if not q or "," in q or _DEMO_RE.search(q):
        return False
    words = q.split()
    if not (2 <= len(words) <= 6):
        return False
    return all(
        re.match(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]*$", word.strip(".,;:!?"))
        for word in words
    )


def _is_pair_list_clue(question: str) -> bool:
    q = _question_line(question)
    if not q or "," not in q or _DEMO_RE.search(q):
        return False
    parts = [part.strip() for part in q.split(",") if part.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        words = part.split()
        if not (1 <= len(words) <= 5):
            return False
        if not all(
            re.match(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\"\-]*$", word.strip(".,;:!?"))
            for word in words
        ):
            return False
    return True


def _extract_head_after_of_or_from(text: str, question: str) -> str:
    """For bare role/title and pair/list clues, keep the first capitalized head
    after ``of``/``from`` (country/state/organization)."""
    if not (_is_bare_role_title_clue(question) or _is_pair_list_clue(question)):
        return text
    match = re.search(
        r"\b(?:of|from)\s+(?P<head>[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]*)", text
    )
    if not match:
        return text
    return match.group("head")


def _plural_candidates(word: str) -> list[str]:
    if not word:
        return []
    out = []
    if re.search(r"[^aeiou]y$", word, re.IGNORECASE):
        out.append(word[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", word, re.IGNORECASE):
        out.append(word + "es")
    out.append(word + "s")
    return out


def _prefer_plural_produce(text: str, surfaces: dict, question: str) -> str:
    if len(text.split()) != 1:
        return text
    q = _question_line(question)
    if not _PRODUCE_RE.search(q):
        return text
    word = _strip_surrounding(text)
    if not word or not word[:1].isupper():
        return text
    for candidate in _plural_candidates(word):
        key = _chunk_key(candidate)
        if key and key in surfaces:
            return _best_surface(surfaces[key], text)
    return text


def _clean(original: str, question: str) -> str:
    surfaces = _surface_map(question)

    text = original.strip()
    text = _strip_code_fence(text)
    text = _strip_surrounding_quotes(text)
    text = _strip_discourse_lead(text)
    text = _strip_answer_lead(text)
    text = _strip_trailing_dash_gloss(text, surfaces)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_parentheticals(text)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_bang(text, surfaces)
    text = _strip_leading_article(text, surfaces)
    text = _strip_of_qualifier(text, surfaces, question)
    text = _strip_category_suffix(text, surfaces, question)

    # Canonicalize spacing/case/hyphenation from the supplied context first.
    text = _echo_context_form(text, surfaces, original)

    # Echo may re-introduce decorative title punctuation; strip it one final
    # time without re-echoing so we do not undo the punctuation cleanup.
    text = _strip_trailing_bang(text, surfaces)

    # Targeted minimal-form extraction, in priority order.
    text = _extract_surname(text, surfaces, question)
    text = _extract_factual_person(text, surfaces, question)
    text = _extract_head_after_of_or_from(text, question)
    text = _prefer_plural_produce(text, surfaces, question)

    return " ".join(text.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.bdae5aa4278b3f3e0b536c91f3cfa52009d7f733:
"""Conservative deterministic short-answer surface cleaner.

Runs only when the task explicitly says to return only the short answer.
It performs lexical-only, context-gated normalization:

  * strip code fences and one matched pair of surrounding quotes
  * strip "answer is / answer:" lead-ins
  * strip True/False/Yes/No discourse lead-ins ("True — ...")
  * strip a trailing sentence period or repeated !/? only when the remaining
    phrase is supported verbatim by the supplied context
  * strip trailing parenthetical/bracket glosses only when the remaining
    phrase is a verbatim context phrase
  * strip trailing em/en-dash glosses only when the remaining phrase is a
    verbatim context phrase

For three recurring generic clue shapes it also reduces a verbose draft to
the requested head phrase, but only when the extracted phrase is itself a
verbatim context phrase:

  * factual-person statements ("he/his/her ...") -> leading name run
  * bare role/title clues ("President X", "Sultan Y") -> associated place
  * bare pair/list clues ("A,B") -> shared label after of/from/in

It never calls a model, never changes the selected entity, and deliberately
does NOT strip leading articles, shorten an organization/term to its first
word, or rewrite surface punctuation (case/hyphenation). Those decisions are
left to the bounded primary-model retry hook.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_ANSWER_LEAD_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s+(?P<gloss>.+)$", re.DOTALL)
_TRAILING_GLOSS_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]{0,120}[\)\]]\s*[.!?]*$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.([A-Za-z]\.)?$")
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

_DEF_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how)\b",
    re.IGNORECASE,
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|his|him|she|her|hers)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|whose)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_keys(question: str) -> set[str]:
    """Return normalized n-gram keys for the supplied context (up to 6 tokens)."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _strip_code_fences_and_quotes(text: str) -> str:
    t = (text or "").strip()
    if t.startswith("```") and t.endswith("```") and len(t) > 6:
        inner = t[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            t = inner
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                t = inner
                break
    return t.strip()


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail:
            return tail
    return text


def _strip_answer_lead(text: str) -> str:
    return _ANSWER_LEAD_RE.sub("", text).strip()


def _strip_trailing_punct(text: str, keys: set[str]) -> str:
    t = text
    while True:
        if t.endswith(".") and not t.endswith("..") and len(t) > 2:
            if _ABBREV_RE.search(t):
                return t
            if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", t, re.IGNORECASE):
                return t
            nxt = t[:-1].rstrip()
            if _norm_text(nxt) in keys:
                t = nxt
                continue
            return t

        match = re.search(r"[!?]+$", t)
        if not match:
            return t
        run = match.group(0)
        nxt = t[: match.start()].rstrip()
        if not nxt:
            return t
        if len(run) >= 2 or _norm_text(nxt) in keys:
            t = nxt
            continue
        return t


def _strip_trailing_parenthetical(text: str, keys: set[str]) -> str:
    match = _TRAILING_GLOSS_RE.search(text)
    if not match:
        return text
    nxt = text[: match.start()].strip()
    if nxt and _norm_text(nxt) in keys:
        return nxt
    return text


def _strip_trailing_dash_gloss(text: str, keys: set[str]) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _norm_text(before) in keys:
        return before
    return text


def _looks_factual_person_statement(question_line: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(question_line)) and not bool(
        _PERSON_DEMO_RE.search(question_line)
    )


def _extract_person_name_run(text: str, keys: set[str]) -> str | None:
    words = text.split()
    if len(words) < 2:
        return None
    run: list[str] = []
    for word in words:
        cleaned = word.strip(".,;:!?\"'`")
        if cleaned and _NAME_TOKEN_RE.match(cleaned):
            run.append(cleaned)
            if len(run) == 3:
                break
        else:
            break
    for length in range(len(run), 1, -1):
        candidate = " ".join(run[:length])
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _looks_role_title_clue(question_line: str) -> bool:
    if not question_line or "," in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    words = question_line.split()
    if not (2 <= len(words) <= 6):
        return False
    return all(word[:1].isupper() for word in words if word)


def _extract_role_title_place(text: str, keys: set[str]) -> str | None:
    matches = re.findall(r"\bof\s+([A-Z][A-Za-z]+)", text)
    for candidate in reversed(matches):
        if _norm_text(candidate) in keys:
            return candidate
    match = re.search(r"\bfrom\s+([A-Z][A-Za-z]+)", text)
    if match and _norm_text(match.group(1)) in keys:
        return match.group(1)
    return None


def _looks_pair_list_clue(question_line: str) -> bool:
    if not question_line or "," not in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        words = part.split()
        if not (1 <= len(words) <= 5):
            return False
        if not all(word[:1].isupper() for word in words if word):
            return False
    return True


def _extract_pair_list_label(text: str, keys: set[str]) -> str | None:
    match = re.search(r"\b(?:from|of|in)\s+([A-Z][A-Za-z]+)(?=\s+(?:and|,)|$)", text)
    if match:
        candidate = match.group(1)
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _clean(text: str, question: str) -> str:
    t = " ".join((text or "").split())
    if not t:
        return t

    keys = _context_keys(question)

    t = _strip_code_fences_and_quotes(t)
    t = _strip_discourse_lead(t)
    t = _strip_answer_lead(t)

    # Iteratively remove one trailing surface wrapper at a time. Every removal
    # is gated on the remaining phrase being a verbatim context n-gram, so the
    # pass never changes the selected entity.
    for _ in range(10):
        prev = t
        t = _strip_trailing_punct(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_parenthetical(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_dash_gloss(t, keys)
        if t != prev:
            continue
        break

    q = _question_line(question)
    if _looks_factual_person_statement(q) and len(t.split()) > 3:
        extracted = _extract_person_name_run(t, keys)
        if extracted:
            t = extracted
    elif _looks_role_title_clue(q):
        extracted = _extract_role_title_place(t, keys)
        if extracted:
            t = extracted
    elif _looks_pair_list_clue(q):
        extracted = _extract_pair_list_label(t, keys)
        if extracted:
            t = extracted

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean a final short answer into its bare requested surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_clean", {})
    state["replaced_this_turn"] = False

    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        state["replaced_this_turn"] = True
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

