                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _strip_code_fences_and_quotes(text: str) -> str:
    t = (text or "").strip()
    if t.startswith("```") and t.endswith("```") and len(t) > 6:
        inner = t[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            t = inner
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                t = inner
                break
    return t.strip()


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail:
            return tail
    return text


def _strip_answer_lead(text: str) -> str:
    return _ANSWER_LEAD_RE.sub("", text).strip()


def _strip_trailing_punct(text: str, keys: set[str]) -> str:
    t = text
    while True:
        if t.endswith(".") and not t.endswith("..") and len(t) > 2:
            if _ABBREV_RE.search(t):
                return t
            if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", t, re.IGNORECASE):
                return t
            nxt = t[:-1].rstrip()
            if _norm_text(nxt) in keys:
                t = nxt
                continue
            return t

        match = re.search(r"[!?]+$", t)
        if not match:
            return t
        run = match.group(0)
        nxt = t[: match.start()].rstrip()
        if not nxt:
            return t
        if len(run) >= 2 or _norm_text(nxt) in keys:
            t = nxt
            continue
        return t


def _strip_trailing_parenthetical(text: str, keys: set[str]) -> str:
    match = _TRAILING_GLOSS_RE.search(text)
    if not match:
        return text
    nxt = text[: match.start()].strip()
    if nxt and _norm_text(nxt) in keys:
        return nxt
    return text


def _strip_trailing_dash_gloss(text: str, keys: set[str]) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _norm_text(before) in keys:
        return before
    return text


def _word_in_text(word: str, text: str) -> bool:
    key = _norm_token(word)
    if not key:
        return False
    return key in {_norm_token(tok) for tok in (text or "").split() if _norm_token(tok)}


def _candidate_is_question_quote(text: str, question_line: str) -> bool:
    cand_key = _norm_text(text)
    if not cand_key:
        return False
    for match in _QUOTED_PHRASE_RE.finditer(question_line):
        quoted = match.group(1).strip()
        if _norm_text(quoted) != cand_key:
            continue
        prefix = question_line[: match.start()].rstrip()
        if re.search(r"\b(?:these|those)\s*$", prefix, re.IGNORECASE):
            return True
    return False


def _strip_question_duplicated_qualifiers(
    text: str, question: str, keys: set[str]
) -> str:
    """Drop leading qualifiers already stated in the question.

    This is deliberately narrow: it only fires for "of these/those" category
    clues, never for a candidate that echoes the question's own quoted phrase,
    and only when the remaining suffix is a verbatim context phrase whose head
    is lowercase (a category/term head rather than a proper noun). It exists to
    reverse over-qualification such as "Chinese laundries" -> "laundries" when
    "Chinese" is already part of the clue.
    """
    qline = _question_line(question)
    if not _OF_THESE_RE.search(qline):
        return text
    if _candidate_is_question_quote(text, qline):
        return text

    words = text.split()
    if len(words) < 2:
        return text

    for n in range(1, len(words)):
        suffix = " ".join(words[n:])
        suffix_key = _norm_text(suffix)
        if not suffix_key or suffix_key not in keys:
            continue
        if not suffix[:1].islower():
            continue
        dropped = words[:n]
        if all(_word_in_text(word, qline) for word in dropped):
            return suffix
    return text


def _looks_factual_person_statement(question_line: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(question_line)) and not bool(
        _PERSON_DEMO_RE.search(question_line)
    )


def _extract_person_name_run(text: str, keys: set[str]) -> str | None:
    words = text.split()
    if len(words) < 2:
        return None
    run: list[str] = []
    for word in words:
        cleaned = word.strip(".,;:!?\"'`")
        if cleaned and _NAME_TOKEN_RE.match(cleaned):
            run.append(cleaned)
            if len(run) == 3:
                break
        else:
            break
    for length in range(len(run), 1, -1):
        candidate = " ".join(run[:length])
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _looks_role_title_clue(question_line: str) -> bool:
    if not question_line or "," in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    words = question_line.split()
    if not (2 <= len(words) <= 6):
        return False
    return all(word[:1].isupper() for word in words if word)


def _extract_role_title_place(text: str, keys: set[str]) -> str | None:
    matches = re.findall(r"\bof\s+([A-Z][A-Za-z]+)", text)
    for candidate in reversed(matches):
        if _norm_text(candidate) in keys:
            return candidate
    match = re.search(r"\bfrom\s+([A-Z][A-Za-z]+)", text)
    if match and _norm_text(match.group(1)) in keys:
        return match.group(1)
    return None


def _looks_pair_list_clue(question_line: str) -> bool:
    if not question_line or "," not in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        words = part.split()
        if not (1 <= len(words) <= 5):
            return False
        if not all(word[:1].isupper() for word in words if word):
            return False
    return True


def _extract_pair_list_label(text: str, keys: set[str]) -> str | None:
    match = re.search(r"\b(?:from|of|in)\s+([A-Z][A-Za-z]+)(?=\s+(?:and|,)|$)", text)
    if match:
        candidate = match.group(1)
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _clean(text: str, question: str) -> str:
    t = " ".join((text or "").split())
    if not t:
        return t

    keys = _context_keys(question)

    t = _strip_code_fences_and_quotes(t)
    t = _strip_discourse_lead(t)
    t = _strip_answer_lead(t)

    # Iteratively remove one trailing surface wrapper at a time. Every removal
    # is gated on the remaining phrase being a verbatim context n-gram, so the
    # pass never changes the selected entity.
    for _ in range(10):
        prev = t
        t = _strip_trailing_punct(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_parenthetical(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_dash_gloss(t, keys)
        if t != prev:
            continue
        break

    t = _strip_question_duplicated_qualifiers(t, question, keys)

    q = _question_line(question)
    if _looks_factual_person_statement(q) and len(t.split()) > 3:
        extracted = _extract_person_name_run(t, keys)
        if extracted:
            t = extracted
    elif _looks_role_title_clue(q):
        extracted = _extract_role_title_place(t, keys)
        if extracted:
            t = extracted
    elif _looks_pair_list_clue(q):
        extracted = _extract_pair_list_label(t, keys)
        if extracted:
            t = extracted

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean a final short answer into its bare requested surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_clean", {})
    state["replaced_this_turn"] = False

    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        state["replaced_this_turn"] = True
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.cb7c61f624e0cc337c3c2ce097ed28200655d9e3:
"""Side-LLM canonical short-answer verifier.

Runs after the deterministic cleaner. For short-answer QA, up to two bounded
side calls re-derive the single correct answer from the supplied context and
map it back to the exact context surface form. It only replaces the draft when
the side answer is a verbatim context phrase, is no longer than the draft, and
is not a forbidden surname-only shortening of a factual person statement.
"""

from __future__ import annotations

import re

_MARKER = re.compile(r"^\[[^\]]*\]$")
_PERSON_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_DEMO_RE = re.compile(r"\b(this|these|that|those)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_text(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _looks_factual_person_statement(question: str) -> bool:
    """A factual statement about a person usually wants the full name, not a
    bare surname. Jeopardy-style 'this ...' clues are handled separately."""
    q = _question_text(question)
    return bool(_PERSON_RE.search(q)) and not bool(_DEMO_RE.search(q))


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to their original context phrases."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _phrase_quality(phrase: str) -> tuple:
    """Prefer title case over ALL CAPS and preserve stylized punctuation."""
    stripped = _strip_surrounding(phrase)
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        len(stripped),
        stripped.count(" "),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    """Pick the dominant context surface form for a normalized key."""
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _clean_side_output(text: str, phrases: dict[str, list[str]] | None = None) -> str:
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines:
        return ""
    cleaned_lines: list[str] = []
    for raw in lines:
        out = raw.strip().strip("\"'`").strip()
        out = re.sub(
            r"^(?:answer\s*(?:is|:)?\s*)", "", out, flags=re.IGNORECASE
        ).strip()
        if not out:
            continue
        cleaned_lines.append(out)
        if phrases and _norm_text(out) in phrases:
            return out
    return cleaned_lines[-1] if cleaned_lines else ""


def _prompt(question: str, draft: str, hint: str | None = None) -> str:
    base = (
        "You are checking a short-answer QA draft. Use ONLY the supplied context below.\n\n"
        + question
        + "\n\nDraft answer:\n"
        + draft
        + "\n\n"
        "Think through the steps internally; do not write them out.\n"
        "1. List the distinct clues/constraints in the question.\n"
        "2. Check whether the draft answer satisfies every one of those clues. "
        "If it does, return the draft unchanged.\n"
        "3. If it does not, find the context passage whose stated function, name, "
        "relationship, date, denomination, or description satisfies ALL of the "
        "clues, then return the exact phrase from that passage.\n\n"
        "Return only the final answer string, using the exact spelling, "
        "capitalization, hyphenation, number, and name extent from the context.\n"
        "Rules:\n"
        "- When passages conflict, prefer the one that satisfies every clue "
        "(for example a specific denomination/date/description), not one that "
        "matches only a keyword.\n"
        "- For a Jeopardy-style 'this ...' clue, return the phrase that fills the "
        "blank, not a longer title or full name unless the clue itself requires it.\n"
        "- If the clue asks for a nickname, surname, acronym, term, place, or "
        "category, return only that form.\n"
        "- If the clue is a factual statement about a person, return the person's "
        "name exactly as the context introduces it.\n"
        "- Do not add articles unless the context phrase includes them.\n"
        "- Return only the answer string, with no explanation, quotes, or formatting."
    )
    if hint:
        base += (
            "\n\nPrevious attempt was rejected because it was " + hint
            + ". Correct that and return only the answer string."
        )
    return base


async def before_final(candidate, ctx):
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    # The deterministic cleaner already canonicalizes single-token drafts; a
    # side rewrite here would risk replacing a correct one-token answer with a
    # nearby distractor.
    if len(original.split()) < 2:
        return None

    phrases, _ = _context_phrases(ctx.question)
    if not phrases:
        return None

    state = ctx.state["verify_short_answer"]
    attempts = state.get("fired", 0)
    original_key = _norm_text(original)

    # Bounded retries with an explicit exit condition: at most two side calls.
    while attempts < 2:
        attempts += 1
        state["fired"] = attempts
        hint = None
        if attempts == 2:
            hint = "not a verbatim phrase from the supplied context"

        try:
            extracted = await ctx.side_text(
                _prompt(ctx.question, original, hint),
                purpose=f"verify_short_answer_{attempts}",
                max_tokens=80,
            )
        except Exception:
            ctx.trace.event("verify_short_answer_error", error="side_text_raised")
            return None
        if not extracted:
            return None

        side_clean = _clean_side_output(extracted, phrases)
        side_key = _norm_text(side_clean)
        if not side_key or side_key == original_key:
            return None
        if side_key not in phrases:
            ctx.trace.event(
                "verify_short_answer_rejected",
                attempt=attempts,
                reason="side_not_context_phrase",
            )
            continue

        ctx_text = _context_text(ctx.question)
        cleaned = _strip_surrounding(_best_phrase(phrases[side_key], ctx_text))
        cleaned_key = _norm_text(cleaned)
        if cleaned_key == original_key:
            return None

        # Do not shorten a factual person statement to a bare surname when the
        # draft already uses the person's full context name.
        if (
            _looks_factual_person_statement(ctx.question)
            and original_key in phrases
            and len(original.split()) >= 2
            and len(cleaned.split()) < 2
        ):
            ctx.trace.event(
                "verify_short_answer_rejected", reason="person_name_shortening_guard"
            )
            return None

        if len(cleaned.split()) > len(original.split()):
            ctx.trace.event(
                "verify_short_answer_rejected", reason="side_longer_than_draft"
            )
            return None

        ctx.trace.event(
            "verify_short_answer_replace",
            draft=original,
            replacement=cleaned,
            attempt=attempts,
            length_before=len(original.split()),
            length_after=len(cleaned.split()),
        )
        return {"action": "replace", "answer": cleaned}

    return None

texts.cc8532f530e74ddef83763203da6d585ba4974b7:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
attempt only when the cleaned candidate is still unlikely to be accepted as a
bare exact-match short answer:

  1. the candidate is prose-like, or
  2. the candidate is not a verbatim phrase from the supplied context, or
  3. the question states a monetary amount but every context passage that
     supports the candidate's head token omits that amount while some other
     passage in the context states it (a keyword-only distractor).

The primary model remains the only author of the final answer. Each trigger
fires at most once per task, and the runtime's remaining-turn and final-continue
budgets bound every retry, so this cannot loop.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\b", re.IGNORECASE
)
_ARTICLE_OPEN_RE = re.compile(r"^(?:a|an|the)\s+", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")

_LEADING_ARTICLE = {"a", "an", "the"}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(5, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                key = _chunk_key(" ".join(tokens[i : i + n]))
                if key:
                    keys.add(key)
    return keys


def _looks_like_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 7:
        return True
    if len(words) >= 4 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    if (
        len(words) == 2
        and _ARTICLE_OPEN_RE.match(text)
        and _SENTENCE_END_RE.search(text)
    ):
        return True
    return False


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _passages(question: str) -> list[tuple[list[str], str]]:
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in re.split(r"\[DOC\]", ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_chunk_key(tok) for tok in raw.split() if _chunk_key(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _candidate_head(candidate: str) -> str | None:
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _generic_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer or was not copied "
        "verbatim from the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from the "
        "supplied context. No lead-in, explanation, parenthetical, gloss, date, "
        "or extra punctuation."
    )


def _currency_feedback(draft: str, amounts: list[str]) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the context passage supporting your previous "
        "answer does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own passage "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    state = ctx.state["short_answer_retry"]
    fired = state.get("fired", 0)
    if fired >= 2:
        return None

    # Trigger 1: monetary-amount constraint gap. Run first so the more specific
    # feedback is used when both this and the generic trigger apply.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            head = _candidate_head(original)
            if passages and head:
                head_key = _chunk_key(head)
                supporting = [
                    raw for _, raw in passages if head_key in _chunk_key(raw)
                ]
                if supporting:
                    covered = {amount: False for amount in amounts}
                    for raw in supporting:
                        for amount in amounts:
                            if amount in raw:
                                covered[amount] = True
                    ctx_lower = _context_text(ctx.question).lower()
                    missing = [
                        amount
                        for amount in amounts
                        if not covered[amount] and amount.lower() in ctx_lower
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = fired + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _currency_feedback(original, missing),
                        }

    # Trigger 2: prose or non-context candidate.
    if state.get("format_fired", 0) < 1:
        keys = _context_phrase_keys(ctx.question)
        if _looks_like_prose(original) or _chunk_key(original) not in keys:
            state["format_fired"] = 1
            state["fired"] = fired + 1
            ctx.trace.event(
                "short_answer_retry_continue",
                candidate=original,
                reason="format_or_non_context",
            )
            return {"action": "continue", "feedback": _generic_feedback(original)}

    return None

texts.d486c0e06e954c7dbbfbdb1c4017ae4b0f892601:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").
4. A one-word produce/plant candidate with a same-stem context variant
   (usually singular vs plural).

It also includes three deterministic correction triggers:

5. A "one of these/those" clue whose candidate merely echoes the quoted clue
   phrase instead of naming the category/entity it describes.
6. A bare list clue whose candidate is a descriptive lower-case phrase about
   the listed people/items instead of the shared title/label/location.
7. A single-token person or brand answer when the supplied context introduces
   a fuller canonical proper-name surface (the inverse of the removed
   overexpansion trigger, so it restores full names rather than shortening
   them).

The previous "overexpanded short form" trigger has been removed: asking the
primary model to shorten a correct full name was causing exact-match regressions
(Oliver Brown -> Brown, Daniel Boone -> Boone, Ace Hardware -> Ace). This hook
no longer requests a shorter form for any context phrase.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_QUESTION_WORD_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"he|she|his|her|him)\b",
    re.IGNORECASE,
)

_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+(?:\.)?$")
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_THIS_PERSON_RE = re.compile(
    r"\bthis\s+(man|woman|person|boy|girl)\b", re.IGNORECASE
)
_PERSON_ROLE_WORDS = (
    "man", "woman", "person", "boy", "girl", "founder", "author", "writer",
    "novelist", "poet", "playwright", "actor", "actress", "singer",
    "bandleader", "composer", "artist", "painter", "director", "senator",
    "president", "mayor", "governor", "sultan", "king", "queen", "emperor",
    "explorer", "frontiersman", "circumnavigator", "pioneer", "leader",
    "chief", "thief", "boxer", "golfer", "inventor", "scientist", "engineer",
    "aviator", "pilot", "sailor", "politician", "diplomat", "general",
    "admiral", "captain", "colonel", "marshal", "knight", "criminal",
    "detective", "sleuth", "outlaw",
)
_HONORIFIC_TOKENS = {"lord", "sir", "dr", "mr", "mrs", "ms", "st", "prof"}
_BRAND_CATEGORY_RE = re.compile(
    r"\b(company|store|chain|brand|retailer|restaurant|network|"
    r"association|organization|organisation|alliance|agency|mint|radio|"
    r"hardware|market|shop|dealer|manufacturer)\b",
    re.IGNORECASE,
)
_ONE_OF_THESE_RE = re.compile(r"\bone of (?:these|those)\b", re.IGNORECASE)
_QUOTED_PHRASE_RE = re.compile(r'"([^"]+)"')

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _is_bare_list_clue(q: str) -> bool:
    if not q or "," not in q:
        return False
    if _QUESTION_WORD_RE.search(q):
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 6):
        return False
    return all(any(ch.isupper() for ch in part) for part in parts)


def _looks_person_clue(q: str) -> bool:
    """True for person clues that normally want the full canonical name when the
    supplied context introduces one (factual statements and role clues)."""
    if not q:
        return False
    ql = q.lower()
    if _PERSON_PRONOUN_RE.search(q):
        return True
    if _THIS_PERSON_RE.search(q):
        return True
    return any(word in ql for word in _PERSON_ROLE_WORDS)


def _looks_brand_clue(q: str) -> bool:
    """True for brand/entity clues that normally want the full context name.

    A ``this ...`` clue must also carry a brand/entity category word such as
    company, store, hardware, or network. This avoids firing on generic
    ``this is ...`` clues whose correct answer is a single common noun or
    place name."""
    if not q:
        return False
    ql = q.lower()
    return bool(
        re.search(r"\bthis\b", ql)
        and _BRAND_CATEGORY_RE.search(ql)
    )


def _proper_name_like(word: str) -> bool:
    if not word:
        return False
    if word.lower() in _HONORIFIC_TOKENS:
        return True
    return bool(_NAME_TOKEN_RE.match(word))


def _fuller_proper_forms(question: str, candidate: str) -> list[str]:
    """Return multi-word proper-name surfaces where candidate is the first or
    last word, ordered by how often the fuller form appears in the context."""
    key = _norm_text(candidate)
    if not key:
        return []
    surfaces = _context_surfaces(question)
    forms: list[tuple[int, str]] = []
    for skey, bucket in surfaces.items():
        if not (skey.startswith(key) or skey.endswith(key)):
            continue
        for surface, count in bucket.items():
            words = surface.split()
            if not (2 <= len(words) <= 4):
                continue
            if not all(_proper_name_like(word) for word in words):
                continue
            if key not in (_norm_text(words[0]), _norm_text(words[-1])):
                continue
            if _norm_text(surface) == key:
                continue
            forms.append((count, surface))
    forms.sort(key=lambda item: (-item[0], item[1].casefold()))
    return [surface for _, surface in forms]


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. If the question quotes a phrase such as 'one "
        "of these \"...\"', do not echo that quoted phrase; name the "
        "category or entity it describes, using the exact context wording. "
        "If the question is a definition or category clue (\"An X that does "
        "Y\", \"this type of ...\", \"the term for ...\"), return the "
        "general category or term whose function the context states, not a "
        "specific example that shares only one property. If your previous "
        "answer was the right entity but the wrong singular/plural or surface "
        "form, fix only that form and keep the entity. Do not include any "
        "lead-in, explanation, parenthetical, gloss, date, or extra punctuation."
    )


def _echoed_clue_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "This is a 'one of these/those' clue. Your previous answer echoes the "
        "quoted phrase from the question, but the requested short answer is the "
        "category or entity that the quoted phrase describes.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the category "
        "or entity that the quoted phrase describes (for example the object, "
        "class, or term), and return only that exact context phrase, with no "
        "lead-in, explanation, or extra punctuation."
    )


def _bare_list_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "This is a bare list clue. Your previous answer describes the listed "
        "people or items, but the requested short answer is the shared title, "
        "label, or location that the supplied context gives for the whole list.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and return only the shared title, label, "
        "or location, copied verbatim from the context. Do not return a "
        "description of the people or items."
    )


def _undershorten_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may be over-shortened. The supplied context "
        "introduces this person or entity with a fuller canonical name or "
        "title, and the question does not ask for only a surname, nickname, "
        "acronym, or initials.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. If the question "
        "explicitly asks for only a surname, nickname, acronym, or initials, "
        "keep your answer unchanged. Otherwise return the fuller canonical "
        "name or title exactly as the supplied context introduces it (include "
        "the given name, honorific, or full brand/entity name the context "
        "uses). Copy the exact wording and extent from the context and return "
        "only that phrase."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 2.4: single-token candidate that looks like an over-shortened
    # person or brand answer. The inverse of the removed overexpansion trigger:
    # it only fires when the answer is already a bare token and the context
    # supplies a fuller proper-name surface, never when a correct full name is
    # already present.
    if state.get("undershorten_fired", 0) < 1:
        q = _question_line(ctx.question)
        if len(original.split()) == 1 and (
            _looks_person_clue(q) or _looks_brand_clue(q)
        ):
            fuller = _fuller_proper_forms(ctx.question, original)
            if fuller:
                state["undershorten_fired"] = 1
                state["fired"] = state.get("fired", 0) + 1
                ctx.trace.event(
                    "short_answer_retry_undershorten",
                    candidate=original,
                    fuller_forms=fuller[:3],
                )
                return {
                    "action": "continue",
                    "feedback": _undershorten_feedback(original),
                }

    # Trigger 2.5: "one of these/those" candidate that only echoes the quoted
    # clue phrase instead of naming the category/entity it describes.
    if state.get("echoed_clue_fired", 0) < 1:
        q = _question_line(ctx.question)
        if _ONE_OF_THESE_RE.search(q):
            quoted = _QUOTED_PHRASE_RE.findall(q)
            key = _norm_text(original)
            if key and any(key == _norm_text(phrase) for phrase in quoted):
                state["echoed_clue_fired"] = 1
                state["fired"] = state.get("fired", 0) + 1
                ctx.trace.event(
                    "short_answer_retry_echoed_clue", candidate=original
                )
                return {
                    "action": "continue",
                    "feedback": _echoed_clue_feedback(original),
                }

    # Trigger 2.6: bare list clue answered with a lower-case descriptive phrase
    # about the listed people/items rather than the shared title/label/location.
    if state.get("bare_list_descriptor_fired", 0) < 1:
        q = _question_line(ctx.question)
        if _is_bare_list_clue(q) and original and not original[:1].isupper():
            state["bare_list_descriptor_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event(
                "short_answer_retry_bare_list_descriptor", candidate=original
            )
            return {
                "action": "continue",
                "feedback": _bare_list_feedback(original),
            }

    # Trigger 3: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 4: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.d7cfae83375f5ec3b86b82cc0b7d29a92f1bbdd2:
"""Deterministic final-answer cleaner for short-answer QA tasks.

Removes only generic wrapper text that breaks exact-match scoring:
discourse lead-ins, parentheticals, dash glosses, leading articles, and
trailing punctuation. When the candidate's normalized token sequence matches
a phrase in the supplied context, it prefers the context's exact surface
form. No task-specific answer strings or answer forms are encoded here.
"""

from __future__ import annotations

import re

_DISCOURSE_LEAD = {
    "true",
    "false",
    "yes",
    "no",
    "correct",
    "right",
    "answer",
    "note",
    "indeed",
}
_MARKER = re.compile(r"^\[[^\]]*\]$")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to their original context phrases."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _phrase_quality(phrase: str) -> tuple:
    """Prefer title case over ALL CAPS and preserve stylized punctuation."""
    stripped = _strip_surrounding(phrase)
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        len(stripped),
        stripped.count(" "),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    """Pick the dominant context surface form for a normalized key."""
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _echo_context_form(text: str, question: str) -> str:
    """Prefer the supplied context's exact surface form for a matched phrase."""
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    key = _norm_text(text)
    if not key or key not in phrases:
        return text
    ctx = _context_text(question)
    best = _strip_surrounding(_best_phrase(phrases[key], ctx))
    # If the candidate already equals the dominant form after ignoring
    # surrounding punctuation, keep it (preserves stylized punctuation).
    if best.lower() == _strip_surrounding(text).lower():
        return text
    return best


def _strip_wrappers(text: str) -> str:
    return text.strip().strip("\"'`").strip()


_LEAD_IN = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)\s*",
    re.IGNORECASE,
)


def _strip_lead_in(text: str) -> str:
    return _LEAD_IN.sub("", text).strip()


def _strip_parentheticals(text: str) -> str:
    return re.sub(r"\s*\([^()]*\)", "", text).strip()


def _strip_dash_gloss(text: str) -> str:
    parts = re.split(r"\s+[\u2014\u2013]\s+", text)
    if len(parts) < 2:
        return text
    left = parts[0].strip().strip("\"'")
    if left.lower() in _DISCOURSE_LEAD:
        return parts[1].strip()
    return left


def _strip_leading_article(text: str) -> str:
    return re.sub(r"^(a|an|the)\s+(?=[a-z])", "", text, flags=re.IGNORECASE).strip()


def _strip_trailing_punct(text: str) -> str:
    while True:
        m = re.search(r"[.!?]+$", text)
        if not m:
            return text
        # Preserve abbreviations and initials such as "U.S." or "J. R.".
        if re.search(r"\b[A-Za-z]\.[A-Za-z]\.?$", text) or re.search(
            r"\b[A-Za-z]\.$", text
        ):
            return text
        run = m.group(0)
        # A single ! or ? is more likely part of a title than sentence
        # punctuation, so only strip repeated exclamation/question marks.
        if ("!" in run or "?" in run) and len(run) == 1:
            return text
        text = text[: m.start()].rstrip()
        if not text:
            return text


def _clean(text: str, question: str) -> str:
    t = _strip_wrappers(text)
    t = _strip_lead_in(t)
    t = _strip_parentheticals(t)
    t = _strip_dash_gloss(t)
    t = _strip_leading_article(t)
    t = _strip_trailing_punct(t)
    t = _echo_context_form(t, question)
    t = _strip_leading_article(t)
    t = _strip_trailing_punct(t)
    return " ".join(t.split())


async def before_final(candidate, ctx):
    """Clean the final short answer into its bare canonical form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        return {"action": "replace", "answer": cleaned}
    return None

texts.e61128a73bd908bd3941ebbddc6fa08520f6a8f3:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate that is a verbatim context phrase with a shorter context-phrase
   prefix/suffix and the question explicitly asks for a short name form
   (surname, nickname, acronym, initials, or a "known as" target). Generic
   "this ..." person/company clues and definition/type terms are deliberately
   not shortened.
4. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").
5. Single-token person/brand candidate whose supplied context also gives a
   fuller canonical proper-name form ending in that token; this is an
   over-shortening recovery trigger, the inverse of trigger 3.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

# Strong cues that the requested form is shorter than the full context phrase.
_SHORT_FORM_MARKERS = (
    "surname",
    "nickname",
    "nicknamed",
    "acronym",
    "short name",
    "initials",
    "known as",
    "referred to as",
    "called it",
)

_EXPLICIT_MINIMAL_NAME_MARKERS = (
    "surname",
    "nickname",
    "nicknamed",
    "acronym",
    "short name",
    "initials",
)

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)

_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_THIS_PERSON_RE = re.compile(r"\bthis\s+(man|woman|person|boy|girl)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "man", "woman", "person", "boy", "girl", "founder", "author", "writer",
    "novelist", "poet", "playwright", "actor", "actress", "singer",
    "bandleader", "composer", "artist", "painter", "director", "senator",
    "president", "mayor", "governor", "sultan", "king", "queen", "emperor",
    "explorer", "frontiersman", "circumnavigator", "pioneer", "leader",
    "chief", "thief", "boxer", "golfer", "inventor", "scientist", "engineer",
    "aviator", "pilot", "sailor", "politician", "diplomat", "general",
    "admiral", "captain", "colonel", "marshal", "knight", "criminal",
    "detective", "sleuth", "outlaw",
)
_BRAND_CATEGORY_RE = re.compile(
    r"\b(company|store|chain|brand|retailer|restaurant|network|association|"
    r"organization|organisation|alliance|agency|mint|radio|hardware|market|"
    r"shop|dealer|manufacturer)\b",
    re.IGNORECASE,
)
_HONORIFIC_TOKENS = {"lord", "sir", "dr", "mr", "mrs", "ms", "st", "prof"}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _looks_person_clue(q: str) -> bool:
    """True for person clues that normally want the full canonical name."""
    if not q:
        return False
    ql = q.lower()
    if _PERSON_PRONOUN_RE.search(q):
        return True
    if _THIS_PERSON_RE.search(q):
        return True
    return any(re.search(r"\b" + re.escape(word) + r"\b", ql) for word in _PERSON_ROLE_WORDS)


def _looks_brand_clue(q: str) -> bool:
    """True for 'this ...' brand/entity clues that may want a fuller name."""
    if not q:
        return False
    ql = q.lower()
    return bool(re.search(r"\bthis\b", ql) and _BRAND_CATEGORY_RE.search(ql))


def _proper_name_like(word: str) -> bool:
    word = (word or "").strip(" .,;:!?\"'`")
    if not word:
        return False
    if word.lower() in _HONORIFIC_TOKENS:
        return True
    return bool(_NAME_TOKEN_RE.match(word))


def _fuller_proper_forms(question: str, candidate: str) -> list[str]:
    """Return fuller proper-name context surfaces ending in ``candidate``.

    Only multi-word surfaces whose final token normalizes to the candidate are
    returned, so a bare given-name answer (e.g. ``Anastasia``) is never
    expanded from a following surname, while a bare surname answer (e.g.
    ``Drake``) can be restored to its fuller introduced form.
    """
    key = _norm_text(candidate)
    if not key:
        return []
    surfaces = _context_surfaces(question)
    forms: list[tuple[int, str]] = []
    for skey, bucket in surfaces.items():
        if not skey.endswith(key) or skey == key:
            continue
        for surface, count in bucket.items():
            words = [word.strip(" .,;:!?\"'`") for word in surface.split()]
            words = [word for word in words if word]
            if not (2 <= len(words) <= 4):
                continue
            if not all(_proper_name_like(word) for word in words):
                continue
            if _norm_text(words[-1]) != key:
                continue
            cleaned_surface = " ".join(words)
            forms.append((count, cleaned_surface))
    forms.sort(key=lambda item: (-item[0], -len(item[1].split()), item[1].casefold()))
    return [surface for _, surface in forms]


def _looks_undershortened_proper_name(text: str, question: str) -> bool:
    """Detect a one-token answer that is likely an over-shortened person/brand."""
    words = text.split()
    if len(words) != 1:
        return False
    q = _question_line(question)
    if not q:
        return False
    ql = q.lower()
    if any(marker in ql for marker in _EXPLICIT_MINIMAL_NAME_MARKERS):
        return False
    if not (_looks_person_clue(q) or _looks_brand_clue(q)):
        return False
    return bool(_fuller_proper_forms(question, text))


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _looks_overexpanded(text: str, question: str) -> bool:
    q = _question_line(question).lower()
    words = text.split()
    if len(words) < 2:
        return False

    keys = _context_phrase_keys(question)
    key = _norm_text(text)
    if key not in keys:
        return False

    # Only explicit short-name requests justify asking for a shorter phrase.
    # Generic "this ..." person/company clues and organization/association
    # clues are deliberately excluded because evidence shows they make the
    # model over-shorten correct full names (Oliver Brown -> Brown,
    # Ace Hardware -> Ace, Lord Robert Baden-Powell -> Robert Baden-Powell).
    if not any(marker in q for marker in _SHORT_FORM_MARKERS):
        return False

    for n in range(1, len(words)):
        if _norm_text(" ".join(words[:n])) in keys:
            return True
    last = _norm_text(words[-1])
    if last in keys and last != key:
        return True
    return False


def _question_token_set(question: str) -> set[str]:
    """Return normalized single-word tokens present in the question line."""
    q = _question_line(question)
    return {_norm_token(token) for token in q.split() if _norm_token(token)}


def _clue_stated_qualifier_shorter(text: str, question: str) -> list[str]:
    """Find shorter context phrases obtained by dropping a leading or trailing
    run of words that are all already stated in the question.

    This is deliberately narrower than the old generic overexpansion trigger:
    it only proposes a shorter phrase when every dropped word is a token that
    the question itself already contains, and the whole candidate is NOT simply
    a quoted phrase echoed from the question. Full proper names whose extra
    words are not in the question (for example a person's full legal name) never fire.
    """
    words = text.split()
    if len(words) < 2:
        return []

    keys = _context_phrase_keys(question)
    if _norm_text(text) not in keys:
        return []

    q_norm = _norm_text(_question_line(question))
    if _norm_text(text) in q_norm:
        return []

    q_tokens = _question_token_set(question)
    candidates: list[str] = []

    # Leading qualifier(s): "Chinese laundries" -> "laundries".
    for n in range(1, len(words)):
        dropped = words[:n]
        if not dropped:
            continue
        if not all(_norm_token(word) and _norm_token(word) in q_tokens for word in dropped):
            continue
        shorter = " ".join(words[n:]).strip()
        if shorter and _norm_text(shorter) in keys:
            candidates.append(shorter)

    # Trailing qualifier(s): "SCTV Network" -> "SCTV";
    # "Anastasia Romanov" -> "Anastasia";
    # "Sirius Satellite Radio" -> "Sirius".
    for n in range(1, len(words)):
        dropped = words[-n:]
        if not dropped:
            continue
        if not all(_norm_token(word) and _norm_token(word) in q_tokens for word in dropped):
            continue
        shorter = " ".join(words[:-n]).strip()
        if shorter and _norm_text(shorter) in keys:
            candidates.append(shorter)

    # Prefer the shortest surviving context phrase, then a stable lexical order.
    unique: dict[str, str] = {}
    for candidate in candidates:
        unique[candidate.casefold()] = candidate
    return [
        candidate
        for candidate in sorted(
            unique.values(), key=lambda s: (len(s.split()), s.casefold())
        )
        if candidate.casefold() != text.casefold()
    ]


def _clue_stated_qualifier_feedback(draft: str, shorter: list[str]) -> str:
    forms = ", ".join(shorter[:4]) if shorter else "none"
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer repeats a word or phrase that is already stated "
        "in the question.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "If the repeated word(s) are only a qualifier or category already "
        "present in the question, return the shorter exact phrase from the "
        "supplied context without them. Candidate context phrase(s): "
        + forms
        + ".\n"
        "If the repeated word is part of the entity's proper name (for "
        "example a person's full legal name or a company's full registered name), keep "
        "your previous answer unchanged.\n"
        "Copy the exact wording and extent from the supplied context, and "
        "return only the corrected exact phrase."
    )


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not include any lead-in, explanation, "
        "parenthetical, gloss, date, or extra punctuation. If the question "
        "quotes a phrase, that quoted phrase is a clue, not the answer; do "
        "not echo it. For a 'these ...' or 'one of these ...' clue, return "
        "the category term for the group, not the quoted phrase itself and "
        "not a phrase that repeats a qualifier already present in the "
        "question. If the question is a definition or category clue (\"An X "
        "that does Y\", \"this type of ...\", \"the term for ...\"), "
        "return the general category or term whose function the context "
        "states, not a specific example that shares only one property."
    )


def _short_form_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer appears to be longer than the requested short "
        "form, or uses a fuller name than the clue asks for.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question. Determine the shortest exact phrase from the "
        "supplied context that still satisfies every clue (for example a "
        "nickname, term, acronym, surname, or short company/network/mint/"
        "association name). For a definition or category clue (\"An X that "
        "does Y\", \"this type of ...\", \"the term for ...\"), return "
        "the general category or term whose function the context states, not "
        "a specific example sharing only one property. If the shorter phrase "
        "no longer satisfies every clue or no longer names the same entity, "
        "keep the full phrase. Do not drop given names, honorifics, or "
        "required company words, and do not replace a name with an epithet "
        "or descriptor. Return only the correct exact phrase."
    )


def _undershorten_feedback(draft: str, fuller_forms: list[str]) -> str:
    forms_text = ", ".join(fuller_forms[:4]) if fuller_forms else "none"
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may be over-shortened. The supplied context "
        "also introduces this person or entity with fuller canonical name "
        "forms: " + forms_text + ".\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. If the question "
        "explicitly asks for only a surname, nickname, acronym, or initials, "
        "keep your answer unchanged. Otherwise return the fuller canonical "
        "name exactly as the supplied context introduces it (including any "
        "given name or honorific the context uses). Copy the exact wording "
        "and extent from the context, and return only that phrase."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 2.4: candidate is a context phrase that repeats a qualifier or
    # category word already stated in the question. Ask the primary model to
    # drop only the repeated qualifier; full proper names are explicitly
    # protected in the feedback.
    if state.get("clue_stated_qualifier_fired", 0) < 1:
        shorter = _clue_stated_qualifier_shorter(original, ctx.question)
        if shorter:
            state["clue_stated_qualifier_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event(
                "short_answer_retry_clue_stated_qualifier",
                candidate=original,
                shorter=shorter[:4],
            )
            return {
                "action": "continue",
                "feedback": _clue_stated_qualifier_feedback(original, shorter),
            }

    # Trigger 2.5: single-token candidate that is likely an over-shortened
    # person or brand answer. The inverse of the overexpansion trigger: it only
    # fires when the answer is already a bare token and the context supplies a
    # fuller canonical proper-name surface ending in that token.
    if state.get("undershorten_fired", 0) < 1:
        if _looks_undershortened_proper_name(original, ctx.question):
            fuller = _fuller_proper_forms(ctx.question, original)
            state["undershorten_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event(
                "short_answer_retry_undershorten",
                candidate=original,
                fuller_forms=fuller[:4],
            )
            return {
                "action": "continue",
                "feedback": _undershorten_feedback(original, fuller),
            }

    # Trigger 3: candidate is a context phrase but longer than the requested
    # short form. The primary model decides whether a shorter phrase is valid.
    if state.get("overexpanded_fired", 0) < 1 and _looks_overexpanded(
        original, ctx.question
    ):
        state["overexpanded_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_overexpanded", candidate=original)
        return {"action": "continue", "feedback": _short_form_feedback(original)}

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

