"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").
4. A one-word produce/plant candidate with a same-stem context variant
   (usually singular vs plural).

The previous "overexpanded short form" trigger has been removed: asking the
primary model to shorten a correct full name was causing exact-match regressions
(Oliver Brown -> Brown, Daniel Boone -> Boone, Ace Hardware -> Ace). This hook
no longer requests a shorter form for any context phrase.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)

_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False



def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. If the question quotes a phrase such as 'one "
        "of these \"...\"', do not echo that quoted phrase; name the "
        "category or entity it describes, using the exact context wording. "
        "If the question is a definition or category clue (\"An X that does "
        "Y\", \"this type of ...\", \"the term for ...\"), return the "
        "general category or term whose function the context states, not a "
        "specific example that shares only one property. If your previous "
        "answer was the right entity but the wrong singular/plural or surface "
        "form, fix only that form and keep the entity. Do not include any "
        "lead-in, explanation, parenthetical, gloss, date, or extra punctuation."
    )



def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 3: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 4: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.e91f32bdcc73bac92b6291da72b2071338ceab5e:
"""Bounded constraint-gap retry for short-answer QA.

This hook never changes the answer itself. It only detects one reusable
failure pattern: the question names a monetary amount, but the document that
supports the current candidate does not state that amount, while some other
document in the supplied context does. That gap is a strong signal the model
latched onto a keyword-only distractor.

When the gap is found it asks the *primary* model for one more bounded attempt
with the missing amount named in the feedback. The primary model remains the
only author of the final answer, and the hook's own state enforces a single
firing per task so this cannot loop.
"""

from __future__ import annotations

import re
from typing import Any

_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]")
_LEADING_ARTICLE = {"a", "an", "the"}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    Document-level grouping is intentional: the title and body of one source
    are part of the same supporting document.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _missing_amount_feedback(amounts: list[str], candidate: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + candidate
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    if not _short_answer_requested(ctx.question):
        return None

    state = ctx.state["constraint_check"]
    if state.get("fired", 0) >= 1:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    original = (candidate or "").strip()
    if not original:
        return None

    amounts = _currency_amounts(_question_line(ctx.question))
    if not amounts:
        return None

    passages = _passages(ctx.question)
    if not passages:
        return None

    key = _candidate_key(original)
    if not key:
        return None
    key_norm = _norm_text(key)
    if not key_norm:
        return None

    candidate_docs: list[str] = []
    for _, raw in passages:
        if key_norm in _norm_text(raw):
            candidate_docs.append(raw)
    if not candidate_docs:
        return None

    # If any candidate-supporting document already states every amount, the
    # constraint is covered and there is nothing to escalate.
    covered = {amount: False for amount in amounts}
    ctx_raw = _context_text(ctx.question)
    for raw in candidate_docs:
        for amount in amounts:
            if amount in raw:
                covered[amount] = True

    missing = [
        amount
        for amount in amounts
        if not covered[amount] and amount in ctx_raw
    ]
    if not missing:
        return None

    state["fired"] = 1
    ctx.trace.event(
        "constraint_check_retry",
        candidate=original,
        missing_amounts=missing,
    )
    return {
        "action": "continue",
        "feedback": _missing_amount_feedback(missing, original),
    }

texts.f1b1c1e2b5fb1fee4411ce6e178aa5001a827e03:
"""Deterministic short-answer surface cleaner.

This hook runs only for tasks whose instruction says to return only the short
answer. It removes generic surface wrappers that break exact-match scoring:
discourse lead-ins, parenthetical/bracket glosses, dash glosses, trailing
sentence punctuation, and leading articles. It then prefers the exact surface
form used by the supplied context, restores plural produce nouns, and extracts
the minimal head for bare role/title and pair/list clues.

It never calls a model and never changes the selected entity or term. All
edits are lexical and reversible by construction.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER = re.compile(r"^\[[^\]]*\]$")
_PAREN_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]*[\)\]]")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAILING_PUNCT_RE = re.compile(r"[.!?]+$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.[A-Za-z]\.?$")
_ARTICLE_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)
_OF_FROM_RE = re.compile(r"\b(of|from)\s+(.+)$", re.IGNORECASE)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|"
    r"berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|"
    r"why|how|his|her|he|she|him)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in question.lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _strip_surrounding(text: str) -> str:
    return text.strip(" .,;:!?\"'`").strip()


def _strip_bracket_wrappers(text: str) -> str:
    """Remove one matched pair of surrounding brackets/parentheses only when it
    wraps the whole phrase."""
    for open_ch, close_ch in (("(", ")"), ("[", "]")):
        if text.startswith(open_ch) and text.endswith(close_ch):
            inner = text[1:-1].strip()
            if inner and _norm_text(inner) == _norm_text(text):
                return inner
    return text


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized n-grams back to the surface phrases that produced them."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    sequences: list[list[tuple[str, str]]] = []
    current: list[tuple[str, str]] = []
    for raw in ctx.split():
        if _MARKER.match(raw.strip()):
            if current:
                sequences.append(current)
                current = []
            continue
        norm = _norm_token(raw)
        if not norm:
            if current:
                sequences.append(current)
                current = []
            continue
        current.append((norm, raw))
    if current:
        sequences.append(current)

    for seq in sequences:
        max_n = min(5, len(seq))
        for n in range(1, max_n + 1):
            for i in range(len(seq) - n + 1):
                toks = seq[i : i + n]
                key = "".join(t[0] for t in toks)
                phrase = " ".join(t[1] for t in toks)
                counts[key] = counts.get(key, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _phrase_quality(phrase: str) -> tuple:
    stripped = _strip_surrounding(phrase)
    bracket_penalty = sum(1 for ch in phrase if ch in "()[]")
    return (
        not stripped.isupper(),
        stripped[:1].isupper(),
        stripped.count(" "),
        -stripped.count("-"),
        -bracket_penalty,
        len(stripped),
    )


def _best_phrase(bucket: list[str], ctx: str) -> str:
    counts = {p: ctx.lower().count(p.lower()) for p in bucket}
    max_count = max(counts.values())
    candidates = [p for p in bucket if counts[p] == max_count]
    return max(candidates, key=_phrase_quality)


def _echo_context_form(text: str, question: str) -> str:
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    key = _norm_text(text)
    if not key or key not in phrases:
        return text
    ctx = _context_text(question)
    best = _strip_surrounding(_best_phrase(phrases[key], ctx))
    return _strip_bracket_wrappers(best)


def _supported(phrase: str, question: str) -> bool:
    key = _norm_text(phrase)
    if not key:
        return False
    phrases, _ = _context_phrases(question)
    if key in phrases:
        return True
    return phrase.casefold() in question.casefold()


def _strip_parentheticals(text: str) -> str:
    cur = text
    for _ in range(8):
        nxt = _PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            cur = nxt
            continue
        break
    return cur


def _strip_dash_gloss(text: str, question: str) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _supported(before, question):
        return before
    return text


def _strip_lead(text: str) -> str:
    text = _LEAD_IN_RE.sub("", text).strip()
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail and len(tail.split()) >= 3:
            return tail
    return text


def _strip_trailing_punct(text: str) -> str:
    while True:
        match = _TRAILING_PUNCT_RE.search(text)
        if not match:
            return text
        if _ABBREV_RE.search(text):
            return text
        nxt = text[: match.start()].rstrip()
        if not nxt:
            return text
        text = nxt


def _strip_leading_article(text: str) -> str:
    match = _ARTICLE_RE.match(text)
    if not match:
        return text
    rest = match.group("rest").strip()
    if rest:
        return rest
    return text


def _plural_candidates(word: str) -> list[str]:
    if not word or word.endswith("s"):
        return []
    candidates = []
    if re.search(r"[^aeiou]y$", word, re.IGNORECASE):
        candidates.append(word[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", word, re.IGNORECASE):
        candidates.append(word + "es")
    candidates.append(word + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question: str) -> str:
    if len(text.split()) != 1:
        return text
    q = _question_line(question)
    if not _PRODUCE_RE.search(q):
        return text
    word = _strip_surrounding(text)
    if not word or word.endswith("s"):
        return text
    phrases, _ = _context_phrases(question)
    if not phrases:
        return text
    for candidate in _plural_candidates(word):
        key = _norm_text(candidate)
        if key and key in phrases:
            ctx = _context_text(question)
            return _strip_surrounding(_best_phrase(phrases[key], ctx))
    return text


def _capitalized_words(text: str) -> list[str]:
    return [t for t in re.findall(r"[A-Za-z][A-Za-z'\-]*", text)]


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _extract_minimal_head(text: str, question: str) -> str:
    match = _OF_FROM_RE.search(text)
    if not match:
        return text
    tail = match.group(2).strip().strip(" .,;:!?\"'`")
    tail = re.sub(r"^(?:the|a|an)\s+", "", tail, flags=re.IGNORECASE)
    run: list[str] = []
    for tok in tail.split():
        if tok and tok[0].isupper() and not tok[0].isdigit():
            run.append(tok)
        else:
            break
    if len(run) != 1:
        return text
    candidate = run[0]
    return _echo_context_form(candidate, question) or candidate


def _clean(text: str, question: str) -> str:
    t = _strip_lead(text)
    t = _strip_parentheticals(t)
    t = _strip_dash_gloss(t, question)
    t = _strip_leading_article(t)
    t = _strip_trailing_punct(t)
    t = " ".join(t.split())
    t = _echo_context_form(t, question)

    if _short_answer_requested(question):
        t = _prefer_plural_produce_form(t, question)
        q = _question_line(question)
        if _is_role_title_clue(q) or _is_pair_list_clue(q):
            t = _extract_minimal_head(t, question)
            t = _echo_context_form(t, question)
    return t


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.f26394207646f8a779324e760bc3175d31606ccc:
"""Bounded side-model verification gate for short-answer QA.

This hook runs after the deterministic surface cleaner and the primary-model
retry. It only spends a side call when the accepted draft is a compact,
context-backed phrase whose question pattern is known to be wrong-entity
prone (type-of, definition/category, or a person clue whose supporting
passage omits content clue words that appear elsewhere in the context).

On a WRONG verdict it returns one bounded ``continue`` so the primary model
(which remains the only author of the final answer) can self-correct with the
checker's reason. On CORRECT, unparseable replies, exhausted budgets, or low
risk it accepts the draft unchanged.

Exit conditions:
  * at most one side call per task,
  * at most one ``continue`` per task from this hook,
  * runtime ``remaining_turns`` and ``_final_continue_max`` are respected,
  * single-token context answers are trusted and skipped.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_VERDICT_RE = re.compile(r"\b(CORRECT|WRONG)\b", re.IGNORECASE)
_STOP_WORDS = {
    "he", "she", "his", "her", "him", "this", "that", "these", "those",
    "it", "its", "what", "which", "who", "whose", "when", "where", "why",
    "how", "the", "a", "an", "of", "as", "by", "for", "with", "to", "from",
    "in", "on", "and", "or", "but", "not", "made", "became", "was", "were",
    "is", "are",
}


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _context_phrase_keys(question: str) -> set[str]:
    """Return chunk keys for every context n-gram up to five tokens."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(5, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                key = _chunk_key(" ".join(tokens[i : i + n]))
                if key:
                    keys.add(key)
    return keys


def _risk_type(question: str, draft: str, phrase_keys: set[str]) -> str | None:
    """Return the wrong-entity risk pattern, or None if the draft is trusted."""
    qline = _question_line(question)
    words = draft.split()
    if len(words) < 2:
        return None
    if _chunk_key(draft) not in phrase_keys:
        # Non-context drafts are already handled by the retry hook.
        return None
    if len(words) > 4:
        return None

    # Type-of questions: a compact descriptor is often emitted instead of the
    # specific named type.
    if re.search(r"\btype of\b", qline, re.IGNORECASE):
        return "type_of"

    # Definition/category questions: the draft may be an example of the head
    # category rather than the category term itself.
    head = re.match(r"^(?:An?|The)\s+([A-Za-z][A-Za-z\-']*)", qline, re.IGNORECASE)
    if head:
        ctx = _context_text(question)
        head_word = head.group(1)
        example_pattern = re.compile(
            r"\bas\s+an?\s+" + re.escape(head_word) + r"\b", re.IGNORECASE
        )
        draft_key = _chunk_key(draft)
        for segment in _MARKER_RE.split(ctx):
            if draft_key not in _chunk_key(segment):
                continue
            if example_pattern.search(segment):
                return "definition_example"

    # Person clues: flag when the draft is a proper-name-like context phrase
    # but its supporting passage omits several content clue words from the
    # question that do occur elsewhere in the supplied context.
    if re.search(r"\b(?:he|she|his|her|him)\b", qline, re.IGNORECASE):
        words_ok = all(
            re.match(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-.]*$", word) for word in words
        )
        if words_ok:
            clue_words = [
                word
                for word in re.findall(r"[A-Za-z]+", qline.lower())
                if word not in _STOP_WORDS and len(word) >= 5
            ]
            if clue_words:
                ctx = _context_text(question)
                draft_key = _chunk_key(draft)
                draft_support = ""
                for segment in _MARKER_RE.split(ctx):
                    if draft_key in _chunk_key(segment):
                        draft_support += " " + segment
                if draft_support:
                    missing = [
                        word
                        for word in clue_words
                        if word not in draft_support.lower()
                    ]
                    if missing and any(
                        word in ctx.lower() for word in missing
                    ):
                        return "person_clue_gap"

    return None


def _prompt(question: str, draft: str, risk: str) -> str:
    focus = {
        "type_of": "The question asks for a specific type. Check whether the draft names that specific type or only a general descriptor.",
        "definition_example": "The question asks for a general category/term. Check whether the draft is the category/term or only an example of it.",
        "person_clue_gap": "The question contains several distinct clues (such as a role, place, event, or time span). Check whether the draft is the person whose passage actually satisfies all of those clues.",
    }.get(risk, "")
    return (
        "You are checking a short-answer QA draft.\n\n"
        "Step 1: Determine the single correct short answer yourself. Use the "
        "supplied context first; if the context is insufficient to resolve every "
        "clue, use your own knowledge of the entities involved.\n"
        "Step 2: Compare that answer with the draft below. Judge whether the "
        "draft is the exact requested short answer.\n\n"
        + focus
        + "\n\nDraft answer:\n"
        + draft
        + "\n\nQuestion with supplied context:\n"
        + question
        + "\n\nReply with exactly one line, either:\n"
        "VERDICT: CORRECT\n"
        "or\n"
        "VERDICT: WRONG | <one short reason naming the missing or wrong clue>\n"
    )


def _parse_verdict(text: str) -> tuple[str | None, str]:
    """Return (verdict, reason) from the last recognizable verdict line."""
    verdict: str | None = None
    reason = ""
    for line in (text or "").splitlines():
        line = line.strip()
        match = _VERDICT_RE.search(line)
        if not match:
            continue
        verdict = match.group(1).lower()
        after = line[match.end() :].strip().lstrip("|:-— ").strip()
        if after and after not in {".", ";", ",", "-"}:
            reason = after
    return verdict, reason


def _feedback(draft: str, reason: str) -> str:
    note = f"\nChecker note:\n{reason}\n" if reason else ""
    return (
        "The instruction says: \"Return only the short answer.\" "
        "An independent check found that your previous answer may not satisfy "
        "every clue in the question or may not be the exact requested form.\n"
        "Previous answer:\n"
        + draft
        + "\n"
        + note
        + "\nRe-read the question and the supplied context. If your previous "
        "answer already satisfies every clue and is copied verbatim from the "
        "context, return it unchanged. Otherwise identify the single requested "
        "item and return only that item, copied verbatim from the supplied "
        "context, with no lead-in, explanation, parenthetical, gloss, date, or "
        "extra punctuation."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    words = original.split()
    if len(words) <= 1:
        # Single-token context answers are canonical enough to trust.
        return None

    phrase_keys = _context_phrase_keys(ctx.question)
    if not phrase_keys:
        return None

    risk = _risk_type(ctx.question, original, phrase_keys)
    if risk is None:
        return None

    state = ctx.state["short_answer_verify"]
    if state.get("side_calls", 0) >= 1 or state.get("continued", 0) >= 1:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    state["side_calls"] = 1
    try:
        extracted = await ctx.side_text(
            _prompt(ctx.question, original, risk),
            purpose="short_answer_verify",
            max_tokens=120,
        )
    except Exception as e:
        ctx.trace.event("short_answer_verify_error", error=str(e))
        return None

    if not extracted:
        return None

    verdict, reason = _parse_verdict(extracted)
    if verdict == "correct":
        ctx.trace.event(
            "short_answer_verify_accept", draft=original, risk=risk, side=extracted
        )
        return None

    if verdict != "wrong":
        ctx.trace.event(
            "short_answer_verify_ignored",
            reason="unrecognized_verdict",
            risk=risk,
            side=extracted,
        )
        return None

    ctx.trace.event(
        "short_answer_verify_wrong", draft=original, risk=risk, side=extracted
    )

    if state.get("continued", 0) >= 1:
        return None
    state["continued"] = 1
    return {"action": "continue", "feedback": _feedback(original, reason)}

texts.fec3b4068c94cd23b41262837a12bd48ec37ea84:
"""Bounded primary-model self-correction for short-answer QA.

Runs after the deterministic cleaner. It asks the *primary* model for one more
bounded attempt when the cleaned candidate is still unlikely to be the bare
exact-match short answer:

1. Prose-like candidate under an explicit "return only the short answer"
   instruction.
2. Candidate that is not a verbatim n-gram from the supplied context, so it
   cannot be the exact short answer the task expects.
3. Candidate whose normalized phrase has a more frequent space-separated
   context surface (for example "Picture-in-picture" vs "Picture in Picture").

The previous "overexpanded short form" trigger was removed: it repeatedly
asked the model to shorten an already-correct full name/title (for example
"Oliver Brown" -> "Brown" or "Ace Hardware" -> "Ace"), causing exact-match
regressions after a correct first answer.

The primary model remains the only author of the final answer; this hook only
supplies feedback. Each trigger fires at most once per task and the runtime's
remaining-turn and final-continue budgets bound every retry, so this cannot
loop.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_CURRENCY_RE = re.compile(r"\$[0-9][0-9,]*")
_ALPHA_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z'\-]*")
_DOC_SPLIT_RE = re.compile(r"\[DOC\]", re.IGNORECASE)
_LEADING_ARTICLE = {"a", "an", "the"}
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_GLOSS_PUNCT_RE = re.compile(r"[()\[\]{}<>—–,;:]")
_PROSE_LEAD_RE = re.compile(r"^(?:true|false|yes|no|correct|right|indeed)\b", re.I)
_PRODUCE_PLANT_CUE_RE = re.compile(
    r"\b(this|that|these|those)\s+"
    r"(fruit|fruits|vegetable|vegetables|berry|berries|plant|plants|crop|crops)\b",
    re.IGNORECASE,
)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_phrase_keys(question: str) -> set[str]:
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _context_surfaces(question: str) -> dict[str, dict[str, int]]:
    """Return normalized n-gram key -> surface form counts."""
    ctx = _context_text(question)
    surfaces: dict[str, dict[str, int]] = {}
    if not ctx:
        return surfaces

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[tuple[str, str]] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            toks = seq[i : i + n]
                            key = "".join(t[0] for t in toks)
                            phrase = " ".join(t[1] for t in toks)
                            bucket = surfaces.setdefault(key, {})
                            bucket[phrase] = bucket.get(phrase, 0) + 1
                    seq = []
                continue
            seq.append((norm, raw))
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    toks = seq[i : i + n]
                    key = "".join(t[0] for t in toks)
                    phrase = " ".join(t[1] for t in toks)
                    bucket = surfaces.setdefault(key, {})
                    bucket[phrase] = bucket.get(phrase, 0) + 1
    return surfaces


def _passages(question: str) -> list[tuple[list[str], str]]:
    """Split the supplied context into [DOC]-bounded documents.

    Each document is returned as (normalized_tokens, raw_text) so callers can
    check both normalized containment and raw surface details like ``$20``.
    """
    ctx = _context_text(question)
    passages: list[tuple[list[str], str]] = []
    for part in _DOC_SPLIT_RE.split(ctx):
        raw = " ".join(part.split())
        if not raw.strip():
            continue
        tokens = [_norm_token(tok) for tok in raw.split() if _norm_token(tok)]
        if tokens:
            passages.append((tokens, raw))
    return passages


def _currency_amounts(text: str) -> list[str]:
    return sorted(set(_CURRENCY_RE.findall(text or "")))


def _candidate_key(candidate: str) -> str | None:
    """Return the first non-article alphabetic token of the candidate.

    Only the head token is used for document lookup. Using all tokens would
    let a generic trailing word (``Mint``, ``Company``, ``Network``) match the
    question restatement itself and hide the gap we are trying to detect.
    """
    for token in _ALPHA_TOKEN_RE.findall(candidate or ""):
        if token.lower() not in _LEADING_ARTICLE:
            return token
    return None


def _looks_prose(text: str) -> bool:
    text = (text or "").strip()
    if not text:
        return False
    words = text.split()
    if len(words) >= 6:
        return True
    if len(words) >= 3 and (
        _SENTENCE_END_RE.search(text) or _GLOSS_PUNCT_RE.search(text)
    ):
        return True
    if len(words) >= 2 and _PROSE_LEAD_RE.match(text):
        return True
    return False


def _surface_needs_verification(text: str, surfaces: dict[str, dict[str, int]]) -> bool:
    """True when a clean space-separated context surface is clearly more frequent.

    This is deliberately narrow: it only asks the model to re-check a
    hyphenated/single-token candidate when the same normalized phrase has a
    more frequent multi-word, space-separated surface with no surrounding
    punctuation. It never rewrites the answer itself, so legitimate
    hyphenated terms such as "look-alike" are only kept or re-emitted by the
    primary model.
    """
    key = _norm_text(text)
    bucket = surfaces.get(key)
    if not bucket:
        return False

    cand_cf = (text or "").casefold()
    cand_best = 0
    space_best = 0
    for surface, count in bucket.items():
        if surface.casefold() == cand_cf:
            cand_best = max(cand_best, count)
        # A clean space-separated variant: no surrounding punctuation, at
        # least one internal space, and no hyphen.
        if surface == surface.strip(" .,;:!?\"'`") and " " in surface and "-" not in surface:
            space_best = max(space_best, count)
    return space_best > cand_best


def _inflection_variants(key: str) -> set[str]:
    """Return plausible singular/plural inflections of a single-token key.

    This is deliberately narrow (``s``, ``es``, ``y -> ies`` and their
    reverse) so compounds such as ``strawberryland`` are never linked to
    ``strawberry``.
    """
    variants: set[str] = set()
    if not key:
        return variants
    if key.endswith("y") and len(key) > 2:
        variants.add(key[:-1] + "ies")
    variants.add(key + "s")
    variants.add(key + "es")
    if key.endswith("ies") and len(key) > 4:
        variants.add(key[:-3] + "y")
    if key.endswith("es") and len(key) > 3:
        variants.add(key[:-2])
    if key.endswith("s") and not key.endswith("ss") and len(key) > 2:
        variants.add(key[:-1])
    return variants


def _single_token_context_keys(question: str) -> set[str]:
    """Return normalized single-token forms present anywhere in the context."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys
    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                continue
            norm = _norm_token(raw)
            if norm:
                keys.add(norm)
    return keys


def _looks_single_token_inflection_gap(text: str, question: str) -> bool:
    """Detect a one-word produce/plant candidate with a same-stem variant in
    the context (for example ``Strawberry`` when the context also contains
    ``strawberries``). The primary model decides which number is requested."""
    words = text.split()
    if len(words) != 1:
        return False
    if not _PRODUCE_PLANT_CUE_RE.search(_question_line(question)):
        return False
    key = _norm_text(text)
    if not key:
        return False
    variants = _inflection_variants(key)
    for other in _single_token_context_keys(question):
        if other != key and other in variants:
            return True
    return False


def _prose_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\" "
        "Your previous answer was not the bare short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, using the exact surface "
        "form from the supplied context. No lead-in, explanation, parenthetical, "
        "gloss, date, or trailing punctuation."
    )


def _exact_phrase_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer is not a verbatim phrase from the supplied "
        "context, so it cannot be the exact short answer.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the question and the supplied context. Identify the single "
        "requested item and reply with only that item, copied verbatim from "
        "the supplied context. Do not repeat the question's own quoted words "
        "unless the context shows those exact words are the answer. Do not "
        "include any lead-in, explanation, parenthetical, gloss, date, or "
        "extra punctuation. If the question is a definition or category clue "
        "(\"An X that does Y\", \"this type of ...\", \"the term for ...\"), "
        "return the general category or term whose function the context states, "
        "not a specific example that shares only one property. If your previous "
        "answer was the right entity but the wrong singular/plural or surface "
        "form, fix only that form and keep the entity."
    )


def _surface_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your previous answer may not use the exact spacing and hyphenation "
        "of the supplied context.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and copy the requested phrase exactly "
        "as it appears there, preserving spaces, hyphens, capitalization, and "
        "punctuation. Return only the corrected phrase."
    )


def _single_token_feedback(draft: str) -> str:
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "Your one-word answer may be the right entity but the wrong number or "
        "surface form.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find how the requested item is written "
        "there (singular or plural, exact spelling and capitalization). For a "
        "fruit/vegetable/berry/plant clue, return the noun form the context uses "
        "for the food itself, not the attributive form used in festival or brand "
        "names. Return only that exact form."
    )


def _missing_currency_feedback(amounts: list[str], draft: str) -> str:
    joined = ", ".join(amounts)
    return (
        "The instruction says: \"Return only the short answer.\"\n"
        "A constraint check found that the question explicitly mentions the "
        f"amount(s) {joined}, but the document supporting your previous answer "
        "does not state that amount.\n"
        "Previous answer:\n"
        + draft
        + "\n\n"
        "Re-read the supplied context and find the entity whose own document "
        f"states the amount(s) {joined} and satisfies every other clue. "
        "Discard candidates that match only a keyword but not the amount. "
        "Return only that entity's short name, using the exact surface form "
        "from the supplied context. No explanation or extra formatting."
    )


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_retry", {})
    if state.get("fired", 0) >= 5:
        return None
    if getattr(ctx, "remaining_turns", 0) <= 0:
        return None
    if getattr(ctx, "_final_continues", 0) >= getattr(ctx, "_final_continue_max", 3):
        return None

    # Trigger 0: currency-amount constraint gap. Runs before the general
    # format/non-context triggers so a wrong keyword-only candidate gets the
    # more specific amount feedback instead.
    if state.get("currency_fired", 0) < 1:
        amounts = _currency_amounts(_question_line(ctx.question))
        if amounts:
            passages = _passages(ctx.question)
            key = _candidate_key(original)
            if passages and key:
                key_norm = _norm_text(key)
                candidate_docs: list[str] = []
                for _, raw in passages:
                    if key_norm in _norm_text(raw):
                        candidate_docs.append(raw)
                if candidate_docs:
                    context_raw = _context_text(ctx.question)
                    missing = [
                        amount
                        for amount in amounts
                        if amount in context_raw
                        and all(amount not in raw for raw in candidate_docs)
                    ]
                    if missing:
                        state["currency_fired"] = 1
                        state["fired"] = state.get("fired", 0) + 1
                        ctx.trace.event(
                            "short_answer_retry_currency_gap",
                            candidate=original,
                            missing_amounts=missing,
                        )
                        return {
                            "action": "continue",
                            "feedback": _missing_currency_feedback(missing, original),
                        }

    # Trigger 1: prose-like candidate under an explicit short-answer request.
    if state.get("prose_fired", 0) < 1 and _looks_prose(original):
        state["prose_fired"] = 1
        state["fired"] = state.get("fired", 0) + 1
        ctx.trace.event("short_answer_retry_prose", candidate=original)
        return {"action": "continue", "feedback": _prose_feedback(original)}

    # Trigger 2: candidate is not a verbatim phrase from the supplied context.
    if state.get("non_context_fired", 0) < 1:
        context_keys = _context_phrase_keys(ctx.question)
        if _norm_text(original) not in context_keys:
            state["non_context_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_non_context", candidate=original)
            return {
                "action": "continue",
                "feedback": _exact_phrase_feedback(original),
            }

    # Trigger 4: hyphen/space surface ambiguity for the same phrase.
    if state.get("surface_fired", 0) < 1:
        surfaces = _context_surfaces(ctx.question)
        if _surface_needs_verification(original, surfaces):
            state["surface_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_surface", candidate=original)
            return {"action": "continue", "feedback": _surface_feedback(original)}

    # Trigger 5: one-word produce/plant candidate with a same-stem context
    # variant (usually singular vs plural). Ask the primary model to copy the
    # exact context form rather than rewriting the answer deterministically.
    if state.get("single_form_fired", 0) < 1:
        if _looks_single_token_inflection_gap(original, ctx.question):
            state["single_form_fired"] = 1
            state["fired"] = state.get("fired", 0) + 1
            ctx.trace.event("short_answer_retry_single_form", candidate=original)
            return {"action": "continue", "feedback": _single_token_feedback(original)}

    return None

texts.ffd58e751a364914194b628ccf0d17a91e337a51:
"""Deterministic short-answer surface cleaner.

This hook runs only when the user explicitly requested a bare short answer
(``return only the short answer``). It removes generic surface wrappers that
break exact-match scoring and, for a few clue shapes, extracts the requested
minimal form. It never calls a model and never changes the chosen entity.

Covered operations (all reversible, lexical only):
  * code fences and matched surrounding quotes
  * "answer is / answer:" lead-ins
  * trailing sentence periods (initialisms are preserved)
  * trailing parenthetical/bracket glosses and short dash glosses
  * leading articles when the article-less form is a supplied context phrase
  * bare role/title and pair/list head extraction ("... of/from X")
  * produce/plant plural restoration ("Strawberry" -> "strawberries")
  * organization-of-these member-noun extraction
    (e.g. "Chinese hand shops (the Chinese Hand Shops Alliance)" -> "shops")
  * hyphenated acronym expansion ("Picture-in-picture" -> "Picture in Picture")
  * repeated title punctuation on pair/list clues ("What's Happening!!")
  * Jeopardy-style person-name shortening ("Jean Genet" -> "Genet")
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_TRAILING_PAREN_RE = re.compile(r"\s*\([^()]*\)\s*$")
_TRAILING_BRACKET_RE = re.compile(r"\s*\[[^\[\]]*\]\s*$")
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–-]\s+(?P<gloss>.+)$", re.DOTALL)
_DEF_DEMO_RE = re.compile(
    r"\b(this|these|that|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"his|her|he|she|him|whose)\b",
    re.IGNORECASE,
)
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_ARTICLE_LEAD_RE = re.compile(r"^(?:a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)

_ORG_OF_THESE_RE = re.compile(
    r"\b(?:alliance|association|union|league|organization|organisation|society|group)"
    r"\s+of\s+these\s+(?P<qualifier>[A-Za-z]+(?:\s+[A-Za-z]+){0,3})\s+"
    r"(?P<kind>businesses|firms|stores|shops|companies|teams|clubs|nations?|"
    r"countries|states?|cities?|towns?)\b",
    re.IGNORECASE,
)

_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(
    r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE
)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    return "".join(ch for ch in tok.lower() if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in (text or "").split() if _norm_token(t))


def _segments(ctx: str) -> list[str]:
    return [p.strip() for p in _MARKER_RE.split(ctx) if p.strip()]


def _context_phrases(question: str) -> tuple[dict[str, list[str]], dict[str, int]]:
    """Map normalized word n-grams back to original context surface forms."""
    ctx = _context_text(question)
    phrases: dict[str, list[str]] = {}
    counts: dict[str, int] = {}
    if not ctx:
        return phrases, counts

    for seg in _segments(ctx):
        toks: list[tuple[str, str]] = []
        for raw in seg.split():
            norm = _norm_token(raw)
            if norm:
                toks.append((norm, raw))
        max_n = min(5, len(toks))
        for n in range(1, max_n + 1):
            for i in range(len(toks) - n + 1):
                key = "".join(t[0] for t in toks[i : i + n])
                phrase = " ".join(t[1] for t in toks[i : i + n])
                counts[phrase] = counts.get(phrase, 0) + 1
                bucket = phrases.setdefault(key, [])
                if phrase not in bucket:
                    bucket.append(phrase)
    return phrases, counts


def _best_phrase(bucket: list[str], counts: dict[str, int]) -> str:
    """Pick the dominant context surface form for a normalized key.

    Trailing sentence punctuation is penalized so ``Sirius Satellite Radio,``
    is not chosen over the cleaner ``Sirius Satellite Radio`` form.
    """
    if not bucket:
        return ""

    def quality(p: str) -> tuple:
        stripped = p.strip()
        trailing = len(stripped) - len(stripped.rstrip(" .,;:!?"))
        return (
            counts.get(p, 0),
            1 if stripped.count(" ") > 0 else 0,
            -p.count("-"),
            -trailing,
            len(stripped),
        )

    return max(bucket, key=quality)


def _strip_code_fences(text: str) -> str:
    text = (text or "").strip()
    if text.startswith("```") and text.endswith("```") and len(text) > 6:
        inner = text[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            text = inner
    return text.strip()


def _strip_outer_quotes(text: str) -> str:
    text = (text or "").strip()
    for quote in ('"', "'", "`"):
        if (
            len(text) >= 2
            and text.startswith(quote)
            and text.endswith(quote)
        ):
            inner = text[1:-1].strip()
            if inner:
                text = inner
                break
    return text.strip()


def _strip_lead_in(text: str) -> str:
    return _LEAD_IN_RE.sub("", (text or "").strip()).strip()


def _strip_leading_article(text: str) -> str:
    """Return the article-less form without changing any other token."""
    match = _ARTICLE_LEAD_RE.match((text or "").strip())
    return match.group("rest").strip() if match else (text or "").strip()


def _resolved_context_form(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str | None:
    """Return the context's surface form for ``text`` if one exists.

    Also accepts the article-less form of ``text``, so a draft like ``A well``
    can resolve to the context's ``well`` when ``A well`` is not itself a
    supplied phrase. Surrounding punctuation is removed from the returned
    context phrase so wrappers such as ``(SiriusXM)`` never leave a comma
    behind.
    """
    key = _norm_text(text)
    if key and key in phrases:
        bucket = phrases[key]
        stripped = (text or "").strip().strip(" .,;:!?\"'`")
        for phrase in bucket:
            if phrase.strip(" .,;:!?\"'`") == stripped:
                return stripped
        return _best_phrase(bucket, counts).strip(" .,;:!?\"'`")
    bare = _strip_leading_article(text)
    if bare and bare != text:
        key = _norm_text(bare)
        if key and key in phrases:
            return _best_phrase(phrases[key], counts).strip(" .,;:!?\"'`")
    return None


def _strip_trailing_period(text: str, phrases: dict[str, list[str]]) -> str:
    """Drop one sentence-final period, preserving abbreviations/initialisms."""
    cur = (text or "").strip()
    if not (cur.endswith(".") and not cur.endswith("..") and len(cur) > 1):
        return cur

    # Initialisms and common abbreviations keep their final period.
    if re.search(r"\b[A-Za-z](\.[A-Za-z])+\.?$", cur):
        return cur
    if re.match(r"^[A-Za-z]\.$", cur):
        return cur
    if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", cur, re.IGNORECASE):
        return cur

    nxt = cur[:-1].rstrip()
    if not nxt:
        return cur

    # Strip when the character before the period is lowercase, a closing
    # bracket/paren/quote, or when the period-less text is a context phrase.
    # This catches both "Massachusetts." and "A well (a water well).".
    if (
        cur[-2].islower()
        or cur[-2] in ")]}\"'`"
        or _norm_text(nxt) in phrases
    ):
        return nxt
    return cur


def _strip_trailing_glosses(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str:
    cur = (text or "").strip()
    for _ in range(5):
        prev = cur

        nxt = _TRAILING_PAREN_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            resolved = _resolved_context_form(nxt, phrases, counts)
            if resolved:
                cur = resolved
                continue

        nxt = _TRAILING_BRACKET_RE.sub("", cur).strip()
        if nxt and nxt != cur:
            resolved = _resolved_context_form(nxt, phrases, counts)
            if resolved:
                cur = resolved
                continue

        match = _DASH_GLOSS_RE.search(cur)
        if match:
            before = cur[: match.start()].strip()
            gloss = match.group("gloss").strip()
            resolved = _resolved_context_form(before, phrases, counts)
            if (
                before
                and gloss
                and len(gloss.split()) <= 8
                and resolved
            ):
                cur = resolved
                continue
        break
    return cur


def _capitalized_words(text: str) -> list[str]:
    return re.findall(r"[A-Za-z][A-Za-z'\-]*", text or "")


def _is_role_title_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," in q:
        return False
    toks = _capitalized_words(q)
    if not (2 <= len(toks) <= 6):
        return False
    return all(t[:1].isupper() for t in toks)


def _is_pair_list_clue(q: str) -> bool:
    if not q or _DEF_DEMO_RE.search(q) or "," not in q:
        return False
    parts = [p.strip() for p in q.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        toks = _capitalized_words(part)
        if not (1 <= len(toks) <= 5):
            return False
        if not all(t[:1].isupper() for t in toks):
            return False
    return True


def _echo_context_form(
    text: str, phrases: dict[str, list[str]], counts: dict[str, int]
) -> str:
    key = _norm_text(text)
    if key and key in phrases:
        return _best_phrase(phrases[key], counts)
    return text


def _extract_head(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    """Extract a single proper-noun head after ``of``/``from`` for bare
    role/title and pair/list clues. Longer proper-name runs are left intact."""
    q = _question_line(question)
    if not (_is_role_title_clue(q) or _is_pair_list_clue(q)):
        return text
    match = re.search(
        r"\b(?:of|from)\s+(?:(?:the|a|an)\s+)?([A-Z][A-Za-z'.\-]*)", text
    )
    if not match:
        return text
    head = match.group(1)
    rest = text[match.end() :].strip()
    next_token = rest.split()[0] if rest else ""
    if next_token and next_token[0].isupper():
        return text
    return _echo_context_form(head, phrases, counts)


def _plural_forms(word: str) -> list[str]:
    if not word:
        return []
    forms: list[str] = []
    if (
        len(word) > 1
        and word[-1].lower() == "y"
        and word[-2].lower() not in "aeiou"
    ):
        forms.append(word[:-1] + "ies")
    forms.append(word + "s")
    return forms


def _prefer_produce_plural(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if len(text.split()) != 1:
        return text
    if not _PRODUCE_RE.search(_question_line(question)):
        return text
    word = text.strip().strip(" .,;:!?\"'`")
    if not word or not word[:1].isupper():
        return text
    for form in _plural_forms(word):
        key = _norm_text(form)
        if key and key in phrases:
            return _best_phrase(phrases[key], counts)
    return text


def _fix_hyphenated_acronym(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if "-" not in text:
        return text
    acronyms = re.findall(r"\b[A-Z]{2,6}\b", _question_line(question))
    if not acronyms:
        return text
    key = _norm_text(text)
    if key not in phrases:
        return text
    words = text.replace("-", " ").split()
    if len(words) < 2:
        return text
    initials = "".join(w[0] for w in words).lower()
    for acr in acronyms:
        if acr.lower() != initials:
            continue
        candidates = [
            p
            for p in phrases[key]
            if "-" not in p and len(p.split()) == len(words)
        ]
        if not candidates:
            continue
        best = _best_phrase(candidates, counts)
        if best and best != text:
            return best
    return text


def _strip_title_bangs(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    if not _is_pair_list_clue(_question_line(question)):
        return text
    if not re.search(r"[!?]{2,}$", (text or "").strip()):
        return text
    key = _norm_text(text)
    if key not in phrases:
        return text
    candidates = [p for p in phrases[key] if not re.search(r"[!?]{1,}$", p.strip())]
    if not candidates:
        return text
    return _best_phrase(candidates, counts)


def _shorten_person_name(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    """Shorten a full name to the surname/target for a Jeopardy-style person
    clue when the surname appears alone in the supplied context.

    Factual statements (``he/his/her ...``) are excluded because they usually
    want the full name exactly as the context introduces it.
    """
    q = _question_line(question).lower()
    if _PERSON_PRONOUN_RE.search(q):
        return text
    if not _PERSON_DEMO_RE.search(q):
        return text
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return text

    words = text.split()
    if len(words) not in (2, 3):
        return text
    if not all(_NAME_TOKEN_RE.match(w) for w in words):
        return text

    surname = words[-1]
    key = _norm_text(surname)
    if key and key in phrases:
        return _best_phrase(phrases[key], counts)
    return text


def _looks_plural_common(word: str, kind: str | None) -> bool:
    """True for a lowercase common-noun plural that is not the clue's generic
    category word (``businesses`` etc.)."""
    if not word or len(word) < 4:
        return False
    if not word[:1].islower():
        return False
    if not word.endswith("s") or word.endswith("ss"):
        return False
    if kind and word.lower() == kind.lower():
        return False
    return True


def _extract_org_member_noun(
    text: str,
    question: str,
    phrases: dict[str, list[str]],
    counts: dict[str, int],
) -> str:
    """Extract the plural member noun for ``alliance/organization of these ...``
    clues.

    Example: ``Chinese hand shops (the Chinese Hand Shops Alliance)`` is
    shortened to ``shops`` when the question asks for the businesses that
    formed the alliance and the context supplies that plural noun. The rule is
    deliberately narrow and only fires when the shorter noun is a supplied
    context phrase.
    """
    q = _question_line(question)
    match = _ORG_OF_THESE_RE.search(q)
    if not match:
        return text

    words = re.findall(r"[A-Za-z]+(?:-[A-Za-z]+)*", text or "")
    best: str | None = None
    best_score: tuple = (-1,)

    for word in words:
        if not _looks_plural_common(word, match.group("kind")):
            continue
        key = _norm_token(word)
        bucket = phrases.get(key)
        if not bucket:
            continue
        surface = _best_phrase(bucket, counts).strip(" .,;:!?\"'`").strip()
        if not surface:
            continue
        score = (
            1 if surface[:1].islower() else 0,
            1 if surface == word else 0,
            counts.get(surface, 0),
            -len(surface),
        )
        if score > best_score:
            best_score = score
            best = surface

    return best if best else text


def _clean(text: str, question: str) -> str:
    phrases, counts = _context_phrases(question)

    t = _strip_code_fences(text)
    t = _strip_outer_quotes(t)
    t = _strip_lead_in(t)

    # Strip a sentence-final period before gloss removal so patterns such as
    # "A well (a water well)." can be unwrapped one layer at a time.
    t = _strip_trailing_period(t, phrases)
    t = _strip_trailing_glosses(t, phrases, counts)

    q = _question_line(question)
    if _is_role_title_clue(q) or _is_pair_list_clue(q):
        t = _extract_head(t, question, phrases, counts)

    t = _prefer_produce_plural(t, question, phrases, counts)
    t = _extract_org_member_noun(t, question, phrases, counts)
    t = _fix_hyphenated_acronym(t, question, phrases, counts)
    t = _strip_title_bangs(t, question, phrases, counts)
    t = _shorten_person_name(t, question, phrases, counts)

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean the final short answer into its bare canonical form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        return {"action": "replace", "answer": cleaned}
    return None

texts.ffe21979e88c75c9b5673af74bf71d97efbdd154:
"""Deterministic surface-only final-answer cleaner for short-answer QA.

This hook runs only when the user request contains the explicit short-answer
instruction (``return only the short answer``). It never calls a model and
never changes which entity or term the model selected: it removes generic
surface wrappers around an answer candidate and re-echoes the supplied
context's dominant surface form for the same normalized token sequence.

Removals are deliberately generic and reversible:

  * surrounding code fences / matched quotes
  * ``Answer is:`` / ``The answer is`` lead-ins
  * discourse lead-ins such as ``True -- ...``
  * a trailing sentence period (abbreviations and initialisms are preserved)
  * trailing parenthetical/bracket glosses
  * trailing em/en-dash glosses whose head is supported by the context
  * decorative trailing ``!``/``?`` marks when the base is context-supported
  * a leading article when the article-less form is context-supported
  * canonical surface echo: case, spacing, and hyphenation are copied from the
    most frequent supplied-context variant of the same normalized phrase

After the surface cleanup above, a conservative minimal-form pass trims only
the shortest context-supported form for question types that conventionally ask
for it (nickname/short name, Jeopardy-style person surname, produce plural,
definition term head, ``of these/those`` demonstrative head, and bare
role/pair clues). Every replacement in that pass is a verbatim n-gram from the
supplied context, so it never invents an answer and never substitutes a
different entity.
"""

from __future__ import annotations

import re
from typing import Any

_MARKER_RE = re.compile(r"\[(?:DOC|TLE|PAR)\]")
_CODE_FENCE_RE = re.compile(r"^```[A-Za-z]*\s*\n(.*?)\n?```$", re.DOTALL)
_LEAD_IN_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DISCOURSE_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:-]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_TRAIL_PAREN_RE = re.compile(r"\s*\([^()]{1,160}\)\s*$")
_TRAIL_BRACKET_RE = re.compile(r"\s*\[[^\[\]]{1,160}\]\s*$")
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s*(?P<gloss>.+)$", re.DOTALL)
_TRAIL_PERIOD_RE = re.compile(r"\.$")
_TRAIL_BANG_RE = re.compile(r"[!?]+$")
_ARTICLE_RE = re.compile(r"^(a|an|the)\s+(?P<rest>.+)$", re.IGNORECASE)

_ABBREV_RE = re.compile(
    r"(?:\b[A-Za-z]\.){2,}$|\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", re.IGNORECASE
)

# ---------------------------------------------------------------------------
# Minimal-form extraction constants
# ---------------------------------------------------------------------------

_SHORT_FORM_MARKERS = (
    "nickname",
    "nicknamed",
    "known as",
    "referred to as",
    "called it",
    "term for",
    "surname",
    "acronym",
    "pre-",
    "company",
    "network",
    "mint",
    "radio",
    "association",
    "organization",
    "organisation",
    "league",
)
_CATEGORY_SUFFIXES = {
    "party",
    "company",
    "network",
    "radio",
    "mint",
    "association",
    "organization",
    "organisation",
    "league",
    "corporation",
    "corp",
    "inc",
    "ltd",
    "system",
    "satellite",
}
_PRODUCE_RE = re.compile(
    r"\b(this|these|that|those)\s+(fruit|fruits|vegetable|vegetables|berry|berries|"
    r"plant|plants|crop|crops)\b",
    re.IGNORECASE,
)
_PERSON_DEMO_RE = re.compile(r"\b(this|that|these|those|whose|who)\b", re.IGNORECASE)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|she|his|her|him)\b", re.IGNORECASE)
_PERSON_ROLE_WORDS = (
    "thief",
    "artist",
    "novelist",
    "playwright",
    "actor",
    "actress",
    "boxer",
    "author",
    "poet",
    "senator",
    "sultan",
    "president",
    "golfer",
    "writer",
    "painter",
    "singer",
    "director",
    "composer",
)
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Ý][A-Za-zÀ-ÿ'\-]+$")
_ROLE_TITLE_WORDS = (
    "president",
    "sultan",
    "king",
    "queen",
    "emperor",
    "mayor",
    "governor",
    "senator",
    "chancellor",
    "secretary",
)
_OF_FROM_BLOCKLIST = {
    "state",
    "office",
    "department",
    "ministry",
    "government",
    "republic",
    "kingdom",
    "party",
    "house",
    "senate",
    "congress",
    "parliament",
}
_QUESTION_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how|"
    r"he|she|his|her|him)\b",
    re.IGNORECASE,
)
_OF_THESE_RE = re.compile(r"\bof\s+(?:these|those)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _chunk_key(text: str) -> str:
    """Casefold and collapse every non-alphanumeric run to a single space."""
    s = (text or "").casefold()
    s = re.sub(r"[^\w]+", " ", s, flags=re.UNICODE)
    s = re.sub(r"_+", " ", s)
    return " ".join(s.split())


def _strip_surrounding(text: str) -> str:
    return (text or "").strip(" \t\r\n.,;:!?\"'`")


def _surface_map(question: str) -> dict[str, list[tuple[str, int]]]:
    """Map normalized n-gram keys to (surface, count) variants from context."""
    ctx = _context_text(question)
    surfaces: dict[str, list[tuple[str, int]]] = {}
    if not ctx:
        return surfaces

    for segment in _MARKER_RE.split(ctx):
        segment = segment.strip()
        if not segment:
            continue
        tokens = segment.split()
        max_n = min(6, len(tokens))
        for n in range(1, max_n + 1):
            for i in range(len(tokens) - n + 1):
                phrase = " ".join(tokens[i : i + n])
                key = _chunk_key(phrase)
                if not key:
                    continue
                bucket = surfaces.setdefault(key, [])
                if all(surface != phrase for surface, _ in bucket):
                    bucket.append((phrase, 0))

    ctx_lower = ctx.lower()
    for key, bucket in surfaces.items():
        for idx, (surface, _) in enumerate(bucket):
            bucket[idx] = (surface, ctx_lower.count(surface.lower()))
    return surfaces


def _surface_quality(item: tuple[str, int], candidate: str) -> tuple:
    surface, count = item
    stripped = _strip_surrounding(surface)
    return (
        count,
        1 if surface.casefold() == candidate.casefold() else 0,
        1 if stripped[:1].isupper() else 0,
        1 if not stripped.isupper() else 0,
        -stripped.count("-"),
        -len(stripped),
    )


def _best_surface(bucket: list[tuple[str, int]], candidate: str) -> str:
    if not bucket:
        return candidate
    best = max(bucket, key=lambda item: _surface_quality(item, candidate))
    return _strip_surrounding(best[0])


def _has_key(text: str, surfaces: dict) -> bool:
    key = _chunk_key(text)
    return bool(key) and key in surfaces


def _strip_code_fence(text: str) -> str:
    match = _CODE_FENCE_RE.match(text.strip())
    if match:
        return match.group(1).strip()
    return text


def _strip_surrounding_quotes(text: str) -> str:
    t = text.strip()
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                return inner
    return t


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_RE.match(text.strip())
    if match and match.group("tail").strip():
        return match.group("tail").strip()
    return text


def _strip_answer_lead(text: str) -> str:
    return _LEAD_IN_RE.sub("", text.strip()).strip()


def _strip_trailing_parentheticals(text: str) -> str:
    cur = text.strip()
    for _ in range(8):
        prev = cur
        for pattern in (_TRAIL_PAREN_RE, _TRAIL_BRACKET_RE):
            match = pattern.search(cur)
            if match:
                nxt = cur[: match.start()].strip()
                if nxt and nxt != cur:
                    cur = nxt
                    break
        if cur == prev:
            break
    return cur


def _strip_trailing_dash_gloss(text: str, surfaces: dict) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _has_key(before, surfaces):
        return before
    return text


def _strip_trailing_period(text: str, surfaces: dict) -> str:
    cur = text.strip()
    for _ in range(4):
        if not cur.endswith(".") or cur.endswith(".."):
            break
        if _ABBREV_RE.search(cur):
            break
        nxt = cur[:-1].rstrip()
        if not nxt:
            break
        if cur[-2].islower() or cur[-2] in ")]}\"'" or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_trailing_bang(text: str, surfaces: dict) -> str:
    """Strip decorative trailing !/? when the base is context-supported or the
    mark is doubled. Repeated marks are surface decoration, not an entity."""
    cur = text.strip()
    for _ in range(4):
        match = _TRAIL_BANG_RE.search(cur)
        if not match:
            break
        run = match.group(0)
        nxt = cur[: match.start()].rstrip()
        if not nxt:
            break
        if len(run) >= 2 or _has_key(nxt, surfaces):
            cur = nxt
            continue
        break
    return cur


def _strip_leading_article(text: str, surfaces: dict) -> str:
    match = _ARTICLE_RE.match(text.strip())
    if not match:
        return text.strip()
    rest = match.group("rest").strip()
    if not rest:
        return text.strip()
    if _has_key(rest, surfaces) or rest[0].isupper() or rest[0].isdigit():
        return rest
    return text.strip()


def _echo_context_form(text: str, surfaces: dict, original: str) -> str:
    key = _chunk_key(text)
    if not key or key not in surfaces:
        return text
    return _best_surface(surfaces[key], original)


# ---------------------------------------------------------------------------
# Minimal-form extraction
# ---------------------------------------------------------------------------


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return question


def _word_in_question(word: str, question_line: str) -> bool:
    w = re.sub(r"[^A-Za-z0-9]", "", word.casefold())
    if not w:
        return False
    return w in set(re.findall(r"[A-Za-z0-9]+", question_line.casefold()))


def _has_short_form_cue(question_line: str) -> bool:
    q = question_line.lower()
    if any(marker in q for marker in _SHORT_FORM_MARKERS):
        return True
    return bool(
        re.search(
            r"\bthis\s+(?:\w+\s+)?(?:company|network|mint|radio|association|"
            r"organization|organisation|league)\b",
            q,
        )
    )


def _drop_trailing_descriptors(text: str, question_line: str, surfaces: dict) -> str:
    """Drop trailing category words or question descriptors when a shorter
    context-supported prefix remains. Used for nickname/short-name clues
    where a trailing category noun should be removed."""
    if not _has_short_form_cue(question_line):
        return text
    if re.search(r"[()\[\]]", text):
        return text
    words = text.split()
    if len(words) < 2:
        return text

    cur = text
    for end in range(len(words) - 1, 0, -1):
        prefix = " ".join(words[:end])
        dropped = words[end]
        drop_word = re.sub(r"[^A-Za-z0-9]", "", dropped.casefold())
        if drop_word in _CATEGORY_SUFFIXES or _word_in_question(dropped, question_line):
            if _has_key(prefix, surfaces):
                cur = prefix
                continue
            break
        break
    return cur


def _person_surname(text: str, question_line: str, surfaces: dict) -> str:
    """For Jeopardy-style ``this ...`` / ``whose ...`` person clues, keep only
    the surname/target name when the supplied context also provides that
    surname alone. Factual ``he/she/his/her`` statements are excluded because
    those usually want the person's name exactly as the context introduces it."""
    q = question_line.lower()
    if _PERSON_PRONOUN_RE.search(q):
        return text
    if not _PERSON_DEMO_RE.search(q):
        return text
    if not any(role in q for role in _PERSON_ROLE_WORDS):
        return text

    words = text.split()
    if len(words) not in (2, 3, 4):
        return text
    if not all(_NAME_TOKEN_RE.match(word) for word in words):
        return text

    surname = words[-1]
    if _has_key(surname, surfaces):
        return _best_surface(surfaces[_chunk_key(surname)], surname)
    return text




def _factual_person_lead_name(text: str, question_line: str, surfaces: dict) -> str:
    """For factual person statements (he/she/his/her without a Jeopardy-style
    demonstrative), a prose answer usually starts with the person's full name
    followed by a lowercase verb. Extract that leading context-supported proper
    name so the final answer is the bare name rather than a full sentence.

    This only fires when the leading token is a capitalized word and the
    question is a factual ``he/his/her`` clue, so role/pair/definition clues and
    Jeopardy-style ``this ...`` person clues are never touched by this rule.
    """
    q = question_line.lower()
    if not _PERSON_PRONOUN_RE.search(q):
        return text
    if _PERSON_DEMO_RE.search(q):
        return text

    words = text.split()
    if len(words) < 3:
        return text
    if not words[0] or not words[0][:1].isupper():
        return text

    leading_stop = {
        "the", "a", "an", "this", "that", "these", "those",
        "he", "she", "his", "her", "him", "it",
    }
    if words[0].casefold() in leading_stop:
        return text

    # Take the maximal leading run of capitalized tokens. In a prose answer
    # this is the name phrase before the verb (e.g. ``Thomas Hardy`` in
    # ``Thomas Hardy published ...``).
    run: list[str] = []
    for word in words:
        if word and word[:1].isupper():
            run.append(word)
        else:
            break
    if not run:
        return text

    # Prefer the longest leading run (up to four tokens) that is a verbatim
    # context phrase. If the whole draft is already that name, leave it alone.
    for n in range(min(4, len(run)), 0, -1):
        phrase = " ".join(run[:n])
        key = _chunk_key(phrase)
        if not key or key not in surfaces:
            continue
        if _chunk_key(phrase) == _chunk_key(text):
            return text
        return _best_surface(surfaces[key], phrase)
    return text

def _plural_candidates(word: str) -> list[str]:
    base = word.strip()
    if not base:
        return []
    candidates: list[str] = []
    if re.search(r"[^aeiou]y$", base, re.IGNORECASE):
        candidates.append(base[:-1] + "ies")
    if re.search(r"(s|x|z|ch|sh)$", base, re.IGNORECASE):
        candidates.append(base + "es")
    candidates.append(base + "s")
    return candidates


def _prefer_plural_produce_form(text: str, question_line: str, surfaces: dict) -> str:
    """Restore the context's plural produce form for ``this fruit/vegetable/
    berry/plant`` clues."""
    if len(text.split()) != 1:
        return text
    if not _PRODUCE_RE.search(question_line):
        return text

    word = text.strip()
    for candidate in _plural_candidates(word):
        if _has_key(candidate, surfaces):
            return _best_surface(surfaces[_chunk_key(candidate)], candidate)
    return text


def _is_pair_list_clue(question_line: str) -> bool:
    """Bare pair/list clues such as ``A,B`` or ``A,B,C`` with no other
    predicate."""
    if "," not in question_line:
        return False
    if _QUESTION_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 6):
        return False
    for part in parts:
        tokens = [t for t in re.findall(r'"[^"]+"|[A-Za-z][A-Za-z\'\-]*', part) if t]
        if not tokens:
            return False
        if not all(t[:1].isupper() or t.startswith('"') for t in tokens):
            return False
    return True


def _is_role_title_clue(question_line: str) -> bool:
    """Bare role/title clues such as ``President X`` or ``Sultan X``. The
    requested short answer is the associated place/office label, not a
    sentence about the role."""
    if "," in question_line:
        return False
    if _QUESTION_DEMO_RE.search(question_line):
        return False
    q = question_line.lower()
    if not any(word in q for word in _ROLE_TITLE_WORDS):
        return False
    return len(question_line.split()) <= 8


def _extract_of_from_head(text: str, surfaces: dict) -> str:
    """Extract a capitalized place/office head after ``of``/``from`` in a
    verbose draft, but only when that head is supplied verbatim by the
    context and is not a generic title/office word."""
    match = re.search(
        r"\b(?:of|from)\s+([A-Z][A-Za-z]+(?:[ \t]+[A-Z][A-Za-z]+){0,2})",
        text,
    )
    if not match:
        return text
    candidate = _strip_surrounding(match.group(1))
    if not candidate:
        return text
    if candidate.casefold() in _OF_FROM_BLOCKLIST:
        return text
    if _has_key(candidate, surfaces):
        return _best_surface(surfaces[_chunk_key(candidate)], candidate)
    return text


def _definition_term_head(text: str, question_line: str, surfaces: dict) -> str:
    """For ``term for`` clues, keep the head term before ``of X`` when the
    head is context-supported and the tail is either a proper noun or is
    already named in the question."""
    if "term for" not in question_line.lower():
        return text
    match = re.match(r"^(.+?)\s+of\s+(.+)$", text)
    if not match:
        return text
    head = match.group(1).strip()
    tail = match.group(2).strip()
    if not _has_key(head, surfaces):
        return text

    tail_words = re.findall(r"[A-Za-z0-9]+", tail)
    tail_in_question = bool(tail_words) and all(
        _word_in_question(word, question_line) for word in tail_words
    )
    if tail_in_question or (tail[:1].isupper() if tail else False):
        return _best_surface(surfaces[_chunk_key(head)], head)
    return text


def _extract_demonstrative_of_head(text: str, question_line: str, surfaces: dict) -> str:
    """For ``of these/those ...`` clues, drop leading modifiers from a draft
    that is not itself a context phrase and keep the shortest context-supported
    suffix. This recovers the head noun (e.g. ``laundries``) from an
    overqualified phrase such as ``Chinese hand laundries``."""
    if not _OF_THESE_RE.search(question_line):
        return text
    words = text.split()
    if len(words) < 2:
        return text
    if _has_key(text, surfaces):
        return text

    for n in range(1, min(4, len(words))):
        suffix = " ".join(words[-n:])
        if suffix != text and _has_key(suffix, surfaces):
            return _best_surface(surfaces[_chunk_key(suffix)], suffix)
    return text


def _minimal_form(text: str, question: str, surfaces: dict) -> str:
    """Return the shortest context-supported form for question types that
    conventionally ask for one. Each rewrite is a verbatim context n-gram."""
    question_line = _question_line(question)
    cur = text

    cur = _drop_trailing_descriptors(cur, question_line, surfaces)
    cur = _person_surname(cur, question_line, surfaces)
    cur = _factual_person_lead_name(cur, question_line, surfaces)
    cur = _prefer_plural_produce_form(cur, question_line, surfaces)
    cur = _definition_term_head(cur, question_line, surfaces)
    cur = _extract_demonstrative_of_head(cur, question_line, surfaces)

    if _is_pair_list_clue(question_line) or _is_role_title_clue(question_line):
        cur = _extract_of_from_head(cur, surfaces)

    return cur


def _clean(original: str, question: str) -> str:
    surfaces = _surface_map(question)

    text = original.strip()
    text = _strip_code_fence(text)
    text = _strip_surrounding_quotes(text)
    text = _strip_discourse_lead(text)
    text = _strip_answer_lead(text)
    text = _strip_trailing_dash_gloss(text, surfaces)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_parentheticals(text)
    text = _strip_trailing_period(text, surfaces)
    text = _strip_trailing_bang(text, surfaces)
    text = _strip_leading_article(text, surfaces)

    # Canonicalize spacing/case/hyphenation from the supplied context.
    text = _echo_context_form(text, surfaces, original)

    # Echo may re-introduce decorative title punctuation; strip it one final
    # time without re-echoing so we do not undo the punctuation cleanup.
    text = _strip_trailing_bang(text, surfaces)

    # Now that the candidate is wrapper-free, select the minimal context form
    # only for question types that ask for a short/nickname/surname/term.
    text = _minimal_form(text, question, surfaces)
    text = _strip_trailing_bang(text, surfaces)

    return " ".join(text.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None
    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None

texts.ffffdd0c07380c806cdb40c48b49849e94e99f5e:
"""Conservative deterministic short-answer surface cleaner.

Runs only when the task explicitly says to return only the short answer.
It performs lexical-only, context-gated normalization:

  * strip code fences and one matched pair of surrounding quotes
  * strip "answer is / answer:" lead-ins
  * strip True/False/Yes/No discourse lead-ins ("True — ...")
  * strip a trailing sentence period or repeated !/? only when the remaining
    phrase is supported verbatim by the supplied context
  * strip trailing parenthetical/bracket glosses only when the remaining
    phrase is a verbatim context phrase
  * strip trailing em/en-dash glosses only when the remaining phrase is a
    verbatim context phrase

For three recurring generic clue shapes it also reduces a verbose draft to
the requested head phrase, but only when the extracted phrase is itself a
verbatim context phrase:

  * factual-person statements ("he/his/her ...") -> leading name run
  * bare role/title clues ("President X", "Sultan Y") -> associated place
  * bare pair/list clues ("A,B") -> shared label after of/from/in

It also removes a leading qualifier that the question line already states when
the remaining phrase is a verbatim context n-gram ("these Chinese businesses"
-> "laundries", "this funeral structure" -> "Pyre").

It never calls a model, never changes the selected entity, and deliberately
does NOT strip leading articles, shorten an organization/term to its first
word, or rewrite surface punctuation (case/hyphenation). Those decisions are
left to the bounded primary-model retry hook.
"""

from __future__ import annotations

import re
import unicodedata
from typing import Any

_MARKER = re.compile(r"^\[(?:DOC|TLE|PAR)\]$", re.IGNORECASE)
_DISCOURSE_LEAD_RE = re.compile(
    r"^(?:true|false|yes|no|correct|right|indeed)\s*[—–:]\s*(?P<tail>.+)$",
    re.IGNORECASE | re.DOTALL,
)
_ANSWER_LEAD_RE = re.compile(
    r"^(?:(?:the\s+)?(?:correct|final|short)\s+)?answer\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_DASH_GLOSS_RE = re.compile(r"\s+[—–]\s+(?P<gloss>.+)$", re.DOTALL)
_TRAILING_GLOSS_RE = re.compile(r"\s*[\(\[][^\(\)\[\]]{0,120}[\)\]]\s*[.!?]*$")
_ABBREV_RE = re.compile(r"\b[A-Za-z]\.([A-Za-z]\.)?$")
_NAME_TOKEN_RE = re.compile(r"^[A-ZÀ-Þ][A-Za-zÀ-ÿ'\-]+$")

_DEF_DEMO_RE = re.compile(
    r"\b(this|that|these|those|it|its|term|name|who|what|which|when|where|why|how)\b",
    re.IGNORECASE,
)
_PERSON_PRONOUN_RE = re.compile(r"\b(he|his|him|she|her|hers)\b", re.IGNORECASE)
_PERSON_DEMO_RE = re.compile(r"\b(this|whose)\b", re.IGNORECASE)


def _short_answer_requested(question: str) -> bool:
    return "return only the short answer" in (question or "").lower()


def _question_line(question: str) -> str:
    if "Question:" in question:
        return question.rsplit("Question:", 1)[1].strip()
    return (question or "").strip()


def _context_text(question: str) -> str:
    if "Context:" not in question:
        return ""
    after = question.split("Context:", 1)[1]
    if "Question:" in after:
        after = after.rsplit("Question:", 1)[0]
    return after


def _norm_token(tok: str) -> str:
    s = tok.lower()
    s = unicodedata.normalize("NFKD", s)
    s = "".join(ch for ch in s if not unicodedata.combining(ch))
    return "".join(ch for ch in s if ch.isalnum())


def _norm_text(text: str) -> str:
    return "".join(_norm_token(t) for t in text.split() if _norm_token(t))


def _context_keys(question: str) -> set[str]:
    """Return normalized n-gram keys for the supplied context (up to 6 tokens)."""
    ctx = _context_text(question)
    keys: set[str] = set()
    if not ctx:
        return keys

    for doc in re.split(r"\[DOC\]", ctx, flags=re.IGNORECASE):
        seq: list[str] = []
        for raw in doc.split():
            if _MARKER.match(raw.strip()):
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            norm = _norm_token(raw)
            if not norm:
                if seq:
                    max_n = min(6, len(seq))
                    for n in range(1, max_n + 1):
                        for i in range(len(seq) - n + 1):
                            keys.add("".join(seq[i : i + n]))
                    seq = []
                continue
            seq.append(norm)
        if seq:
            max_n = min(6, len(seq))
            for n in range(1, max_n + 1):
                for i in range(len(seq) - n + 1):
                    keys.add("".join(seq[i : i + n]))
    return keys


def _strip_code_fences_and_quotes(text: str) -> str:
    t = (text or "").strip()
    if t.startswith("```") and t.endswith("```") and len(t) > 6:
        inner = t[3:-3].strip()
        inner = re.sub(r"^[A-Za-z]+\s*\n", "", inner)
        if inner:
            t = inner
    for quote in ('"', "'", "`"):
        if len(t) >= 2 and t.startswith(quote) and t.endswith(quote):
            inner = t[1:-1].strip()
            if inner:
                t = inner
                break
    return t.strip()


def _strip_discourse_lead(text: str) -> str:
    match = _DISCOURSE_LEAD_RE.match(text)
    if match:
        tail = match.group("tail").strip()
        if tail:
            return tail
    return text


def _strip_answer_lead(text: str) -> str:
    return _ANSWER_LEAD_RE.sub("", text).strip()


def _strip_trailing_punct(text: str, keys: set[str]) -> str:
    t = text
    while True:
        if t.endswith(".") and not t.endswith("..") and len(t) > 2:
            if _ABBREV_RE.search(t):
                return t
            if re.search(r"\b(?:Jr|Sr|St|Dr|Mr|Mrs|Ms|Mt)\.$", t, re.IGNORECASE):
                return t
            nxt = t[:-1].rstrip()
            if _norm_text(nxt) in keys:
                t = nxt
                continue
            return t

        match = re.search(r"[!?]+$", t)
        if not match:
            return t
        run = match.group(0)
        nxt = t[: match.start()].rstrip()
        if not nxt:
            return t
        if len(run) >= 2 or _norm_text(nxt) in keys:
            t = nxt
            continue
        return t


def _strip_trailing_parenthetical(text: str, keys: set[str]) -> str:
    match = _TRAILING_GLOSS_RE.search(text)
    if not match:
        return text
    nxt = text[: match.start()].strip()
    if nxt and _norm_text(nxt) in keys:
        return nxt
    return text


def _strip_trailing_dash_gloss(text: str, keys: set[str]) -> str:
    match = _DASH_GLOSS_RE.search(text)
    if not match:
        return text
    before = text[: match.start()].strip()
    if before and _norm_text(before) in keys:
        return before
    return text


_LEADING_STRIP_KEEP = {
    "the", "a", "an", "sir", "lord", "dr", "mr", "mrs", "ms", "st", "prof",
    "of", "from", "in", "on", "at", "and", "or",
}


def _question_token_set(question_line: str) -> set[str]:
    """Return normalized single-token forms present in the question line."""
    return {
        _norm_token(tok)
        for tok in re.findall(r"[A-Za-z0-9]+", question_line or "")
        if _norm_token(tok)
    }


def _strip_question_echo(text: str, question_line: str, keys: set[str]) -> str:
    """Drop leading clue words that the question already states.

    Jeopardy-style clues often phrase the answer as a qualifier plus a head
    noun ("these Chinese businesses" -> "laundries", "this funeral structure"
    -> "Pyre"). When the model repeats the qualifier from the question, this
    pass removes it only if the remaining phrase is itself a verbatim context
    n-gram, so it never invents a new answer or changes the selected entity.
    It is deliberately leading-only and refuses to touch candidates whose full
    phrase already appears in the question line (those are either echo quotes
    or exact restatements that this lexical pass must not truncate).
    """
    t = " ".join((text or "").split())
    if not t:
        return t
    words = t.split()
    if len(words) <= 1:
        return t

    q_tokens = _question_token_set(question_line)
    if not q_tokens:
        return t
    if _norm_text(t) in _norm_text(question_line):
        return t

    cur = words
    while len(cur) > 1:
        lead = cur[0]
        remainder = " ".join(cur[1:])
        lead_norm = _norm_token(lead)
        if lead_norm in _LEADING_STRIP_KEEP:
            break
        if lead_norm in q_tokens and _norm_text(remainder) in keys:
            cur = cur[1:]
            continue
        break
    return " ".join(cur)


def _looks_factual_person_statement(question_line: str) -> bool:
    return bool(_PERSON_PRONOUN_RE.search(question_line)) and not bool(
        _PERSON_DEMO_RE.search(question_line)
    )


def _extract_person_name_run(text: str, keys: set[str]) -> str | None:
    words = text.split()
    if len(words) < 2:
        return None
    run: list[str] = []
    for word in words:
        cleaned = word.strip(".,;:!?\"'`")
        if cleaned and _NAME_TOKEN_RE.match(cleaned):
            run.append(cleaned)
            if len(run) == 3:
                break
        else:
            break
    for length in range(len(run), 1, -1):
        candidate = " ".join(run[:length])
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _looks_role_title_clue(question_line: str) -> bool:
    if not question_line or "," in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    words = question_line.split()
    if not (2 <= len(words) <= 6):
        return False
    return all(word[:1].isupper() for word in words if word)


def _extract_role_title_place(text: str, keys: set[str]) -> str | None:
    matches = re.findall(r"\bof\s+([A-Z][A-Za-z]+)", text)
    for candidate in reversed(matches):
        if _norm_text(candidate) in keys:
            return candidate
    match = re.search(r"\bfrom\s+([A-Z][A-Za-z]+)", text)
    if match and _norm_text(match.group(1)) in keys:
        return match.group(1)
    return None


def _looks_pair_list_clue(question_line: str) -> bool:
    if not question_line or "," not in question_line or _DEF_DEMO_RE.search(question_line):
        return False
    parts = [p.strip() for p in question_line.split(",") if p.strip()]
    if not (2 <= len(parts) <= 5):
        return False
    for part in parts:
        words = part.split()
        if not (1 <= len(words) <= 5):
            return False
        if not all(word[:1].isupper() for word in words if word):
            return False
    return True


def _extract_pair_list_label(text: str, keys: set[str]) -> str | None:
    match = re.search(r"\b(?:from|of|in)\s+([A-Z][A-Za-z]+)(?=\s+(?:and|,)|$)", text)
    if match:
        candidate = match.group(1)
        if _norm_text(candidate) in keys:
            return candidate
    return None


def _clean(text: str, question: str) -> str:
    t = " ".join((text or "").split())
    if not t:
        return t

    keys = _context_keys(question)

    t = _strip_code_fences_and_quotes(t)
    t = _strip_discourse_lead(t)
    t = _strip_answer_lead(t)

    q = _question_line(question)

    # Iteratively remove one trailing surface wrapper at a time. Every removal
    # is gated on the remaining phrase being a verbatim context n-gram, so the
    # pass never changes the selected entity.
    for _ in range(10):
        prev = t
        t = _strip_trailing_punct(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_parenthetical(t, keys)
        if t != prev:
            continue
        t = _strip_trailing_dash_gloss(t, keys)
        if t != prev:
            continue
        break

    # Remove a leading qualifier already stated in the clue (for example
    # "Chinese laundries" -> "laundries", "funeral pyre" -> "pyre").
    t = _strip_question_echo(t, q, keys)

    if _looks_factual_person_statement(q) and len(t.split()) > 3:
        extracted = _extract_person_name_run(t, keys)
        if extracted:
            t = extracted
    elif _looks_role_title_clue(q):
        extracted = _extract_role_title_place(t, keys)
        if extracted:
            t = extracted
    elif _looks_pair_list_clue(q):
        extracted = _extract_pair_list_label(t, keys)
        if extracted:
            t = extracted

    return " ".join(t.split())


async def before_final(candidate: str, ctx: Any) -> dict | None:
    """Clean a final short answer into its bare requested surface form."""
    original = (candidate or "").strip()
    if not original or not _short_answer_requested(ctx.question):
        return None

    state = ctx.state.setdefault("short_answer_clean", {})
    state["replaced_this_turn"] = False

    cleaned = _clean(original, ctx.question)
    if cleaned and cleaned != original:
        state["replaced_this_turn"] = True
        ctx.trace.event(
            "short_answer_clean_replace",
            candidate=original,
            cleaned=cleaned,
        )
        return {"action": "replace", "answer": cleaned}
    return None
